window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0135", [{"word":"descendant","ipa_uk":"/dɪˈsendənt/","ipa_us":"/dɪˈsendənt/","definition_zh":"后代；后裔；（物种、语言等的）衍生者；由早先事物发展而来的产物","definition_en":"a person, animal or thing that comes from an earlier ancestor, species or source","core_image":"一条向下的石阶从祖辈的门口铺到孙辈的脚下，每一级都稳稳踩在前一级上","scene":"族谱摊在长桌上，最末一页写着一个刚出生的名字，The archivist points to the youngest descendant in the register.","sceneCN":"这里 descendant 指「由祖先一脉相传下来的后人」（第 1 个义项：直系血统上的后代）；句意为档案员指着族谱里最年幼的那位后代。图中可辨识物件：摊开的族谱、长桌、指页的手指、墨迹未干的名字。","pos":[{"tag":"n.","zh":"后代；后裔；衍生物"},{"tag":"adj.","zh":"（罕用）下降的；向下的"}],"collocations":[{"phrase":"direct descendant","zh":"直系后代"},{"phrase":"lineal descendant","zh":"直系后裔"},{"phrase":"remote descendant","zh":"远代后裔"},{"phrase":"surviving descendant","zh":"在世的后代"},{"phrase":"descendant species","zh":"衍生物种"},{"phrase":"a descendant of","zh":"……的后代"}],"forms":[{"label":"复数","form":"descendants"}],"derivatives":[{"word":"descend","pos":"v.","zh":"下降；下来；传下"},{"word":"descent","pos":"n.","zh":"下降；血统；斜坡"},{"word":"condescend","pos":"v.","zh":"屈尊；带着优越感地俯就"},{"word":"ascend","pos":"v.","zh":"上升；攀登"},{"word":"transcend","pos":"v.","zh":"超越；超出"}],"senses":[{"no":"01","title":"A person born of an ancestor","titleCN":"祖先血脉上的后人","definition":"a person who is descended from a particular ancestor","definitionCN":"从某位祖先一脉传下来的人","example":"Every descendant of the founder received a copy of the will.","exampleCN":"创始人的每一位后代都拿到了一份遗嘱副本。","why":"descendant is the present participle of descend, so the person is literally one who is going down the family line from the ancestor.","whyCN":"descendant 是 descend 的现在分词，字面就是「沿着家族这条线从祖先往下走的人」。"},{"no":"02","title":"The later members of a line, taken together","titleCN":"一族后人（集合意义）","definition":"all the later members of a family regarded as one body","definitionCN":"把某一家族后来各代的人合起来看","example":"The estate is now run by his descendants as a working farm.","exampleCN":"这座庄园现在由他的后人当作农场经营。","why":"the singular form can name a group because a line of descent is thought of as one stream rather than separate persons.","whyCN":"单数形式能指一群人，因为「一脉」在说话人心里是一股水流，而不是一个个孤立的人。"},{"no":"03","title":"A species derived from an earlier one","titleCN":"由早期物种演化而来的物种","definition":"an organism that has evolved from an earlier species","definitionCN":"由更早的物种演化出来的生物","example":"Modern maize is a descendant of a wild grass from southern Mexico.","exampleCN":"现代玉米是墨西哥南部一种野草的衍生种。","why":"the family metaphor carries over to evolution: a species stands in the same relation to its ancestor as a child to a parent.","whyCN":"家族的比喻被搬到演化上：一个物种与其祖先的关系，正如孩子与父母的关系。"},{"no":"04","title":"A language derived from another","titleCN":"由另一语言分化出的语言","definition":"a language that developed from an earlier parent language","definitionCN":"由更早的母语分化发展出来的语言","example":"French, Spanish and Italian are descendants of Latin.","exampleCN":"法语、西班牙语和意大利语都是拉丁语的衍生语言。","why":"linguists borrowed the genealogy image directly, so a daughter language is called a descendant rather than an offshoot.","whyCN":"语言学家直接借用了谱系意象，因此子语言被称作 descendant，而不是旁枝。"},{"no":"05","title":"A thing copied or developed from an earlier form","titleCN":"由先前形态发展或复制而来的事物","definition":"an object or version that has been developed from an earlier one","definitionCN":"由更早的物件或版本发展出来的东西","example":"This compact model is a descendant of the first field radio.","exampleCN":"这款轻便机型是最早的野战电台的后继型号。","why":"when a design is changed step by step, each stage looks like a child of the one before, so the word spreads from people to products.","whyCN":"设计一步步改动时，每一阶段都像前一阶段的子代，于是这个词从人扩展到产品。"},{"no":"06","title":"A legal heir in the direct line","titleCN":"法定直系继承人","definition":"in law, a person entitled to inherit because of direct descent","definitionCN":"法律上因直系血缘而有继承资格的人","example":"The court ruled that the nephew was not a descendant under the statute.","exampleCN":"法院裁定，这位侄子在该法条下不属于直系后代。","why":"inheritance law needs an exact word for the direct line, so the everyday family sense is narrowed into a legal category.","whyCN":"继承法需要给直系这条线一个精确的词，于是日常的家族义被收窄为法律类别。"},{"no":"07","title":"Going downward in direction","titleCN":"方向朝下的","definition":"moving or sloping downward, as in the rare adjective use","definitionCN":"向下移动或向下倾斜的（罕用形容词义）","example":"A descendant branch of the river drops toward the marsh.","exampleCN":"河道一条向下的支流朝沼泽落去。","why":"the adjective keeps the oldest physical sense of de- plus scandere, climbing down, which the noun use later overshadowed.","whyCN":"形容词保留了 de- 加 scandere「向下爬」这层最古老的物理义，后来被名词用法盖过。"},{"no":"08","title":"A later result of an event or idea","titleCN":"事件或想法在后世结出的结果","definition":"something that follows from and is shaped by an earlier event or idea","definitionCN":"由更早的事件或观念引出并受其塑造的事物","example":"The current subsidy scheme is a descendant of wartime rationing.","exampleCN":"现行的补贴方案是战时配给制的后续产物。","why":"the idea of inheritance is loosened until anything shaped by an earlier thing can be called its descendant.","whyCN":"「继承」的观念被放宽，凡是受早先事物塑造的东西，都可称作它的后代。"}],"etymology":{"intro":{"en":"Descendant is the English present participle of descend, built on Latin scandere 'to climb' with the prefix de- 'down'. Dates are approximate.","cn":"descendant 是 descend 的英语现在分词形式，底层是拉丁 scandere「攀登」加前缀 de-「向下」。年代均为约数。"},"items":[{"era":"LATIN SCANDERE","en":"Scandere meant 'to climb'. Its deeper pre-Latin base is a reconstructed form, and the usual suggestion of a root meaning 'to leap' is a hypothesis rather than an attested fact.","cn":"scandere 意为「攀登」。它在拉丁语之前的词基属重构形式；通常把它联系到一个意为「跳」的词根，这只是假说，并非有书证的事实。"},{"era":"LATIN DESCENDERE","en":"De- 'down' plus scandere gave descendere 'to climb down, go down'. Classical Latin already used it for coming down from a stock or source.","cn":"de-「向下」加 scandere 构成 descendere「爬下来、下去」。古典拉丁语已用它表示「出自某一血统或来源」。"},{"era":"LATIN DESCENDENS","en":"The present participle descendens, genitive descendentis, meant 'going down' and also 'deriving from'.","cn":"现在分词 descendens（属格 descendentis）意为「向下的」，也有「源自」的意思。"},{"era":"FRENCH DESCENDANT","en":"Old French took the participle as descendant and used it of a person who comes from a stock.","cn":"古法语把这个分词写作 descendant，用来指由某一血统传下来的人。"},{"era":"ENGLISH ENTRY","en":"English adopted descendant in the fourteenth century, first as an adjective and then as a noun for the person.","cn":"英语在 14 世纪引入 descendant，先作形容词，后作指人的名词。"},{"era":"SPELLING VARIATION","en":"Descendent also appears, modelled on the Latin stem; source uncertain which spelling entered English first, and descendant is now the standard form.","cn":"也见 descendent 这一拼法，是照着拉丁词干造的；两种拼法孰先进入英语来源不确定，现在以 descendant 为标准。"}]},"similar":{"note":{"en":"The first group holds forms of the same Latin verb that are easily confused in spelling; the second holds words for later family members that do not share the root.","cn":"第一组是同一个拉丁动词的各形态，拼写极易混淆；第二组指同样表示后人的词，但词根不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"descendent","ipa":"/dɪˈsendənt/","tag":"variant spelling","definition":"An alternative spelling of the same word, shaped on the Latin stem; it is not a separate meaning and is now less standard.","definitionCN":"同一个词的另一种拼法，照着拉丁词干写成；并非另一个词义，如今较不规范。"},{"word":"descend","ipa":"/dɪˈsend/","tag":"the verb","definition":"The verb meaning to go down or to come from an ancestor; the noun names the person, the verb names the movement.","definitionCN":"动词，意为下降或传自某祖先；名词指人，动词指动作。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"the noun of the movement","definition":"The act of going down, a downward slope, or the fact of being related by blood; it never names the person.","definitionCN":"指下降的动作、下坡，或血缘关系这一事实；从不指人。"},{"word":"condescend","ipa":"/ˌkɒndɪˈsend/","tag":"same verb, social sense","definition":"To lower oneself to deal with inferiors; the downward image survives as social slumming rather than family descent.","definitionCN":"屈尊与地位低的人打交道；向下的意象保留为社会意义上的俯就，而非家族传承。"}]},{"heading":"NEAR MEANING","entries":[{"word":"offspring","ipa":"/ˈɒfsprɪŋ/","tag":"the immediate child","definition":"A child or the young of an animal, usually the direct product of a parent rather than a remote generation.","definitionCN":"子女或动物的幼仔，通常指父母的直接产物，而非隔了很多代的后人。"},{"word":"progeny","ipa":"/ˈprɒdʒəni/","tag":"formal collective","definition":"Descendants considered as a group, often with a tone of lineage or stock; more formal than descendant.","definitionCN":"把后代作为一个群体来看，常带血统或族系的意味；比 descendant 正式。"},{"word":"heir","ipa":"/eə/","tag":"the one who inherits","definition":"A person who receives property or a title; descent is one route to being an heir, but inheritance is the point.","definitionCN":"接受财产或头衔的人；血缘是成为继承人的一条途径，但重点在继承。"},{"word":"ancestor","ipa":"/ˈænsestə/","tag":"the other direction","definition":"The person from whom one is descended; the mirror image of descendant on the same family line.","definitionCN":"自己由之传下来的人；是同一条家族线上 descendant 的镜像。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real family of words and the phrases the word actually keeps.","cn":"正常联想：真实的拉丁构件、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"de- 'down' + scandere 'climb' = one who climbs down the family tree from the ancestor.","cn":"de-「向下」+ scandere「爬」= 沿家族树从祖先往下爬的人。"},{"en":"The same verb gives descend, descent, condescend, ascend and transcend.","cn":"同一个动词还给出 descend、descent、condescend、ascend、transcend。"},{"en":"-ant marks the person, as in applicant, attendant and occupant.","cn":"-ant 标记「人」，如 applicant、attendant、occupant。"},{"en":"The word usually follows direct, lineal or remote, which grade how far back the line runs.","cn":"这个词常跟在 direct、lineal、remote 之后，用来说明这条线往上追得多远。"},{"en":"In biology and linguistics it pairs with ancestor as the standard term for a derived form.","cn":"在生物学与语言学里，它与 ancestor 配对，是表示「衍生形态」的标准词。"}],"abstract":[{"en":"Picture a staircase where each step carries a name carved by the step above it.","cn":"想象一架楼梯，每一级都刻着由上一级刻下的名字。"},{"en":"Picture a river that splits again and again, yet every channel still carries the same water.","cn":"想象一条不断分岔的河，每一道支流里流的仍是同一股水。"},{"en":"Picture a seed packet labelled with the name of the garden it came from.","cn":"想象一只种子袋，标签上写着它来自的那座园子。"}]},"examples":[{"en":"She is a direct descendant of the family that built the mill.","cn":"她是建造这座磨坊的家族的直系后代。"},{"en":"The languages of the region are all descendants of one older tongue.","cn":"这一地区的语言都是同一种更古老语言的衍生语言。"},{"en":"Today's lightweight laptop is a descendant of machines that filled a whole room.","cn":"今天的轻薄笔记本是那些占满整间屋子的机器的后代。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「得森登特」听成「得孙等它」——祖先往下等，等到孙子这一代，就是后代。de 向下，scend 爬，向下爬出来的就是后人。","word":"descendant"},"root":"拉丁 scandere「攀登」加 de-「向下」构成 descendere「爬下来、下来」，其现在分词 descendens 经古法语 descendant 进入英语。scandere 在拉丁语之前的词基属重构形式，通常联系的「跳」义只是假说。","sensesIntro":{"en":"Eight senses follow one downward line: first the person, then the group, then the derived species, language and object, then the legal heir, the rare downward adjective and finally any later result.","cn":"八个义项沿同一条向下的线展开：先是人，再是一群人，再是衍生的物种、语言与物件，然后是法定继承人、罕用的「向下」形容词，最后是任何后世结出的结果。"},"semanticMap":{"core":{"en":"CORE IMAGE: a staircase running down from an ancestor's door to a child's feet.","cn":"核心意象：一架从祖先门口向下铺到孩子脚下的楼梯。"},"chain":["BLOOD LINE","LATER FAMILY","NEW SPECIES","NEW LANGUAGE","DERIVED OBJECT","LATER RESULT"],"branches":[{"senses":"义项 01 · 02","en":"ONE PERSON AND THE WHOLE LINE: the same word names a single heir and the group of later members, because both sit below the ancestor.","cn":"一个人与整条线：同一个词既指单个后人，也指后来全体成员，因为两者都位于祖先之下。"},{"senses":"义项 03 · 04","en":"SPECIES AND LANGUAGE: evolution and linguistics both reuse the family tree, so a new species or a daughter language is a descendant.","cn":"物种与语言：演化与语言学都借用了家族树，因此新物种或子语言都叫 descendant。"},{"senses":"义项 05","en":"DERIVED OBJECT: a revised design inherits features from its earlier model the way a child inherits traits.","cn":"衍生物件：改过的设计从旧型号继承特征，正如孩子继承父母的性状。"},{"senses":"义项 06","en":"LEGAL HEIR: the direct line is narrowed into a person with a right to inherit.","cn":"法定继承人：直系这条线被收窄为有继承权的人。"},{"senses":"义项 07 · 08","en":"DOWNWARD AND AFTERWARD: the physical sense of going down survives in the adjective, while the temporal sense of coming after survives in the figurative result.","cn":"向下与在后：向下的物理义留在形容词里，而「在其后」的时间义留在比喻性的结果里。"}]},"affixes":{"intro":{"en":"Descendant can be read from a Latin prefix, a Latin verb stem and an English participial ending.","cn":"descendant 可以按拉丁前缀、拉丁动词词干与英语分词词尾逐段读出。"},"latinIntro":{"en":"Latin scandere supplies the climbing image to descend, descent, ascend, transcend and the ladder word scale, while de- fixes the direction as downward.","cn":"拉丁 scandere 为 descend、descent、ascend、transcend 以及表示梯子的 scale 提供「攀爬」意象，de- 则把方向定为向下。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'down from')","meaning":"down; away from","meaningCN":"向下；离开","example":"The prefix turns climbing into climbing down.","exampleCN":"这个前缀把「往上爬」变成「往下爬」。"},{"word":"scand-","structure":"scandere (Latin verb, 'to climb')","meaning":"to climb","meaningCN":"攀登","example":"The stem supplies the upward motion that de- reverses.","exampleCN":"这个词干提供向上的动作，再由 de- 反转。"},{"word":"-ant","structure":"-ant (English participial and personal ending)","meaning":"one doing or being","meaningCN":"正在做或处于某状态的人或物","example":"The ending also marks applicant and occupant.","exampleCN":"这个结尾也见于 applicant 与 occupant。"},{"word":"descend","structure":"de- + scandere","meaning":"to go down; to come from a stock","meaningCN":"下降；传自某一血统","example":"The path descends to the river.","exampleCN":"小路向下通向河边。"},{"word":"descent","structure":"descend + -t (noun of action)","meaning":"a going down; lineage","meaningCN":"下降；血统","example":"The descent from the ridge took two hours.","exampleCN":"从山脊下撤用了两个小时。"},{"word":"condescend","structure":"con- (together) + descend","meaning":"to lower oneself toward others","meaningCN":"屈尊俯就","example":"He condescended to explain the rule.","exampleCN":"他屈尊解释了这条规则。"},{"word":"ascend","structure":"ad- (up to) + scandere","meaning":"to climb up","meaningCN":"上升；攀登","example":"The balloon ascended into cloud.","exampleCN":"气球升入云层。"},{"word":"transcend","structure":"trans- (across, beyond) + scandere","meaning":"to climb beyond a limit","meaningCN":"超越界限","example":"The argument transcends national boundaries.","exampleCN":"这一论证超越了国界。"},{"word":"scale","structure":"scala (Latin 'ladder'), from scandere","meaning":"a ladder; a graded series","meaningCN":"梯子；分级序列","example":"The map is drawn to a scale of one to fifty thousand.","exampleCN":"这幅地图按五万分之一的比例尺绘制。"}],"latinEntries":[{"word":"descendere","structure":"de- + scandere (Latin verb)","meaning":"to climb down; to be derived from","meaningCN":"爬下来；源自"},{"word":"descensus","structure":"descendere, past participle (Latin noun)","meaning":"a going down; a descent","meaningCN":"下降；下行"},{"word":"ascendere","structure":"ad- + scandere (Latin verb)","meaning":"to climb up, mount","meaningCN":"攀登；上升"},{"word":"scala","structure":"from scandere (Latin noun)","meaning":"a ladder, steps","meaningCN":"梯子；台阶"}],"derivatives":[{"word":"descendants","structure":"descendant + -s (plural)","meaning":"the later members of a line","meaningCN":"后代（复数）"},{"word":"descended","structure":"descend + -ed (past participle)","meaning":"having come down or come from a stock","meaningCN":"已下来；传自某血统"}]}},{"word":"lineage","ipa_uk":"/ˈlɪniɪdʒ/","ipa_us":"/ˈlɪniɪdʒ/","definition_zh":"血统；世系；家系；谱系；一脉相承的传承线","definition_en":"the line of descent from an ancestor, or a continuous line of transmission","core_image":"一根从祖辈手里递下来的麻线，线上串着代表每一代人的木珠","scene":"樟木箱里摊着一卷手抄家谱，The elder traces the lineage back to a boatman who landed three centuries earlier.","sceneCN":"这里 lineage 指「一脉相承的血统世系」（第 1 个义项：连续不断的直系传承线）；句意为长者把这条世系一直追溯到三个世纪前靠岸的船夫。图中可辨识物件：手抄家谱、樟木箱、麻线装订、老花镜。","pos":[{"tag":"n.","zh":"血统；世系；家系；谱系"}],"collocations":[{"phrase":"maternal lineage","zh":"母系世系"},{"phrase":"paternal lineage","zh":"父系世系"},{"phrase":"trace one's lineage","zh":"追溯自己的世系"},{"phrase":"a long lineage of","zh":"一脉悠长的……传承"},{"phrase":"lineage group","zh":"世系群"},{"phrase":"lineage of manuscripts","zh":"抄本的传承谱系"}],"forms":[{"label":"复数","form":"lineages"}],"derivatives":[{"word":"lineal","pos":"adj.","zh":"直系的；沿直线的"},{"word":"line","pos":"n./v.","zh":"线；排成一线"},{"word":"linear","pos":"adj.","zh":"线性的；直线的"},{"word":"align","pos":"v.","zh":"使成一条直线；对齐"},{"word":"lineages","pos":"n.","zh":"世系（复数形式）"},{"word":"lineally","pos":"adv.","zh":"按直系方式地"}],"senses":[{"no":"01","title":"A continuous line of descent","titleCN":"连续的直系传承线","definition":"the unbroken line of descent from a particular ancestor","definitionCN":"自某位祖先起未曾中断的直系传承","example":"The family can trace its lineage to a single village on the coast.","exampleCN":"这个家族能把世系一直追溯到沿海的一座村子。","why":"lineage begins as a line drawn through generations, so the core sense is the unbroken thread itself rather than any one person on it.","whyCN":"lineage 起初是穿过各代画出的一条线，核心因此是那根不断的线，而不是线上的某个人。"},{"no":"02","title":"A family or stock as a descended group","titleCN":"作为传承群体的家族或族系","definition":"a family or stock regarded as a line of related people","definitionCN":"被看作一条相关人群线的家族或族系","example":"Two lineages have shared the valley for as long as anyone remembers.","exampleCN":"在所有人记忆所及的年代里，一直有两个族系共用这座山谷。","why":"people speak of a lineage when they think of the family as a body that persists through time, not as a list of names.","whyCN":"人们说某个 lineage，是把家族当成一个穿越时间延续的群体，而不是一串名字。"},{"no":"03","title":"A record of ancestry","titleCN":"世系的记载","definition":"a written or oral record setting out a line of ancestors","definitionCN":"以书面或口传形式列出一串祖先的记录","example":"The monastery kept a lineage of its abbots in the margin of the chronicle.","exampleCN":"修道院在编年史的页边记下了历任院长的传承。","why":"once a line is written down, the record itself comes to be called the lineage, as if paper could hold the thread.","whyCN":"一条线一旦被写下来，记录本身也被称作 lineage，仿佛纸能握住那根线。"},{"no":"04","title":"A breeding line in animals or plants","titleCN":"动植物的育种品系","definition":"a line of animals or plants maintained through controlled breeding","definitionCN":"通过定向繁育维持下来的动植物品系","example":"The seed bank preserves a lineage of drought-tolerant barley.","exampleCN":"种子库保存着一个耐旱大麦品系。","why":"breeders think in lines because each generation is selected from the one before, which is the same shape as family descent.","whyCN":"育种者按「线」思考，因为每一代都从上一代选出，这与家族传承形状相同。"},{"no":"05","title":"A line of transmission in texts or ideas","titleCN":"文本或思想的传承线","definition":"a sequence of copies, versions or ideas derived one from another","definitionCN":"一份份抄本、版本或观念依次由前者派生出的序列","example":"Scholars reconstructed the lineage of the three surviving manuscripts.","exampleCN":"学者们重建了三份存世抄本的传承谱系。","why":"philology borrowed the family model: a copy descends from an exemplar just as a child descends from a parent.","whyCN":"文献学借用了家族模型：抄本从祖本传下，正如孩子从父母传下。"},{"no":"06","title":"A unilineal descent group in anthropology","titleCN":"人类学中的单系继嗣群","definition":"a group whose members trace descent through one parent only","definitionCN":"成员只通过父系或只通过母系追溯血统的群体","example":"The lineage owns the terraces and decides who may marry whom.","exampleCN":"这个继嗣群拥有梯田，并决定谁可以与谁通婚。","why":"anthropology needed a technical term for a corporate descent group, and lineage already carried the unbroken-line idea.","whyCN":"人类学需要一个术语来指作为法人单位的继嗣群，而 lineage 本就带着「不断的线」这层意思。"},{"no":"07","title":"A pedigree certificate","titleCN":"血统证明书","definition":"a document certifying the ancestry of a person or animal","definitionCN":"证明人或动物血统来源的文书","example":"The mare's lineage was printed on a single sheet of stiff paper.","exampleCN":"这匹母马的血统谱印在一张硬纸上。","why":"where ancestry is bought and sold, the paper that proves the line takes the name of the line itself.","whyCN":"在血统可以买卖的地方，证明这条线的纸就沿用了这条线的名字。"},{"no":"08","title":"Any sequence of development","titleCN":"任何前后相续的发展序列","definition":"a series of related stages or products following one from another","definitionCN":"一组前后相续的相关阶段或产品","example":"The new software has a lineage reaching back to a 1970s drawing program.","exampleCN":"这款新软件的源流可以上溯到 20 世纪 70 年代的一个绘图程序。","why":"the family image is so elastic that any series of versions can be given a lineage, even machines.","whyCN":"家族的意象极有弹性，任何一串版本，哪怕是机器，都能被赋予一个 lineage。"}],"etymology":{"intro":{"en":"Lineage comes through Old French from Latin linea 'line, thread', a noun built on linum 'flax'. Dates are approximate.","cn":"lineage 经古法语来自拉丁 linea「线、细绳」，该名词建于 linum「亚麻」之上。年代均为约数。"},"items":[{"era":"LATIN LINUM","en":"Linum meant 'flax', the plant whose fibres were twisted into thread. The deeper origin of the word is not established.","cn":"linum 意为「亚麻」，这种植物的纤维被捻成线。这个词更深的来源未得到证明。"},{"era":"LATIN LINEA","en":"Linea, literally 'a linen thread', came to mean any line, including a line drawn on paper and a boundary.","cn":"linea 字面是「一根麻线」，后来指任何线，包括纸上画的线与边界。"},{"era":"OLD FRENCH LIGNE","en":"Old French ligne kept the sense of a line and also developed the idea of a line of descent.","cn":"古法语 ligne 保留了「线」的意思，并发展出「血统线」的观念。"},{"era":"OLD FRENCH LIGNAGE","en":"Lignage named the body of people descended from one stock, adding a collective suffix to ligne.","cn":"lignage 指由同一族系传下的一群人，是在 ligne 之后加集合性后缀构成的。"},{"era":"ENGLISH LINEAGE","en":"English borrowed lineage in the fourteenth century for both the descent line and the family holding it.","cn":"英语在 14 世纪借入 lineage，既指血统线，也指沿这条线延续的家族。"},{"era":"SENSE EXTENSION","en":"By the nineteenth century the word was extended to breeding lines and to manuscript traditions, where descent is reconstructable but not biological.","cn":"到 19 世纪，这个词扩展到育种品系与抄本传统——那里的传承可以重建，却不是生物性的。"}]},"similar":{"note":{"en":"The first group turns on the same Latin thread and is easily mixed up; the second lists other words for ancestry that come from different roots.","cn":"第一组共用同一个拉丁「线」词，极易混淆；第二组是同样表示血统、但词根不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"line","ipa":"/laɪn/","tag":"the plain line","definition":"A mark, a row or a connection; the everyday word, with no special claim about ancestors.","definitionCN":"指痕迹、一行或一种联系；是日常用词，对祖先没有专门含义。"},{"word":"lineal","ipa":"/ˈlaɪniəl/","tag":"adjective of the direct line","definition":"Descended in a direct line, as in a lineal heir; an adjective, where lineage is the noun.","definitionCN":"指直系传承的，如直系继承人；它是形容词，lineage 是名词。"},{"word":"linear","ipa":"/ˈlɪniə/","tag":"straight, not genealogical","definition":"Arranged in or along a line; it describes shape or order and says nothing about descent.","definitionCN":"指沿直线排列的；描述形状或次序，与血统无关。"},{"word":"linage","ipa":"/ˈlaɪnɪdʒ/","tag":"false friend by spelling","definition":"An obsolete word for the number of lines in a piece of writing, paid by the line; it looks like lineage but means something else.","definitionCN":"一个废弃词，指文稿的行数（按行计酬）；它看起来像 lineage，意思却完全不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ancestry","ipa":"/ˈænsestri/","tag":"all the ancestors","definition":"The whole body of one's forebears rather than the connecting line; it answers who, not how the line runs.","definitionCN":"指一个人全部的先辈，而非那条连接线；它回答「是谁」，而不是「线怎么走」。"},{"word":"pedigree","ipa":"/ˈpiːdɪɡriː/","tag":"the recorded table","definition":"A recorded table of ancestors, especially for animals; the document sense of lineage, usually drawn as a chart.","definitionCN":"尤其指动物的血统记录表；相当于 lineage 的文书义，常画成图表。"},{"word":"descent","ipa":"/dɪˈsent/","tag":"the fact of coming from","definition":"The relation of being descended from a person or group, viewed as a fact rather than as a continuing thread.","definitionCN":"指与某人或某群体有血缘关系这一事实，被看作事实而非延续的线。"},{"word":"genealogy","ipa":"/dʒiˈælədʒi/","tag":"the study and the chart","definition":"The study of family lines, or a chart of them; it names the discipline, not the family itself.","definitionCN":"指对家族线的研究，或这样的图表；它指这门学问，而非家族本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin word for thread, the words built on it and the collocations that keep it in use.","cn":"正常联想：真正表示「线」的拉丁词、由它构成的词，以及让这个词保持活力的搭配。"},"normal":[{"en":"linea 'thread' + -age 'collective body' = the body of people on one thread.","cn":"linea「线」+ -age「集合体」= 串在同一根线上的一群人。"},{"en":"Latin linum 'flax' also gives linen and line, because thread was made of flax.","cn":"拉丁 linum「亚麻」还给出 linen 与 line，因为线是用亚麻捻成的。"},{"en":"The usual phrases are maternal lineage, paternal lineage and trace one's lineage.","cn":"常见搭配是母系世系、父系世系与追溯世系。"},{"en":"-age builds a collective noun here, much as it does in baggage and mileage.","cn":"这里的 -age 构成集合名词，作用和 baggage、mileage 里的 -age 一样。"},{"en":"In anthropology the word pairs with clan and descent group as a technical unit.","cn":"在人类学里，这个词与「氏族」「世系群」并列为专业单位。"}],"abstract":[{"en":"Picture a thread with one wooden bead for every generation, each bead tied by the same knot.","cn":"想象一根线上每一代各有一颗木珠，每颗珠子都打着同一个结。"},{"en":"Picture a margin note that repeats a name for four hundred years without changing a letter.","cn":"想象页边的一行批注，四百年里反复写同一个名字，一个字母都没改。"},{"en":"Picture a single fibre pulled from a page and held up against the light, still unbroken.","cn":"想象从纸页里抽出一根纤维，对着光举起来，依旧没有断。"}]},"examples":[{"en":"Her maternal lineage is recorded in a parish register from the 1680s.","cn":"她的母系世系记在 17 世纪 80 年代的一本教区登记簿里。"},{"en":"The lineage of these manuscripts can be traced through the scribal notes.","cn":"这些抄本的传承谱系可以靠抄写者留下的批注追溯。"},{"en":"A lineage of herders has moved this herd through the same pass each spring.","cn":"一个牧人世系每年春天都赶着这群牲畜走同一道山口。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「来尼奇」听成「来你继」——一代来、你来继，线不断，就是世系。line 是线，lineage 就是那条代代相传的线。","word":"lineage"},"root":"古法语 lignage，源自 ligne「线」，再上为拉丁 linea「线、麻线」，其基础是 linum「亚麻」。与英语 line、lineal、linear 同族。","sensesIntro":{"en":"Eight senses all hang on one thread: the descent line, the family on it, the record of it, the breeding and manuscript lines that copy its shape, the clan unit, the certificate and finally any sequence of versions.","cn":"八个义项都挂在一根线上：血统线、线上的家族、对这条线的记载、模仿这条线形状的育种线与抄本线、作为单位的继嗣群、证明文书，最后是任何版本的序列。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hemp thread strung with one bead for each generation.","cn":"核心意象：一根麻线，每一代人串一颗珠。"},"chain":["UNBROKEN THREAD","FAMILY STOCK","WRITTEN RECORD","BREEDING LINE","TEXT TRADITION","SERIES OF VERSIONS"],"branches":[{"senses":"义项 01 · 02","en":"THREAD AND FAMILY: the line itself and the people who occupy it are two views of one object.","cn":"线与家族：线本身与站在线上的两群人是同一物的两种看法。"},{"senses":"义项 03","en":"RECORD: once the line is written down, the paper replaces the thread as the thing people consult.","cn":"记载：线一旦写下，纸就取代线，成为人们查阅的对象。"},{"senses":"义项 04","en":"BREEDING: selection across generations copies the shape of family descent without any family.","cn":"育种：逐代选育复制了家族传承的形状，却并没有家族。"},{"senses":"义项 05","en":"TEXT TRADITION: copies descend from an exemplar, so philology speaks of a manuscript lineage.","cn":"文本传承：抄本自祖本传下，因此文献学说「抄本谱系」。"},{"senses":"义项 06 · 07 · 08","en":"INSTITUTION, PAPER AND PRODUCT: the clan unit, the pedigree sheet and the version series each turn the thread into an object that can be owned or traced.","cn":"制度、纸与产品：继嗣群、血统证明书与版本序列，都把这条线变成可以拥有或追溯的对象。"}]},"affixes":{"intro":{"en":"Lineage is a Latin noun for a thread plus a French collective ending, so it can be read as 'the body belonging to one line'.","cn":"lineage 是表示「线」的拉丁名词加法语集合后缀，可以读作「属于同一条线的一群」。"},"latinIntro":{"en":"Latin linea and linum also give line, lineal, linear, linen and align, all through the image of a stretched thread.","cn":"拉丁 linea 与 linum 还给出 line、lineal、linear、linen、align，全都围绕「拉直的一根线」这一意象。"},"items":[{"word":"line-","structure":"linea (Latin noun, 'line, thread')","meaning":"line; thread","meaningCN":"线；细绳","example":"The stem supplies the image of a continuous thread.","exampleCN":"这个词干提供「连续不断的线」这一意象。"},{"word":"-age","structure":"-age (French collective suffix)","meaning":"a body or set of","meaningCN":"一群；一组","example":"The suffix also forms baggage and mileage.","exampleCN":"这个后缀还构成 baggage 与 mileage。"},{"word":"line","structure":"linea through French","meaning":"a mark or row; a connection","meaningCN":"线；一行；联系","example":"Draw a line from the well to the gate.","exampleCN":"从井边到大门画一条线。"},{"word":"lineal","structure":"line + -al (relating to)","meaning":"belonging to the direct line","meaningCN":"直系的","example":"A lineal heir takes before a collateral one.","exampleCN":"直系继承人在旁系之前继承。"},{"word":"linear","structure":"line + -ar (of the nature of)","meaning":"arranged along a line","meaningCN":"线性的；沿直线的","example":"The village grew in a linear pattern along the road.","exampleCN":"村子沿道路呈线状发展。"},{"word":"linen","structure":"linum (Latin 'flax') + -en","meaning":"cloth woven from flax","meaningCN":"亚麻布","example":"The register was bound in linen.","exampleCN":"这本登记簿用亚麻布装订。"},{"word":"align","structure":"a ligne (French 'into line')","meaning":"to bring into a straight line","meaningCN":"使成一线；对齐","example":"Align the poles with the ridge.","exampleCN":"把杆子与山脊对齐。"},{"word":"lineage","structure":"ligne + -age","meaning":"a body of people on one line","meaningCN":"一脉相传的世系","example":"The lineage holds the lower terraces.","exampleCN":"这个世系拥有下面的梯田。"},{"word":"lineages","structure":"lineage + -s (plural)","meaning":"descent lines considered separately","meaningCN":"一条条分别来看的世系","example":"Two lineages share the same spring.","exampleCN":"两个世系共用同一处泉水。"}],"latinEntries":[{"word":"linea","structure":"linum + -ea (Latin noun)","meaning":"a line, a thread","meaningCN":"线；细绳"},{"word":"linum","structure":"Latin noun","meaning":"flax","meaningCN":"亚麻"},{"word":"linealis","structure":"linea + -alis (Medieval Latin adjective)","meaning":"belonging to a line","meaningCN":"属于线的；直系的"}],"derivatives":[{"word":"lineages","structure":"lineage + -s (plural)","meaning":"multiple descent lines","meaningCN":"多个世系"},{"word":"lineally","structure":"lineal + -ly (adverb)","meaning":"by direct descent","meaningCN":"按直系方式"}]}},{"word":"cultural adaptation","ipa_uk":"/ˌkʌltjərəl əˈdæptʃən/","ipa_us":"/ˌkʌltʃərəl əˈdæptʃən/","definition_zh":"文化适应；文化调适；为适应新环境而对习俗、技术与制度所作的调整","definition_en":"the process by which a group or an individual adjusts customs, techniques and institutions to a new setting","core_image":"一群人在新的气候里把旧屋加高、把旧食谱换掉、把旧歌改调，屋梁上留下每一次改动的凿痕","scene":"移民社区在北方落脚后把屋顶加厚、把腌菜换成熏鱼，An exhibit shows how cultural adaptation reshaped the kitchen.","sceneCN":"这里 cultural adaptation 指「群体为适应新环境而对习俗与技术所作的调整」（第 1 个义项：整体文化调适过程）；句意为展览呈现这种文化适应如何改变了厨房的样子。图中可辨识物件：加厚的屋顶、熏鱼架、旧腌菜坛、展签。","pos":[{"tag":"n.","zh":"文化适应；文化调适（不可数）；一次具体的文化调适（可数）"}],"collocations":[{"phrase":"cultural adaptation to a new climate","zh":"对新气候的文化适应"},{"phrase":"process of cultural adaptation","zh":"文化适应的过程"},{"phrase":"cultural adaptation strategy","zh":"文化适应策略"},{"phrase":"rapid cultural adaptation","zh":"快速的文化调适"},{"phrase":"a study of cultural adaptation","zh":"一项文化适应研究"},{"phrase":"cultural adaptation and identity","zh":"文化适应与身份认同"}],"forms":[{"label":"复数（可数用法）","form":"cultural adaptations"},{"label":"相关动词","form":"adapt"},{"label":"相关形容词","form":"adaptive"}],"derivatives":[{"word":"acculturation","pos":"n.","zh":"文化涵化；跨文化接触中的文化改变"},{"word":"adaptation","pos":"n.","zh":"适应；改编本"},{"word":"adapt","pos":"v.","zh":"适应；改编"},{"word":"culturally","pos":"adv.","zh":"在文化方面；从文化角度"},{"word":"enculturation","pos":"n.","zh":"文化习得；在自身文化中的社会化"}],"senses":[{"no":"01","title":"A group adjusts to a new environment","titleCN":"群体对新环境的整体调适","definition":"the process by which a community changes its customs and technology to suit a new environment","definitionCN":"一个社群为适应新环境而改变习俗与技术的过程","example":"Cultural adaptation among the settlers included new roof shapes and new fuels.","exampleCN":"定居者的文化适应包括新的屋顶形制与新的燃料。","why":"the phrase joins the Latin idea of cultivating a way of life to the Latin idea of fitting one thing to another, so it names a whole way of life being fitted to a place.","whyCN":"这个短语把拉丁「耕作、养成一种生活方式」与拉丁「使一物适配另一物」结合起来，指整套生活方式被调整以适配某地。"},{"no":"02","title":"One concrete adaptive custom","titleCN":"一项具体的调适习俗","definition":"a particular practice or object adopted because it helps a group live in a new setting","definitionCN":"某群体为在新环境中生活而采用的特定做法或物件","example":"The smoke-drying rack is a cultural adaptation to a short growing season.","exampleCN":"熏鱼架是对短生长季的一项文化调适。","why":"once the process is familiar, each product of it can be counted and called an adaptation, so the phrase shifts from mass noun to count noun.","whyCN":"过程一旦为人熟悉，它的每件产物都可以计数并称作一项 adaptation，短语便从不可数转为可数。"},{"no":"03","title":"A strategy in cross-cultural psychology","titleCN":"跨文化心理学中的适应策略","definition":"the way individuals manage contact between their heritage culture and a host culture","definitionCN":"个人在处理自身原有文化与所在文化接触时所采取的方式","example":"Integration is often the most successful cultural adaptation for migrants.","exampleCN":"对移民而言，整合常是最成功的文化适应方式。","why":"psychology narrowed the group-level process to the individual, asking how a person holds two cultural frames at once.","whyCN":"心理学把群体层面的过程收窄到个人，追问一个人如何同时持有两套文化框架。"},{"no":"04","title":"A change visible in material remains","titleCN":"在物质遗存中可见的调适","definition":"in archaeology, a change in tools, houses or diet that answers a new environment","definitionCN":"考古学中，工具、房屋或饮食为回应新环境而发生的变化","example":"Pottery with thicker walls records a cultural adaptation to colder winters.","exampleCN":"器壁更厚的陶器记录了针对更冷冬季的一次文化调适。","why":"archaeologists cannot see a process, only its residue, so the phrase comes to name the trace of adjustment in objects.","whyCN":"考古学家看不到过程，只看得到残留，于是这个短语用来指物件上留下的调适痕迹。"},{"no":"05","title":"Localising a policy or product","titleCN":"政策或产品的本地化改编","definition":"the revision of a policy, service or product so that it fits a local culture","definitionCN":"修改政策、服务或产品，使其契合当地文化","example":"The clinic's cultural adaptation of the consent form raised enrolment.","exampleCN":"诊所对知情同意书所作的文化适配提高了入组率。","why":"organisations borrowed the anthropological phrase for a practical task: fitting a ready-made thing to the people who must use it.","whyCN":"机构借用了人类学的说法来描述一项实务：把现成的东西调整给必须使用它的人。"},{"no":"06","title":"A work rewritten for another culture","titleCN":"为另一文化改写过的作品","definition":"a book, film or play recast so that its setting and references suit another audience","definitionCN":"经改写、使其背景与指涉适合另一受众的书、电影或戏剧","example":"The stage version is a cultural adaptation of a Nordic saga.","exampleCN":"这个舞台版本是一部北欧萨迦的改编作品。","why":"the word adaptation already meant a rewritten work, so adding cultural specifies what is being adjusted rather than the medium.","whyCN":"adaptation 本已可指改写过的作品，加上 cultural 是说明被调整的是文化内容，而非媒介。"},{"no":"07","title":"Culture and biology adjusting together","titleCN":"文化与生物性的协同调适","definition":"the mutual adjustment of a cultural practice and a biological trait over time","definitionCN":"文化做法与生物性状在长时段中彼此调整","example":"Dairying and adult lactose tolerance are a case of cultural adaptation meeting genetics.","exampleCN":"乳业与成年乳糖耐受，正是文化适应与遗传相遇的例证。","why":"once a practice changes what people eat, it also changes who survives, so culture and genes adapt to each other.","whyCN":"一种做法一旦改变人们吃什么，也就改变了谁能存活，于是文化与基因彼此适应。"},{"no":"08","title":"Adjusting teaching to a culture","titleCN":"教学对文化的适性调整","definition":"changes to curriculum, assessment or classroom practice that fit local cultural expectations","definitionCN":"为使课程、评估或课堂做法契合当地文化期待而作的变化","example":"The school's cultural adaptation of the oral exam let students answer in pairs.","exampleCN":"学校对口试所作的文化适性调整允许学生两人一组作答。","why":"education took the phrase from psychology and made it a design principle: methods that ignore local norms fail.","whyCN":"教育学从心理学取来这个短语并当作设计原则：忽视本地规范的方法会失败。"}],"etymology":{"intro":{"en":"Cultural adaptation joins two Latin-shaped words: culture from colere 'to till', adaptation from aptare 'to fit'. The compound phrase itself is modern. Dates are approximate.","cn":"cultural adaptation 由两个拉丁形态的词组合而成：culture 出自 colere「耕作」，adaptation 出自 aptare「使合适」。短语本身是近代产物。年代均为约数。"},"items":[{"era":"LATIN COLERE","en":"Colere meant 'to till, cultivate, inhabit, worship'. Its deeper origin is not settled; the range of senses already included caring for land and for gods.","cn":"colere 意为「耕作、培育、居住、敬奉」。其更深来源未有定论；词义范围已同时包括照料土地与敬神。"},{"era":"LATIN CULTURA","en":"Cultura named tilling and tending, and by extension the tending of the mind, from which the modern sense of culture grew.","cn":"cultura 指耕作与照料，并引申为对心智的培育，现代「文化」义由此发展而来。"},{"era":"LATIN APTARE","en":"Aptus 'fit, suited' gave aptare 'to fit or adjust', the source of adapt and adaptation.","cn":"aptus「合适的、相称的」给出 aptare「使合适、调整」，是 adapt 与 adaptation 的来源。"},{"era":"ENGLISH CULTURE AND ADAPTATION","en":"Culture entered English in the thirteenth century as husbandry and learning; adaptation entered in the sixteenth century for the act of fitting.","cn":"culture 于 13 世纪以农事与学问义进入英语；adaptation 于 16 世纪以「使适配」的动作义进入英语。"},{"era":"ANTHROPOLOGY, NINETEENTH CENTURY","en":"Anthropology combined the two words to describe how a people adjusts its whole way of life to a habitat.","cn":"人类学把这两个词组合起来，描述一个民族如何把整套生活方式调整到某一生境。"},{"era":"TWENTIETH-CENTURY SPREAD","en":"Psychology, archaeology, education and marketing each took the phrase and narrowed it to their own kind of adjustment; the shared core is fitting a culture to a setting.","cn":"心理学、考古学、教育学与市场研究各自取用这个短语，并收窄为自己那一类调整；共同的核是让文化适配某种处境。"}]},"similar":{"note":{"en":"The first group is built on adapt and apt and is easily confused by spelling; the second holds neighbouring processes of cultural change.","cn":"第一组建于 adapt 与 apt，拼写极易混淆；第二组是邻近的文化变迁过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adaptation","ipa":"/ˌædæpˈteɪʃən/","tag":"the general fitting","definition":"Any adjustment to a new condition, biological or practical; without cultural it need not involve a way of life.","definitionCN":"对任何新条件的调整，生物性或实务性的皆可；不带 cultural 时不必涉及生活方式。"},{"word":"adoption","ipa":"/əˈdɒpʃən/","tag":"taking up, not fitting","definition":"The act of taking something as one's own, such as a practice or a child; it names acceptance, not adjustment.","definitionCN":"指把某物据为己有，例如采用一种做法或收养孩子；指接受，而非调整。"},{"word":"adaption","ipa":"/əˈdæpʃən/","tag":"older variant","definition":"An older spelling of adaptation that survives in some technical writing; it means the same thing and is now rare.","definitionCN":"adaptation 的旧拼法，仍见于部分技术文献；意思相同，如今罕见。"},{"word":"adaptive","ipa":"/əˈdæptɪv/","tag":"the adjective","definition":"Describing a trait or practice that helps survival; the adjective describes, while the phrase names the process.","definitionCN":"形容有助于生存的性状或做法；形容词是描述性的，短语则指过程本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"acculturation","ipa":"/əˌkʌltʃəˈreɪʃən/","tag":"change through contact","definition":"Cultural change produced by sustained contact between two societies; the change comes from the meeting, not from a habitat.","definitionCN":"两个社会长期接触所引起的文化改变；变化源于相遇，而非生境。"},{"word":"assimilation","ipa":"/əˌsɪmɪˈleɪʃən/","tag":"absorption into the majority","definition":"The process by which a minority group adopts the majority culture until the difference fades; it implies loss as well as fit.","definitionCN":"少数群体采用多数文化直至差异消失的过程；既含适应，也含丧失。"},{"word":"enculturation","ipa":"/ˌenˈkʌltʃəˈreɪʃən/","tag":"learning one's own culture","definition":"The learning of one's native culture from childhood; it is acquisition, not adjustment to something new.","definitionCN":"自幼习得本族文化；那是获得，而非对新事物的调整。"},{"word":"adjustment","ipa":"/əˈdʒʌstmənt/","tag":"the general word","definition":"Any change made to fit circumstances; the plain term, with no claim that a whole culture is involved.","definitionCN":"为适应情况而作的任何改变；最平实的说法，不表示涉及整套文化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin verbs behind the phrase and the collocations researchers actually use.","cn":"正常联想：短语背后两个拉丁动词，以及研究者实际使用的搭配。"},"normal":[{"en":"culture from colere 'to till' + adaptation from aptare 'to fit' = a way of life tilled to fit a place.","cn":"culture 出自 colere「耕作」+ adaptation 出自 aptare「使合适」= 被耕作到适配某地的生活方式。"},{"en":"Adapt also gives adaptable, adaptive, adapter and maladaptive.","cn":"adapt 还给出 adaptable、adaptive、adapter、maladaptive。"},{"en":"The usual frame is adaptation to something: to a climate, to a host society, to a market.","cn":"常见搭配框架是「对某事物的适应」：对气候、对所在社会、对市场。"},{"en":"In psychology the phrase contrasts with assimilation and separation as acculturation strategies.","cn":"在心理学里，这个短语与 assimilation、separation 并列为涵化策略。"},{"en":"Researchers often shorten it to cultural adaptation in titles and keep the full phrase in definitions.","cn":"研究者常在标题里简写为 cultural adaptation，在定义里保留完整短语。"}],"abstract":[{"en":"Picture a house whose roof is raised one beam at a time as the snow line drops.","cn":"想象一座房子，随着雪线下降，屋顶被一根梁一根梁地加高。"},{"en":"Picture a recipe card with old measurements crossed out and local ones pencilled in.","cn":"想象一张食谱卡，旧的计量被划掉，本地计量用铅笔补上。"},{"en":"Picture a song whose tune stays the same while the words learn a new landscape.","cn":"想象一首歌，曲调不变，歌词却学会了新的地貌。"}]},"examples":[{"en":"Cultural adaptation to the high plateau included heavier clothing and barley beer.","cn":"对高原的文化适应包括更厚的衣物与青稞酒。"},{"en":"The museum labels each object as a cultural adaptation rather than an invention.","cn":"博物馆把每件物品标为一次文化调适，而非一项发明。"},{"en":"Her research compares cultural adaptation among three groups of migrants.","cn":"她的研究比较三组移民的文化适应情况。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「靠它适应」——culture 靠它、adapt 适应，合起来就是「靠文化去适应」。换地方先换活法，活法换了就是文化适应。","word":"cultural adaptation"},"root":"culture 出自拉丁 colere「耕作、培育」，经 cultura「耕作、培育」进入英语；adaptation 出自拉丁 aptus「合适的」所生的 aptare「使合适」。两者组合成短语是 19 世纪人类学的用法。","sensesIntro":{"en":"Eight senses move from the whole group to single customs, then to individual psychology, material traces, policy, artworks, gene-culture coadjustment and finally the classroom.","cn":"八个义项从整个群体移到单项习俗，再到个体心理、物质痕迹、政策、作品、基因与文化的协同调整，最后落到课堂。"},"semanticMap":{"core":{"en":"CORE IMAGE: an old house altered beam by beam until it suits a new climate.","cn":"核心意象：一座旧屋被一根根梁地改动，直到适配新的气候。"},"chain":["WHOLE WAY OF LIFE","SINGLE CUSTOM","INDIVIDUAL STRATEGY","MATERIAL TRACE","LOCALISED PRACTICE","ADJUSTED TEACHING"],"branches":[{"senses":"义项 01 · 02","en":"PROCESS AND PRODUCT: the whole adjustment and one adjustable item are the same change seen at two scales.","cn":"过程与产物：整体调整与单项可调之物，是同一变化在两个尺度上的样子。"},{"senses":"义项 03","en":"THE PERSON: psychology moves the unit from a community to an individual holding two cultural frames.","cn":"个人：心理学把单位从社群移到同时持有两套文化框架的个人。"},{"senses":"义项 04","en":"THE TRACE: archaeology can only read the adjustment from what was left in the ground.","cn":"痕迹：考古学只能从留在土里的东西读出这次调整。"},{"senses":"义项 05 · 06","en":"FITTING A READY-MADE THING: a policy or an artwork is reworked until the local audience can use it.","cn":"适配现成之物：政策或作品被改写，直到本地受众能够使用。"},{"senses":"义项 07 · 08","en":"BODY AND CLASSROOM: practice and biology adjust to each other, and teaching adjusts to local norms.","cn":"身体与课堂：做法与生物性彼此调整，教学也调整到本地规范。"}]},"affixes":{"intro":{"en":"The phrase is transparent from its parts: a Latin noun of cultivation and a Latin noun of fitting, each with a living English family.","cn":"这个短语从构件上一目了然：一个表示培育的拉丁名词与一个表示适配的拉丁名词，各自都有活跃的英语词族。"},"latinIntro":{"en":"Latin colere yields culture, cultivate, cult and colony; Latin aptare yields adapt, apt, aptitude and inept.","cn":"拉丁 colere 衍生 culture、cultivate、cult、colony；拉丁 aptare 衍生 adapt、apt、aptitude、inept。"},"items":[{"word":"cultur-","structure":"cultura (Latin noun, 'tilling, tending')","meaning":"cultivation; care","meaningCN":"耕作；培育；照料","example":"The stem carries the idea of tending something over time.","exampleCN":"这个词干带着「长期照料某物」的意思。"},{"word":"adapt-","structure":"aptare (Latin verb, 'to fit')","meaning":"to fit, adjust","meaningCN":"使合适；调整","example":"The stem carries the idea of making one thing suit another.","exampleCN":"这个词干带着「使一物适合另一物」的意思。"},{"word":"-ation","structure":"-atio (Latin noun of action)","meaning":"the act or result of","meaningCN":"……的动作或结果","example":"The ending turns the verb adapt into the noun adaptation.","exampleCN":"这个结尾把动词 adapt 变成名词 adaptation。"},{"word":"culture","structure":"cultura through French","meaning":"a way of life; cultivation","meaningCN":"文化；耕作培育","example":"The two villages share a river culture.","exampleCN":"这两个村子共享一种河谷文化。"},{"word":"cultivate","structure":"cultura + -ate (verb)","meaning":"to till or encourage growth","meaningCN":"耕种；培育","example":"They cultivate rice on the lower terraces.","exampleCN":"他们在低处梯田种稻。"},{"word":"adapt","structure":"ad- + aptare","meaning":"to fit oneself or something to a condition","meaningCN":"适应；使适合","example":"The design adapts to both wet and dry years.","exampleCN":"这一设计能适应湿年与旱年。"},{"word":"apt","structure":"aptus (Latin adjective, 'fit')","meaning":"suitable; quick to learn","meaningCN":"合适的；敏于学习的","example":"An apt comparison makes the point at once.","exampleCN":"一个贴切的比较能立刻说明问题。"},{"word":"aptitude","structure":"aptus + -tudo (Latin noun)","meaning":"natural fitness or talent","meaningCN":"天资；适宜性","example":"She showed an aptitude for languages.","exampleCN":"她显出语言天分。"},{"word":"acculturation","structure":"ad- + cultura + -ation","meaning":"cultural change through contact","meaningCN":"接触引起的文化改变","example":"Acculturation followed two generations of trade.","exampleCN":"两代人的贸易之后出现了文化涵化。"}],"latinEntries":[{"word":"cultura","structure":"colere, past participle cultus (Latin noun)","meaning":"tilling, cultivation, care","meaningCN":"耕作；培育；照料"},{"word":"aptus","structure":"Latin adjective","meaning":"fit, suited, fastened","meaningCN":"合适的；系紧的"},{"word":"adaptare","structure":"ad- + aptare (Latin verb)","meaning":"to fit to, adjust","meaningCN":"使适合；调整"},{"word":"adaptatio","structure":"adaptare + -tio (Medieval Latin noun)","meaning":"a fitting or adjustment","meaningCN":"适配；调整"}],"derivatives":[{"word":"cultural adaptations","structure":"cultural adaptation + -s (plural)","meaning":"several concrete adaptive customs","meaningCN":"多项具体的调适习俗"},{"word":"maladaptive","structure":"mal- (badly) + adaptive","meaning":"adjusting in a way that harms survival","meaningCN":"适应不良的"}]}},{"word":"nomadic","ipa_uk":"/nəʊˈmædɪk/","ipa_us":"/noʊˈmædɪk/","definition_zh":"游牧的；逐水草迁徙的；无固定居所的；四处流动的","definition_en":"moving from place to place with herds or without a fixed home","core_image":"一顶可以整个拆下装进皮袋的帐篷，第二天清晨原地只剩一圈压过草的痕迹","scene":"牧人们在雪线下降之前就拔营转场，Herding families follow a nomadic pattern, moving the flock to fresh grass as each season turns.","sceneCN":"这里 nomadic 指「随牲畜逐水草而迁徙的」（第 1 个义项：按季节转场的游牧方式）；句意为牧户遵循游牧的节奏，随季节把羊群赶到新草地。图中可辨识物件：可拆卸的帐篷、捆好的木杆、羊群、转场小路。","pos":[{"tag":"adj.","zh":"游牧的；流动的；无固定居所的"}],"collocations":[{"phrase":"nomadic herdsmen","zh":"游牧牧民"},{"phrase":"nomadic lifestyle","zh":"游牧生活方式"},{"phrase":"nomadic tribe","zh":"游牧部落"},{"phrase":"nomadic pastoralism","zh":"游牧畜牧"},{"phrase":"nomadic existence","zh":"漂泊不定的生活"},{"phrase":"nomadic worker","zh":"流动工作者"}],"forms":[{"label":"比较级","form":"more nomadic"},{"label":"最高级","form":"most nomadic"},{"label":"副词","form":"nomadically"}],"derivatives":[{"word":"nomad","pos":"n.","zh":"游牧民；漂泊者"},{"word":"nomadism","pos":"n.","zh":"游牧生活；游牧制度"},{"word":"seminomadic","pos":"adj.","zh":"半游牧的"},{"word":"nomadically","pos":"adv.","zh":"以游牧方式地"}],"senses":[{"no":"01","title":"Moving with herds to fresh pasture","titleCN":"随畜群逐水草而迁移","definition":"moving seasonally with livestock so that pasture is not exhausted","definitionCN":"按季节随牲畜迁移，以免草场被吃空","example":"Nomadic herders time their moves by the state of the grass, not by the calendar.","exampleCN":"游牧牧人依草情而不是日历决定迁移的时机。","why":"the Greek source of the word means grazing, so the first sense is tied to animals and pasture rather than to travel for its own sake.","whyCN":"这个词的希腊语源头意为「放牧」，因此第一个义项紧扣牲畜与草场，而不是为了旅行而旅行。"},{"no":"02","title":"Living without a fixed home","titleCN":"没有固定住处","definition":"having no permanent dwelling and moving residence regularly","definitionCN":"没有永久居所、定期搬迁住处","example":"The family has a settled winter house and a nomadic summer camp.","exampleCN":"这家有固定的冬屋，也有夏天流动的营地。","why":"the herding sense widens: once the key fact is that people move, the word can describe anyone without a fixed address.","whyCN":"畜牧义被放宽：一旦关键事实是人会移动，这个词就能形容任何没有固定地址的人。"},{"no":"03","title":"A mobile foraging way of life","titleCN":"移动式觅食的生活方式","definition":"describing a subsistence pattern in which people move to follow wild food","definitionCN":"形容一种随野生食物而移动的生计方式","example":"Nomadic foraging groups cover a wide range within a single year.","exampleCN":"流动觅食的群体在一年之内就走遍很大的范围。","why":"anthropology needed a neutral adjective for mobility that is not herding, so nomadic was borrowed for foragers too.","whyCN":"人类学需要一个中性的形容词来描述非畜牧的移动，于是 nomadic 也被用来指觅食者。"},{"no":"04","title":"Of an animal that roams","titleCN":"指经常漫游的动物","definition":"describing a species that moves constantly rather than holding a territory","definitionCN":"形容不断移动、不固守领地的物种","example":"Nomadic birds appear wherever the seed crop happens to ripen.","exampleCN":"漫游性的鸟出现在种子恰好成熟的地方。","why":"the human image of the wanderer is applied to animals that follow food instead of defending a range.","whyCN":"人类「漂泊者」的意象被移用到那些追随食物而非守卫领地的动物身上。"},{"no":"05","title":"Working without a fixed office","titleCN":"没有固定办公地点的","definition":"describing work done from changing locations rather than one base","definitionCN":"形容在变动地点而非单一基地完成的工作","example":"The studio runs a nomadic model, borrowing a desk in each city.","exampleCN":"这家工作室采用流动模式，每座城市借一张桌子。","why":"modern work repeats the old pattern: no fixed base, resources picked up where they are available.","whyCN":"现代工作重复了旧的模式：没有固定基地，资源在哪儿有就在哪儿取。"},{"no":"06","title":"Living through digital mobility","titleCN":"数字化的流动生活","definition":"describing a life organised around remote work and changing countries","definitionCN":"形容围绕远程工作与更换国家来安排的生活","example":"A nomadic freelancer can bill a client from three countries in one month.","exampleCN":"流动的自由职业者一个月内可以在三个国家为客户结账。","why":"the internet removed the physical herd, leaving only the habit of moving, so the word survives as a lifestyle label.","whyCN":"互联网抽掉了实体畜群，只留下移动的习惯，于是这个词作为生活标签继续存在。"},{"no":"07","title":"Moving between temporary camps","titleCN":"在临时营地之间迁移","definition":"describing a pattern of short stays at a series of camps","definitionCN":"形容在一连串营地短期停留的格局","example":"The survey team led a nomadic summer, packing up every fourth night.","exampleCN":"勘测队过了一个流动的夏天，每四夜收营一次。","why":"this is the concrete mechanics of sense one: pasture, water and fuel decide when the tents come down.","whyCN":"这是第一个义项的具体机制：草、水与燃料决定何时拔营。"},{"no":"08","title":"Restless or transient in manner","titleCN":"心性上漂泊不定的","definition":"figuratively, unable or unwilling to stay long in one place or one subject","definitionCN":"比喻上指无法或不愿久留一地、久守一题","example":"His nomadic reading habits left forty books half finished.","exampleCN":"他游移的阅读习惯留下四十本读了一半的书。","why":"when physical wandering becomes a temperament, the adjective stops describing shepherds and starts describing attention.","whyCN":"当身体的漂泊变成性情，这个形容词就不再描述牧人，而开始描述注意力。"}],"etymology":{"intro":{"en":"Nomadic is the adjective of nomad, which comes from Greek nomas 'roaming for pasture', from nemein 'to graze'. Dates are approximate.","cn":"nomadic 是 nomad 的形容词，nomad 出自希腊 nomas「为放牧而游走」，再上为 nemein「放牧」。年代均为约数。"},"items":[{"era":"GREEK NEMEIN","en":"Nemein meant 'to pasture' and also 'to deal out, distribute'. The two senses belong to one reconstructed root meaning 'to take or allot'; the reconstruction is standard but not attested.","cn":"nemein 意为「放牧」，也有「分配、分给」的意思。这两义属于同一个重构词根「取、分配」；该重构是学界常规做法，却无直接书证。"},{"era":"GREEK NOMAS","en":"Nomas, genitive nomados, described a person or animal that roams in search of pasture; it was not a general word for any traveller.","cn":"nomas（属格 nomados）指为找草场而游走的人或畜，并不是泛指任何旅行者。"},{"era":"GREEK NOMOS","en":"A different noun from the same verb, nomos meant 'law, custom, allotment'. It is the source of economy and autonomy, not of nomad, and the two lines should not be merged.","cn":"同一个动词还给出另一个名词 nomos，意为「法、习俗、分配」。它是 economy 与 autonomy 的来源，不是 nomad 的来源，两条线不能合并。"},{"era":"LATIN NOMAS","en":"Latin borrowed nomas directly as a noun for a wandering shepherd; the word stayed rare and literary in Latin.","cn":"拉丁语直接借入 nomas，作指漂泊牧人的名词；在拉丁语中一直罕见且偏文学。"},{"era":"FRENCH NOMADE","en":"French nomade generalized the word from shepherds to any people without fixed homes, and English took it in that broader shape.","cn":"法语 nomade 把这个词从牧人推广到任何没有固定居所的人群，英语接受的就是这个更宽的形式。"},{"era":"ENGLISH NOMADIC","en":"The adjective nomadic appeared in the nineteenth century, when travel writing and anthropology needed a word for mobile societies.","cn":"形容词 nomadic 在 19 世纪出现，当时游记与人类学需要一个词来描述流动社会。"}]},"similar":{"note":{"en":"The first group shares the Greek grazing word or looks like it; the second group names movement with different roots and different implications.","cn":"第一组共用希腊「放牧」词或形近；第二组用不同词根表示移动，含义也不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nomad","ipa":"/ˈnəʊmæd/","tag":"the person","definition":"A person who moves with herds or without a fixed home; the noun for the person, where nomadic is the adjective.","definitionCN":"随畜群移动或没有固定居所的人；是指人的名词，nomadic 是对应的形容词。"},{"word":"nomadism","ipa":"/ˈnəʊmædɪzəm/","tag":"the system","definition":"The way of life or social system of nomads; it names the arrangement, not a single trait.","definitionCN":"游牧民的生活方式或社会制度；指整套安排，而非单个特征。"},{"word":"seminomadic","ipa":"/ˌsemiˈnəʊmædɪk/","tag":"half mobile","definition":"Partly settled and partly mobile, usually with a fixed winter base and seasonal camps.","definitionCN":"半定居半流动，通常有固定冬基地与季节营地。"},{"word":"nomos","ipa":"/ˈnɒmɒs/","tag":"different Greek noun","definition":"Greek for law or custom, from the same verb but a different noun line; it yields economy and autonomy, not nomad.","definitionCN":"希腊语「法、习俗」，同出一个动词但属另一条名词线；它衍生 economy 与 autonomy，而非 nomad。"}]},{"heading":"NEAR MEANING","entries":[{"word":"migratory","ipa":"/ˈmaɪɡrətəri/","tag":"seasonal movement","definition":"Moving between two fixed regions on a seasonal cycle, as birds do; the route is regular and the endpoints are known.","definitionCN":"按季节在两个固定区域之间移动，如候鸟；路线固定，端点明确。"},{"word":"itinerant","ipa":"/aɪˈtɪnərənt/","tag":"moving for work","definition":"Travelling from place to place for work or duty, such as a circuit judge; it stresses a route of calls, not pasture.","definitionCN":"为工作或职务四处奔走，如巡回法官；强调巡回路线，而非草场。"},{"word":"wandering","ipa":"/ˈwɒndərɪŋ/","tag":"without a plan","definition":"Moving about with no fixed route or purpose; it can sound aimless in a way that nomadic usually does not.","definitionCN":"无固定路线或目的地地走动；常带「漫无目的」的意味，而 nomadic 通常没有这层意思。"},{"word":"peripatetic","ipa":"/ˌperɪpəˈtetɪk/","tag":"walking about, often learned","definition":"Walking from place to place, often used of teachers or musicians who work in several institutions.","definitionCN":"走来走去，常用于在多个机构任教的教师或乐师。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Greek grazing verb, the family of forms and the collocations that keep the adjective in use.","cn":"正常联想：希腊语「放牧」动词、同族各形态，以及让这个形容词保持常用的搭配。"},"normal":[{"en":"nomas 'roaming for pasture' + -ic 'having the character of' = having the character of a pasture-roamer.","cn":"nomas「为放牧而游走」+ -ic「具有……性质的」= 具有逐草而居性质的。"},{"en":"The family moves through nomad, nomadic, nomadism, seminomadic and nomadically.","cn":"词族贯穿 nomad、nomadic、nomadism、seminomadic、nomadically。"},{"en":"The usual partners are herdsmen, tribe, lifestyle and pastoralism.","cn":"常见搭档是 herdsmen、tribe、lifestyle、pastoralism。"},{"en":"Greek nomos 'law' is a different noun line, so economy and autonomy are cousins, not children.","cn":"希腊 nomos「法」属另一条名词线，economy 与 autonomy 是远亲，不是子嗣。"},{"en":"In modern use the word often drops the herd and keeps only the mobility: nomadic worker, nomadic freelancer.","cn":"现代用法常去掉畜群，只留「移动」：流动工作者、流动自由职业者。"}],"abstract":[{"en":"Picture a tent that leaves no mark except a ring of flattened grass.","cn":"想象一顶帐篷，除了压平的一圈草，什么痕迹都不留。"},{"en":"Picture a road whose direction is decided by the colour of the grass ahead.","cn":"想象一条路，方向由前方草的颜色决定。"},{"en":"Picture a house carried on four poles, so that home is a thing you can lift.","cn":"想象一座架在四根杆上的房子，家成了可以用肩抬起的东西。"}]},"examples":[{"en":"Nomadic herders cross the border twice a year with the same flock.","cn":"游牧牧人每年带着同一群牲畜两次越过边界。"},{"en":"The report describes a nomadic childhood spent in eleven villages.","cn":"这份报告描述了一个在十一个村庄间度过的流动童年。"},{"en":"Some nomadic species follow rain rather than seasons.","cn":"有些漫游物种追随降雨而非季节。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「挪麦迪克」听成「挪、迈的可」——挪一挪、迈一迈，随时可以搬走，就是游牧的。nomad 里藏着「挪」。","word":"nomadic"},"root":"希腊 nomas（属格 nomados）「为放牧而游走」，出自 nemein「放牧、分配」，经拉丁 nomas 与法语 nomade 进入英语。希腊 nomos「法、习俗」是同动词的另一条名词线，衍生 economy、autonomy，与 nomad 不同源流。","sensesIntro":{"en":"Eight senses follow mobility outward from the herd: pasture, no fixed home, foraging, roaming animals, mobile work, digital life, temporary camps and finally a restless mind.","cn":"八个义项从畜群向外扩展「移动」：草场、无固定住处、觅食、漫游动物、流动工作、数字生活、临时营地，最后是漂泊的心性。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tent folded onto a pack animal, leaving only a ring of flattened grass.","cn":"核心意象：一顶帐篷被折叠捆上驮畜，原地只剩一圈压平的草。"},"chain":["PASTURE","NO FIXED HOME","MOBILE FORAGING","ROAMING SPECIES","MOBILE WORK","RESTLESS HABIT"],"branches":[{"senses":"义项 01 · 07","en":"HERD AND CAMP: the seasonal move and the nightly pack-up are the same motion at two time scales.","cn":"畜群与营地：季节转场与每夜收营，是同一动作在两个时间尺度上的样子。"},{"senses":"义项 02","en":"NO ADDRESS: once home can be folded, the absence of a fixed dwelling becomes the defining trait.","cn":"没有地址：家一旦可以折叠，「没有固定居所」就成了定义性特征。"},{"senses":"义项 03 · 04","en":"WILD FOOD: people and animals both move to where the food is, so foraging and roaming share the adjective.","cn":"野生食物：人与动物都向食物所在移动，因此觅食与漫游共用这个形容词。"},{"senses":"义项 05 · 06","en":"WORK AND SIGNAL: the herd disappears, but the habit of working and living from wherever one stands remains.","cn":"工作与信号：畜群消失了，但在哪儿站着就在哪儿工作生活的习惯留了下来。"},{"senses":"义项 08","en":"INNER WANDERING: physical restlessness turns into a temperament that will not stay with one place or one question.","cn":"内心漂泊：身体的躁动变成一种不肯久留一地、久守一题的心性。"}]},"affixes":{"intro":{"en":"Nomadic is a Greek noun of pasturing plus an English adjective ending, which is why the word has no Latin root.","cn":"nomadic 是希腊语「放牧」名词加英语形容词词尾，因此这个词没有拉丁词根。"},"latinIntro":{"en":"No Latin cognate is securely attested for this family; Latin borrowed nomas as a loanword, and the Latin-looking forms in modern dictionaries are borrowings rather than native relatives.","cn":"这个词族没有可靠书证的拉丁同族词；拉丁语是把 nomas 当作借词收进来的，现代词典里那些拉丁形只是借形，并非本族亲戚。"},"items":[{"word":"nomas","structure":"nomas, nomados (Greek noun, 'pasture-roamer')","meaning":"one who roams for pasture","meaningCN":"为放牧而游走者","example":"The Greek noun already names the herding life, not travel in general.","exampleCN":"这个希腊名词已经指畜牧生活，而非泛泛的旅行。"},{"word":"nemein","structure":"nemein (Greek verb, 'to pasture, deal out')","meaning":"to graze; to distribute","meaningCN":"放牧；分配","example":"The verb supplies both the pasture sense and the allotment sense.","exampleCN":"这个动词同时提供「放牧」与「分配」两义。"},{"word":"-ic","structure":"-ikos (Greek adjective ending, through Latin -icus)","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The ending also makes pastoral and civic.","exampleCN":"这个结尾也构成 pastoral 与 civic。"},{"word":"nomad","structure":"nomas through Latin and French","meaning":"a pasture-roamer; a person without a fixed home","meaningCN":"游牧民；无固定居所的人","example":"A nomad pitched camp beside the well.","exampleCN":"一个游牧民在水井旁扎营。"},{"word":"nomadism","structure":"nomad + -ism (system or practice)","meaning":"the system of moving with herds","meaningCN":"游牧制度","example":"Nomadism survived the enclosure of the plains.","exampleCN":"平原被圈占之后，游牧制度仍然存续。"},{"word":"seminomadic","structure":"semi- (half) + nomadic","meaning":"partly settled, partly mobile","meaningCN":"半定居半流动的","example":"A seminomadic household keeps both a house and a tent.","exampleCN":"半游牧的家庭既留房子也留帐篷。"},{"word":"nomadically","structure":"nomadic + -ally (adverb)","meaning":"in a roaming manner","meaningCN":"以游牧方式地","example":"They lived nomadically for one whole year.","exampleCN":"他们整整一年过着游牧式的生活。"},{"word":"nomos","structure":"nomos (Greek noun, 'law, custom')","meaning":"law; custom; allotted order","meaningCN":"法；习俗；分配秩序","example":"This noun line gives economy and autonomy, not nomad.","exampleCN":"这条名词线衍生 economy 与 autonomy，而不是 nomad。"},{"word":"economy","structure":"oikos 'house' + nemein 'manage'","meaning":"household management; the management of resources","meaningCN":"家计管理；资源管理","example":"The Greek compound literally means managing a household.","exampleCN":"这个希腊复合词字面意思是管理一个家。"}],"latinEntries":[],"derivatives":[{"word":"nomads","structure":"nomad + -s (plural)","meaning":"people who live without fixed homes","meaningCN":"没有固定居所的游牧民（复数）"},{"word":"nomadology","structure":"nomad + -ology (study of)","meaning":"the study of nomadic societies","meaningCN":"游牧社会研究"}]}},{"word":"nomad","ipa_uk":"/ˈnəʊmæd/","ipa_us":"/ˈnoʊmæd/","definition_zh":"游牧民；游牧部落成员；无固定居所的人；四处漂泊者","definition_en":"a person who moves with herds or lives without a fixed home","core_image":"一个把全部家当系在驮架上的人，走到哪里就把门帘挂到哪里","scene":"井边支起一顶黑毡帐篷，A nomad waters the flock before the long crossing of the plain.","sceneCN":"这里 nomad 指「随畜群迁徙的游牧民」（第 1 个义项：以畜牧为生的游牧者）；句意为一位游牧民在穿越平原之前先给羊群饮水。图中可辨识物件：黑毡帐篷、水槽、羊群、驮架。","pos":[{"tag":"n.","zh":"游牧民；游牧部落成员；漂泊者"},{"tag":"adj.","zh":"（罕用，多作定语）游牧的"}],"collocations":[{"phrase":"a nomad camp","zh":"游牧营地"},{"phrase":"desert nomads","zh":"沙漠游牧民"},{"phrase":"nomad tribes","zh":"游牧部落"},{"phrase":"digital nomad","zh":"数字游民"},{"phrase":"nomad life","zh":"漂泊生活"},{"phrase":"a born nomad","zh":"天生的漂泊者"}],"forms":[{"label":"复数","form":"nomads"},{"label":"形容词","form":"nomadic"},{"label":"名词（制度）","form":"nomadism"}],"derivatives":[{"word":"nomadic","pos":"adj.","zh":"游牧的；流动的"},{"word":"nomadism","pos":"n.","zh":"游牧生活；游牧制度"},{"word":"seminomad","pos":"n.","zh":"半游牧民"},{"word":"nomadically","pos":"adv.","zh":"以游牧方式地"}],"senses":[{"no":"01","title":"A herder who moves with livestock","titleCN":"随牲畜迁移的牧人","definition":"a person who moves seasonally with a herd to find pasture","definitionCN":"按季节随畜群迁移以寻找草场的人","example":"The nomad knows which well still holds water in August.","exampleCN":"这位游牧民知道哪口井到八月还有水。","why":"the Greek noun behind the word means one who roams for pasture, so herding is the oldest and tightest sense.","whyCN":"这个词背后的希腊名词意为「为放牧而游走者」，所以畜牧是最古老、最紧的义项。"},{"no":"02","title":"A person with no fixed home","titleCN":"没有固定居所的人","definition":"a person who lives in no permanent dwelling","definitionCN":"没有永久住所的人","example":"The city counted forty nomads sleeping under the arcade.","exampleCN":"市里统计到有四十名无固定居所的人睡在拱廊下。","why":"the absence of a fixed address is enough to earn the name, even without animals.","whyCN":"即使没有牲畜，只要没有固定地址，就足以得到这个称呼。"},{"no":"03","title":"A member of a nomadic people","titleCN":"游牧民族的成员","definition":"a member of a society whose whole economy is organised around movement","definitionCN":"整个经济都围绕移动来组织的社会中的成员","example":"The nomads of the steppe traded hides for iron at the frontier.","exampleCN":"草原上的游牧民在边市用皮革换铁。","why":"the personal noun becomes a group label, because mobility is organised by the whole people rather than chosen by an individual.","whyCN":"指人的名词变成群体标签，因为流动是由整个民族来组织的，而非个人选择。"},{"no":"04","title":"A restless traveller","titleCN":"不肯久留的漂泊者","definition":"a person who keeps moving out of temperament rather than necessity","definitionCN":"因性情而非生计而不断移动的人","example":"He is a nomad by habit, never staying two winters in one town.","exampleCN":"他习惯漂泊，从不在同一座镇上过两个冬天。","why":"the word loses its herds and keeps its restlessness, so it can describe a temperament.","whyCN":"这个词丢掉了畜群，保留了不安定，因此可以形容性情。"},{"no":"05","title":"A remote worker who keeps moving","titleCN":"不断更换驻地的远程工作者","definition":"a person who works online while changing cities or countries","definitionCN":"一边在线工作一边更换城市或国家的人","example":"The island fills with nomads who stay for a month and leave.","exampleCN":"这座岛挤满了住一个月就走的数字游民。","why":"the old figure of the person whose livelihood travels is refilled with a laptop and a visa instead of a herd.","whyCN":"「生计随身走」的旧形象被重新填上笔记本与签证，而不是畜群。"},{"no":"06","title":"An animal that roams","titleCN":"四处漫游的动物","definition":"an animal that moves continuously rather than keeping a territory","definitionCN":"持续移动、不守领地的动物","example":"The desert nomad among birds follows the rain front south.","exampleCN":"鸟类中的沙漠漫游者随雨锋南下。","why":"the human noun is transferred to animals mainly in natural-history writing.","whyCN":"这个指人的名词主要在博物学写作中被移用到动物身上。"},{"no":"07","title":"A steppe or desert wanderer in history","titleCN":"历史叙述中的草原或沙漠游牧者","definition":"a member of the mobile peoples of steppe or desert as described by settled neighbours","definitionCN":"定居邻人笔下那些草原或沙漠中流动民族的成员","example":"The chronicle describes the nomad as a rider who carries his house on his back.","exampleCN":"这部编年史把游牧民写成把房子背在背上的骑手。","why":"settled societies named mobile peoples from the outside, so the word carries an observer's viewpoint as well as a fact.","whyCN":"定居社会是从外部给流动民族命名的，因此这个词既带事实，也带观察者的视角。"},{"no":"08","title":"Attributive use before a noun","titleCN":"作定语放在名词前","definition":"used before another noun to mean nomadic, as in nomad camp","definitionCN":"放在另一名词前表示「游牧的」，如游牧营地","example":"A nomad tent can be struck in under an hour.","exampleCN":"一顶游牧帐篷不到一小时就能拆完。","why":"English often lets a noun modify another noun, so nomad does the work of the adjective in tight compounds.","whyCN":"英语常让名词修饰名词，因此在紧凑的复合词里，nomad 承担了形容词的职能。"}],"etymology":{"intro":{"en":"Nomad comes from Greek nomas, genitive nomados, 'roaming for pasture', through Latin and French. Dates are approximate.","cn":"nomad 出自希腊 nomas（属格 nomados）「为放牧而游走」，经拉丁语与法语进入英语。年代均为约数。"},"items":[{"era":"GREEK NEMEIN","en":"Nemein meant 'to pasture' and 'to deal out'. It belongs to a reconstructed root meaning 'to take, allot', a standard reconstruction with no direct attestation.","cn":"nemein 意为「放牧」与「分配」。它属于意为「取、分配」的重构词根，这是学界常规重构，无直接书证。"},{"era":"GREEK NOMAS","en":"Nomas named the person or animal that moves in search of grazing; the pasture, not the journey, was the point.","cn":"nomas 指为找草而移动的人或畜；重点是草场，不是旅程。"},{"era":"GREEK NOMOS","en":"Nomos 'law, custom' is a separate noun from the same verb; it produced economy and autonomy, and dictionaries that merge it with nomas are wrong.","cn":"nomos「法、习俗」是同动词的另一个名词；它衍生 economy 与 autonomy，把它与 nomas 合并的词典是错的。"},{"era":"LATIN NOMAS","en":"Latin kept nomas as a literary borrowing for a wandering shepherd, without developing a large family of its own.","cn":"拉丁语把 nomas 作为文学借词保留下来，指漂泊牧人，并未发展出庞大的本族词族。"},{"era":"FRENCH NOMADE","en":"French nomade widened the sense to any mobile people, and eighteenth-century travel writing spread the widened word.","cn":"法语 nomade 把词义放宽到任何流动民族，18 世纪游记把这一放宽后的词传播开来。"},{"era":"ENGLISH NOMAD","en":"English nomad is recorded from the sixteenth century; the modern digital sense dates only from the twenty-first.","cn":"英语 nomad 自 16 世纪有记录；现代数字义直到 21 世纪才出现。"}]},"similar":{"note":{"en":"The first group is the same family or a Greek near neighbour; the second group names other kinds of mover, each with a different reason for moving.","cn":"第一组是同族词或希腊语近邻；第二组指其他类型的移动者，各自的移动理由不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nomadic","ipa":"/nəʊˈmædɪk/","tag":"adjective","definition":"The adjective describing the life; nomad is the person, nomadic is the quality.","definitionCN":"描述这种生活的形容词；nomad 指人，nomadic 指性质。"},{"word":"nomadism","ipa":"/ˈnəʊmædɪzəm/","tag":"the system","definition":"The social and economic system of moving with herds; it cannot name one person.","definitionCN":"随畜群移动的社会经济制度；不能指单个人。"},{"word":"nomade","ipa":"/nɔˈmad/","tag":"French spelling","definition":"The French form that English borrowed; the final -e is silent and should not be carried into English.","definitionCN":"英语借用的法语形式；词尾 -e 不发音，不应带进英语拼写。"},{"word":"nomos","ipa":"/ˈnɒmɒs/","tag":"different noun line","definition":"Greek for law or custom, from the same verb but not the same noun; it is behind economy, not nomad.","definitionCN":"希腊语「法、习俗」，同动词但非同名词；它支撑 economy，而非 nomad。"}]},{"heading":"NEAR MEANING","entries":[{"word":"wanderer","ipa":"/ˈwɒndərə/","tag":"generic mover","definition":"Anyone who moves about without a fixed route; it lacks the herding and pasture history of nomad.","definitionCN":"任何无固定路线四处走动的人；缺少 nomad 的畜牧与草场历史。"},{"word":"migrant","ipa":"/ˈmaɪɡrənt/","tag":"moves for work or season","definition":"A person or animal that moves, usually between known places and for a known reason such as work or weather.","definitionCN":"通常在已知地点之间、因工作或气候等已知原因而移动的人或动物。"},{"word":"Bedouin","ipa":"/ˈbeduɪn/","tag":"a particular people","definition":"An Arabic-speaking desert people of the Middle East; a proper name for one nomadic group, not a general term.","definitionCN":"中东讲阿拉伯语的沙漠民族；是某一游牧群体的专名，不是通称。"},{"word":"roamer","ipa":"/ˈrəʊmə/","tag":"aimless tone","definition":"A person who roams, often with a suggestion of pleasure or aimlessness rather than livelihood.","definitionCN":"四处漫游的人，常暗示消遣或漫无目的，而非生计。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Greek pasture word, the family and the modern compounds the noun now forms.","cn":"正常联想：希腊语「草场」词、同族词，以及这个名词现在构成的现代复合词。"},"normal":[{"en":"nomas 'pasture-roamer' = the person; the tents and herds are implied by the Greek source.","cn":"nomas「为草场而游走者」= 这个人；希腊词源已隐含帐篷与畜群。"},{"en":"The family runs nomad, nomadic, nomadism, seminomad and nomadically.","cn":"词族包括 nomad、nomadic、nomadism、seminomad、nomadically。"},{"en":"Common compounds are nomad camp, nomad tribe and digital nomad.","cn":"常见复合词是「游牧营地」「游牧部落」「数字游民」。"},{"en":"Greek nomos 'law' is behind economy and autonomy, not behind nomad.","cn":"希腊 nomos「法」支撑 economy 与 autonomy，不支撑 nomad。"},{"en":"The word is nearly always countable: a nomad, two nomads, the nomads of the steppe.","cn":"这个词几乎总是可数：一个游牧民、两个游牧民、草原上的游牧民。"}],"abstract":[{"en":"Picture a door curtain that can be hung on any frame in any valley.","cn":"想象一幅门帘，挂到任何山谷的任何门框上都合适。"},{"en":"Picture a saddlebag holding a bowl, a rope and a deed to nothing.","cn":"想象一只鞍袋，装着一只碗、一根绳，和一张不指向任何地产的契。"},{"en":"Picture footprints that never deepen because they are never repeated.","cn":"想象一串永不加深的脚印，因为它们从不重复。"}]},"examples":[{"en":"The nomad traded two ewes for a sack of salt.","cn":"这位游牧民拿两只母羊换了一袋盐。"},{"en":"Nomads have crossed this pass for as long as the road has existed.","cn":"自这条路存在以来，游牧民就一直翻越这道山口。"},{"en":"She calls herself a digital nomad and works from six time zones.","cn":"她自称数字游民，在六个时区之间工作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「诺曼」听成「挪门」——门一挪就走，家当全在身上。挪门的人，就是游牧民。","word":"nomad"},"root":"希腊 nomas（属格 nomados）「为放牧而游走」，出自 nemein「放牧、分配」；经拉丁 nomas 与法语 nomade 进入英语。同动词的 nomos「法、习俗」是另一条名词线。","sensesIntro":{"en":"Eight senses move from the herder to the homeless person, the whole people, the restless traveller, the remote worker, the roaming animal, the historical figure and finally the attributive use.","cn":"八个义项从牧人移到无家者、整个民族、不安定的旅人、远程工作者、漫游动物、历史形象，最后是定语用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a traveller whose whole household is tied to a pack frame.","cn":"核心意象：一个把全部家当捆在驮架上的人。"},"chain":["HERDER","NO FIXED HOME","NOMADIC PEOPLE","RESTLESS TRAVELLER","REMOTE WORKER","ANIMAL ROAMER"],"branches":[{"senses":"义项 01 · 07","en":"THE HERDER INSIDE AND OUTSIDE HISTORY: the working herder and the figure described by settled neighbours are the same person seen from two sides.","cn":"历史内外的牧人：干活的牧人与定居邻人笔下的形象，是同一个人从两面看。"},{"senses":"义项 02 · 04","en":"WITHOUT A HOME, WITH OR WITHOUT A REASON: necessity and temperament both produce the same absence of address.","cn":"没有家，有理由或没理由：生计与性情都造成同样的「没有地址」。"},{"senses":"义项 03","en":"THE WHOLE PEOPLE: mobility organised by a society turns the personal noun into an ethnic label.","cn":"整个民族：由社会来组织的流动，把指人的名词变成族群标签。"},{"senses":"义项 05","en":"THE LAPTOP REPLACES THE HERD: remote work reproduces the old pattern with a different livelihood.","cn":"笔记本取代畜群：远程工作用另一种生计复制了旧模式。"},{"senses":"义项 06 · 08","en":"ANIMALS AND COMPOUNDS: the noun is lent to roaming species and also pressed into service as a modifier.","cn":"动物与复合词：这个名词既借给漫游物种，也被压作修饰语使用。"}]},"affixes":{"intro":{"en":"Nomad is a Greek noun of pasturing with no Latin root, so its family is built by English suffixes rather than by Latin prefixes.","cn":"nomad 是希腊语「放牧」名词，没有拉丁词根，因此它的词族由英语后缀构成，而非拉丁前缀。"},"latinIntro":{"en":"There is no native Latin relative: Latin only borrowed nomas. The Latin-looking nominal endings added later are English or French work, not Latin descent.","cn":"没有本族的拉丁亲戚：拉丁语只是借入 nomas。后来加上的那些拉丁味名词词尾是英语或法语的手工，而非拉丁血统。"},"items":[{"word":"nomad-","structure":"nomas, nomados (Greek noun)","meaning":"pasture-roamer","meaningCN":"为草场而游走者","example":"The stem already contains the herd and the pasture.","exampleCN":"这个词干已包含畜群与草场。"},{"word":"-ic","structure":"-ikos (Greek adjective ending)","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The ending forms nomadic from nomad.","exampleCN":"这个结尾把 nomad 变成 nomadic。"},{"word":"-ism","structure":"-ismos (Greek noun ending, through French -isme)","meaning":"a system or practice","meaningCN":"制度；做法","example":"The ending forms nomadism from nomad.","exampleCN":"这个结尾把 nomad 变成 nomadism。"},{"word":"nomad","structure":"nomas through Latin and French","meaning":"a pasture-roamer","meaningCN":"游牧民","example":"A nomad keeps few possessions.","exampleCN":"游牧民的家当很少。"},{"word":"nomads","structure":"nomad + -s (plural)","meaning":"mobile herders as a group","meaningCN":"作为一群的流动牧人","example":"The nomads moved north with the rain.","exampleCN":"游牧民随雨向北移动。"},{"word":"nomadic","structure":"nomad + -ic","meaning":"living by moving","meaningCN":"以移动为生的","example":"The camp is nomadic in summer only.","exampleCN":"这个营地只在夏天流动。"},{"word":"nomadism","structure":"nomad + -ism","meaning":"the mobile herding system","meaningCN":"游牧制度","example":"Nomadism shapes the whole calendar.","exampleCN":"游牧制度塑造了整个历法。"},{"word":"seminomad","structure":"semi- (half) + nomad","meaning":"a partly settled herder","meaningCN":"半定居的牧人","example":"The seminomad keeps a winter house.","exampleCN":"半游牧民有固定的冬屋。"},{"word":"nomadically","structure":"nomadic + -ally","meaning":"in a roaming way","meaningCN":"以游牧方式地","example":"They travelled nomadically for a decade.","exampleCN":"他们以游牧方式走了十年。"}],"latinEntries":[],"derivatives":[{"word":"nomadness","structure":"nomad + -ness (state)","meaning":"the condition of being a nomad","meaningCN":"游牧者的状态"},{"word":"antinomad","structure":"anti- (against) + nomad","meaning":"opposed to nomadic life","meaningCN":"反对游牧生活的"}]}},{"word":"nomadism","ipa_uk":"/ˈnəʊmædɪzəm/","ipa_us":"/ˈnoʊmædɪzəm/","definition_zh":"游牧生活；游牧制度；以移动为基础的生存方式","definition_en":"the way of life or social system in which people move with herds or without fixed homes","core_image":"一张画满箭头的年历，每个箭头都指向一处按季节轮换的草场","scene":"牧道在图上被画成一条闭合的环，Seasonal nomadism keeps every pasture rested for half of the year.","sceneCN":"这里 nomadism 指「以季节迁移为核心的游牧制度」（第 1 个义项：畜牧型游牧）；句意为季节性的游牧使每片草场在一年里有半年得以休养。图中可辨识物件：闭合的牧道环、年历、草场标记、羊群剪影。","pos":[{"tag":"n.","zh":"游牧生活；游牧制度（不可数）"}],"collocations":[{"phrase":"pastoral nomadism","zh":"畜牧游牧"},{"phrase":"seasonal nomadism","zh":"季节性游牧"},{"phrase":"the rise of nomadism","zh":"游牧制度的兴起"},{"phrase":"nomadism and settlement","zh":"游牧与定居"},{"phrase":"a study of nomadism","zh":"对游牧制度的研究"},{"phrase":"digital nomadism","zh":"数字游牧生活方式"}],"forms":[{"label":"不可数（无复数）","form":"nomadism"},{"label":"形容词","form":"nomadic"},{"label":"指人的名词","form":"nomad"}],"derivatives":[{"word":"nomadic","pos":"adj.","zh":"游牧的"},{"word":"nomad","pos":"n.","zh":"游牧民"},{"word":"seminomadism","pos":"n.","zh":"半游牧状态"},{"word":"nomadically","pos":"adv.","zh":"以游牧方式地"}],"senses":[{"no":"01","title":"Herding by seasonal movement","titleCN":"按季节迁移的畜牧方式","definition":"a pastoral system in which herds and herders move between seasonal pastures","definitionCN":"畜群与牧人在季节草场之间移动的畜牧制度","example":"Pastoral nomadism depends on wells that are shared by several groups.","exampleCN":"畜牧游牧依赖几群人共用的水井。","why":"the -ism turns the person into a system, and the first system built on moving herders is seasonal herding.","whyCN":"-ism 把人变成制度，而建立在流动牧人之上的第一个制度就是季节畜牧。"},{"no":"02","title":"Mobility as social organisation","titleCN":"以流动为骨架的社会组织","definition":"a form of society whose institutions assume that people will move","definitionCN":"制度以人将移动为前提的社会形式","example":"Nomadism shapes marriage rules as much as it shapes grazing.","exampleCN":"游牧制度对婚姻规则的影响不亚于对放牧的影响。","why":"once mobility is normal, kinship, law and property are built around it rather than around a village.","whyCN":"一旦流动成为常态，亲属、法律与财产便围绕流动而建，而不是围绕村庄。"},{"no":"03","title":"A seasonal migration cycle","titleCN":"季节迁移的循环","definition":"the recurring pattern of moving to and from fixed seasonal sites","definitionCN":"往返于固定的季节地点之间的循环格局","example":"The nomadism of the valley is drawn as a ring, not a line.","exampleCN":"这座山谷的游牧路线被画成一个环，而不是一条线。","why":"the system repeats annually, so it is better pictured as a loop than as a departure.","whyCN":"这套制度每年重复，因此画成环比画成一次出发更准确。"},{"no":"04","title":"A subsistence type in anthropology","titleCN":"人类学中的一种生计类型","definition":"one of the standard categories of subsistence strategy in social science","definitionCN":"社会科学中标准生计策略分类之一","example":"The course compares nomadism, transhumance and settled ranching.","exampleCN":"这门课比较游牧、季节性移牧与定居放牧。","why":"social science classifies livelihoods, so the system becomes a box on a chart beside foraging and farming.","whyCN":"社会科学要给生计分类，于是这套制度成了图表上与觅食、农耕并列的一格。"},{"no":"05","title":"A modern mobile lifestyle","titleCN":"现代流动生活方式","definition":"a contemporary life organised around moving between cities while working remotely","definitionCN":"围绕在城市间移动并远程工作来安排的当代生活","example":"Digital nomadism changed what landlords expect from a one-month lease.","exampleCN":"数字游牧改变了房东对一个月租期的期待。","why":"the suffix -ism is productive enough to name any organised way of life, including one built on wifi.","whyCN":"-ism 这个后缀足够能产，能为任何成体系的生活方式命名，包括建立在无线网络之上的那种。"},{"no":"06","title":"The opposite of sedentism","titleCN":"与定居相对的状态","definition":"the condition of living without permanent settlement, seen as the counterpart of staying put","definitionCN":"没有永久定居的生活状态，被看作「久居一地」的对立面","example":"Debates about early nomadism are often debates about the meaning of home.","exampleCN":"关于早期游牧的争论，往往是对「家」之含义的争论。","why":"a system is easiest to define against its opposite, so nomadism is often explained by what it is not.","whyCN":"一套制度最容易借对立面来定义，因此游牧常以「它不是什么」来解释。"},{"no":"07","title":"Roaming behaviour in animals","titleCN":"动物的漫游习性","definition":"the habit of a species that moves continuously instead of holding a territory","definitionCN":"某物种持续移动而不守领地的习性","example":"Nomadism in desert birds tracks rainfall rather than latitude.","exampleCN":"沙漠鸟类的漫游习性追随降雨，而非纬度。","why":"ecology borrowed the human term, and the -ism now names a behavioural pattern rather than a society.","whyCN":"生态学借用了这个人类学术语，-ism 现在指的是一种行为格局，而非社会。"},{"no":"08","title":"Wandering of the mind","titleCN":"思想上的游走","definition":"figuratively, a habit of moving between ideas or disciplines without settling","definitionCN":"比喻指在观念或学科之间游走而不肯落定","example":"His intellectual nomadism produced brilliant fragments and no book.","exampleCN":"他的思想游牧留下许多精彩片段，却没有一部完整的书。","why":"the system image is light enough to describe attention itself, which also refuses to settle.","whyCN":"这套制度的意象足够轻，可以描述注意力本身，而注意力也拒绝定居。"}],"etymology":{"intro":{"en":"Nomadism is nomad plus the Greek-derived suffix -ism, naming a system rather than a person. Dates are approximate.","cn":"nomadism 是 nomad 加希腊来源的后缀 -ism，指一套制度而非一个人。年代均为约数。"},"items":[{"era":"GREEK NOMAS","en":"Nomas 'pasture-roamer' came from nemein 'to pasture'. The root behind nemein is reconstructed, not attested, and its sense is usually given as 'to allot'.","cn":"nomas「为草场而游走者」出自 nemein「放牧」。nemein 背后的词根属重构而非书证，其含义通常写作「分配」。"},{"era":"FRENCH NOMADE","en":"French widened the noun to any mobile people and formed the adjective nomade before English borrowed the set.","cn":"法语把这个名词放宽到任何流动民族，并在英语整套借入之前已构成形容词 nomade。"},{"era":"SUFFIX -ISM","en":"The suffix -ism came into English through French from Greek -ismos, and turns a noun into the name of a system, practice or doctrine.","cn":"后缀 -ism 经法语从希腊 -ismos 进入英语，把名词变成制度、做法或学说的名称。"},{"era":"ENGLISH NOMADISM","en":"Nomadism is recorded in the nineteenth century, when anthropology needed names for whole subsistence systems rather than for individuals.","cn":"nomadism 在 19 世纪有记录，当时人类学需要为整套生计制度而非个人命名。"},{"era":"ANTHROPOLOGICAL USE","en":"The term was fixed in contrast with pastoralism, transhumance and sedentism; the boundaries between them are still debated.","cn":"这个词在与畜牧、季节性移牧、定居的对举中固定下来；它们之间的界线至今仍有争论。"},{"era":"DIGITAL EXTENSION","en":"In the twenty-first century nomadism was applied to remote workers, an extension that anthropologists often treat as metaphor rather than category.","cn":"21 世纪，nomadism 被用在远程工作者身上；人类学者通常把这当作比喻，而非分类。"}]},"similar":{"note":{"en":"The first group shares the Greek stem; the second group names neighbouring systems, each with a different relation between people, animals and place.","cn":"第一组共用希腊词干；第二组是邻近的制度，各自在人、畜与地点之间有不同关系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nomad","ipa":"/ˈnəʊmæd/","tag":"the person","definition":"One mobile herder; the -ism names the arrangement that such people live inside.","definitionCN":"一个流动的牧人；-ism 指这些人所处的整套安排。"},{"word":"nomadic","ipa":"/nəʊˈmædɪk/","tag":"the adjective","definition":"Describing the life or the person; it gives a quality, while nomadism gives a system.","definitionCN":"描述生活或人的形容词；它给出性质，nomadism 给出制度。"},{"word":"seminomadism","ipa":"/ˌsemiˈnəʊmædɪzəm/","tag":"half system","definition":"A system that combines a fixed base with seasonal movement, common among mountain herders.","definitionCN":"固定基地与季节移动并存的制度，山地牧人中常见。"},{"word":"nomadisme","ipa":"/nɔmaˈdism/","tag":"French spelling","definition":"The French form; English uses -ism, so the French ending should not appear in English text.","definitionCN":"法语形式；英语用 -ism，因此法语词尾不应出现在英语文本里。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pastoralism","ipa":"/ˈpɑːstərəlɪzəm/","tag":"herding as such","definition":"The branch of farming based on grazing animals; it may be settled, and it does not by itself require movement.","definitionCN":"以放牧牲畜为基础的农业分支；可以是定居的，本身不要求移动。"},{"word":"transhumance","ipa":"/trænzˈhjuːməns/","tag":"seasonal up-and-down","definition":"The regular movement of herds between high summer pasture and low winter pasture, usually with a fixed home base.","definitionCN":"畜群在夏季高山草场与冬季低地草场之间规律移动，通常有固定基地。"},{"word":"migration","ipa":"/maɪˈɡreɪʃən/","tag":"the move itself","definition":"The act of moving from one region to another, often one-way or seasonal; it can name people, birds or labour.","definitionCN":"从一个地区移到另一地区的行为，常为单向或季节性；可指人、鸟或劳动力。"},{"word":"itinerancy","ipa":"/aɪˈtɪnərənsi/","tag":"moving for duty","definition":"The practice of travelling from place to place for work, as itinerant teachers or judges do; no herds are implied.","definitionCN":"为工作四处奔走，如巡回教师或法官；不隐含畜群。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Greek stem, the system suffix and the contrasts anthropologists actually draw.","cn":"正常联想：希腊词干、表示制度的后缀，以及人类学者实际作出的对举。"},"normal":[{"en":"nomad + -ism = the system lived by nomads, the way feudalism is the system lived under lords.","cn":"nomad + -ism = 游牧民所生活的制度，正如 feudalism 是领主制度下的生活方式。"},{"en":"The standard contrast set is nomadism, transhumance, pastoralism and sedentism.","cn":"标准对举组是 nomadism、transhumance、pastoralism、sedentism。"},{"en":"The word is uncountable: one does not say a nomadism, but one may say a form of nomadism.","cn":"这个词不可数：不说「一个游牧制度」，但可以说「某种游牧制度」。"},{"en":"The adjective is nomadic and the person is nomad; only the -ism names the system.","cn":"形容词是 nomadic，指人是 nomad；只有 -ism 形式指制度。"},{"en":"Modern writing prefixes it: digital nomadism, corporate nomadism, intellectual nomadism.","cn":"现代写作给它加前缀：数字游牧、企业流动、思想游牧。"}],"abstract":[{"en":"Picture a yearly ring drawn on a map, with an arrow at each quarter.","cn":"想象地图上画着一个年度环，每一季都有一支箭头。"},{"en":"Picture a calendar where every month names a well instead of a day.","cn":"想象一本日历，每个月写的是一口水井，而不是哪一天。"},{"en":"Picture a society whose only monument is a path worn into stone.","cn":"想象一个社会，唯一的纪念碑是一条被踩进石头的路。"}]},"examples":[{"en":"Nomadism in this valley depends on three shared wells.","cn":"这座山谷的游牧制度依赖三口共用的水井。"},{"en":"The paper argues that nomadism is a strategy, not a stage.","cn":"这篇论文主张游牧是一种策略，而非一个阶段。"},{"en":"Digital nomadism has reshaped the short-term rental market.","cn":"数字游牧生活方式改变了短租市场。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「挪麦迪怎」听成「挪、买地怎」——走到哪儿都在问「地怎么买」，问完又走，成了一套活法，就是游牧制度。","word":"nomadism"},"root":"nomad 出自希腊 nomas（属格 nomados）「为放牧而游走」，出自 nemein「放牧」；后缀 -ism 经法语来自希腊 -ismos，表示制度或做法。两层组合指「游牧民所依循的整套制度」。","sensesIntro":{"en":"Eight senses widen one system: seasonal herding, social organisation, the migration cycle, the anthropological category, the modern lifestyle, the contrast with settlement, animal roaming and mental wandering.","cn":"八个义项从一个制度向外扩：季节畜牧、社会组织、迁移循环、人类学分类、现代生活方式、与定居的对举、动物漫游、思想游走。"},"semanticMap":{"core":{"en":"CORE IMAGE: a closed ring of pasture roads marked on a yearly calendar.","cn":"核心意象：年历上标出的一圈闭合牧道。"},"chain":["SEASONAL HERDING","MOBILE SOCIETY","MIGRATION CYCLE","SUBSISTENCE CATEGORY","MODERN MOBILITY","MENTAL WANDERING"],"branches":[{"senses":"义项 01 · 03","en":"HERDING AND ITS LOOP: the annual circle is the practical form of the herding system.","cn":"畜牧与其环线：年度循环是畜牧制度的实际形态。"},{"senses":"义项 02","en":"INSTITUTIONS ON THE MOVE: kinship and property are redesigned around the expectation of movement.","cn":"随移动而建的制度：亲属与财产围绕「将会移动」这一预期重新设计。"},{"senses":"义项 04 · 06","en":"A BOX AND ITS OPPOSITE: social science files the system beside foraging and farming, and defines it against staying put.","cn":"一格及其对立面：社会科学把它与觅食、农耕并列归档，并以「不久居」来界定它。"},{"senses":"义项 05","en":"THE LAPTOP VARIANT: remote work keeps the system shape but changes the economy inside it.","cn":"笔记本变体：远程工作保留了制度形状，却换掉了里面的经济。"},{"senses":"义项 07 · 08","en":"BEYOND SOCIETY: the same word describes roaming animals and a mind that will not settle.","cn":"超出社会：同一个词也描述漫游的动物，以及不肯落定的心智。"}]},"affixes":{"intro":{"en":"Nomadism is a Greek-derived noun stem with a Greek-derived system suffix, and it has no Latin root to divide.","cn":"nomadism 是希腊来源的名词词干加希腊来源的制度后缀，没有可拆的拉丁词根。"},"latinIntro":{"en":"Latin has no native relative here; it borrowed the Greek noun. The -ism ending reached English through French, which is why it looks familiar rather than Latin.","cn":"拉丁语在此没有本族亲戚，只是借入这个希腊名词。-ism 词尾经法语进入英语，因此它看起来眼熟，却不是拉丁的。"},"items":[{"word":"nomad-","structure":"nomas, nomados (Greek noun)","meaning":"pasture-roamer","meaningCN":"为草场而游走者","example":"The stem names the person before the suffix names the system.","exampleCN":"词干先指人，后缀再指制度。"},{"word":"-ism","structure":"-ismos (Greek suffix, through French -isme)","meaning":"a system, practice or doctrine","meaningCN":"制度、做法或学说","example":"The suffix also forms pastoralism and feudalism.","exampleCN":"这个后缀还构成 pastoralism 与 feudalism。"},{"word":"nomadism","structure":"nomad + -ism","meaning":"the mobile herding system","meaningCN":"游牧制度","example":"Nomadism survives where wells are shared.","exampleCN":"在共用井水的地方，游牧制度得以存续。"},{"word":"nomad","structure":"nomas through Latin and French","meaning":"one who lives by moving","meaningCN":"以移动为生的人","example":"Each nomad belongs to a camp group.","exampleCN":"每个游牧民都属于一个营地群体。"},{"word":"nomadic","structure":"nomad + -ic","meaning":"of the mobile life","meaningCN":"流动生活的","example":"The route is nomadic in origin.","exampleCN":"这条路线源于游牧。"},{"word":"seminomadism","structure":"semi- (half) + nomadism","meaning":"a partly settled system","meaningCN":"半定居的制度","example":"Seminomadism fits mountain valleys better than plains.","exampleCN":"半游牧更适合山谷而非平原。"},{"word":"pastoralism","structure":"pastor + -al + -ism","meaning":"herding as a branch of farming","meaningCN":"作为农业分支的畜牧","example":"Pastoralism can be fully settled.","exampleCN":"畜牧可以是完全定居的。"},{"word":"transhumance","structure":"trans- + humus (Latin 'ground') + -ance","meaning":"seasonal movement between pastures","meaningCN":"在草场之间的季节移动","example":"Transhumance keeps a fixed village base.","exampleCN":"季节性移牧保留固定的村庄基地。"},{"word":"sedentism","structure":"sedent- (sitting) + -ism","meaning":"the system of permanent settlement","meaningCN":"永久定居的制度","example":"Sedentism grew with stored grain.","exampleCN":"定居制度随储粮而发展。"}],"latinEntries":[],"derivatives":[{"word":"nomadisms","structure":"nomadism + -s (rare plural)","meaning":"distinct forms of the system","meaningCN":"不同形态的游牧制度"},{"word":"neonomadism","structure":"neo- (new) + nomadism","meaning":"a recent revived form of mobile living","meaningCN":"新式流动生活"}]}},{"word":"hunter-gatherer","ipa_uk":"/ˈhʌntə ɡæðərə/","ipa_us":"/ˈhʌntər ɡæðərər/","definition_zh":"狩猎采集者；以狩猎与采集野生食物为生的人或社会","definition_en":"a person who lives by hunting wild animals and gathering wild plants","core_image":"一个人清晨握着削尖的木矛、背着编好的草袋，在河岸与林地之间来回察看踪迹与果实","scene":"河岸的泥地上留着鹿蹄印，A hunter-gatherer reads the bank for roots and tracks alike.","sceneCN":"这里 hunter-gatherer 指「以狩猎和采集野生食物为生的人」（第 1 个义项：个体狩猎采集者）；句意为一位狩猎采集者同时察看岸边的根茎与兽迹。图中可辨识物件：木矛、草袋、蹄印、挖根的木棍。","pos":[{"tag":"n.","zh":"狩猎采集者"},{"tag":"adj.","zh":"（作定语）狩猎采集的"}],"collocations":[{"phrase":"hunter-gatherer society","zh":"狩猎采集社会"},{"phrase":"hunter-gatherer band","zh":"狩猎采集群体"},{"phrase":"hunter-gatherer lifestyle","zh":"狩猎采集生活方式"},{"phrase":"hunter-gatherer diet","zh":"狩猎采集饮食"},{"phrase":"a group of hunter-gatherers","zh":"一群狩猎采集者"}],"forms":[{"label":"复数","form":"hunter-gatherers"},{"label":"作定语","form":"hunter-gatherer"}],"derivatives":[{"word":"hunter","pos":"n.","zh":"猎人"},{"word":"gatherer","pos":"n.","zh":"采集者"},{"word":"hunting","pos":"n.","zh":"狩猎"},{"word":"gathering","pos":"n.","zh":"采集；聚集"}],"senses":[{"no":"01","title":"A person living by hunting and gathering","titleCN":"以狩猎采集为生的人","definition":"an individual whose food comes from hunting animals and collecting wild plants","definitionCN":"食物来自猎取动物与采集野生植物的人","example":"A hunter-gatherer moves camp when the fruit stand is stripped.","exampleCN":"果实被摘光后，狩猎采集者就搬营。","why":"the compound names the two food-getting activities directly, so the person is defined by the work rather than by ancestry or place.","whyCN":"这个复合词直接点出两种获取食物的活动，因此这个人是由劳作而非血统或地点来定义的。"},{"no":"02","title":"A society organised around wild food","titleCN":"围绕野生食物组织起来的社会","definition":"a small mobile society whose economy rests on wild resources rather than farming","definitionCN":"经济依赖野生资源而非农耕的小型流动社会","example":"The hunter-gatherer society kept no stored surplus beyond a few days.","exampleCN":"这个狩猎采集社会除几天的份量外不留储备。","why":"anthropology uses the singular compound as a category label, so one word can stand for a whole social formation.","whyCN":"人类学把这个单数复合词当作分类标签，因此一个词可以代表一整套社会形态。"},{"no":"03","title":"An archaeological category","titleCN":"考古学中的文化类型","definition":"a classification for sites and tool kits interpreted as products of wild-food economies","definitionCN":"把遗址与工具组合解释为野生食物经济产物的分类","example":"The cave was assigned to a late hunter-gatherer phase.","exampleCN":"这处洞穴被归入狩猎采集的晚期阶段。","why":"archaeologists classify what they cannot observe, so the term becomes a label attached to material assemblages.","whyCN":"考古学家给无法直接观察的东西分类，因此这个词成了贴在器物组合上的标签。"},{"no":"04","title":"Attributive use before a noun","titleCN":"作定语放在名词前","definition":"used before another noun to describe a practice or economy, as in hunter-gatherer diet","definitionCN":"放在另一名词前描述某种做法或经济，如狩猎采集饮食","example":"The hunter-gatherer diet included nuts, tubers and small game.","exampleCN":"狩猎采集饮食包括坚果、块根与小猎物。","why":"English compounds often work as modifiers without any change of form, so the whole compound sits in front of the noun it qualifies.","whyCN":"英语复合词常不加变化就作修饰语，因此整个复合词直接放在被修饰名词之前。"},{"no":"05","title":"A contemporary group using wild food","titleCN":"当代仍以野生食物为生的群体","definition":"a present-day community that still draws much of its food from wild sources","definitionCN":"今天仍以相当部分食物取自野生来源的社群","example":"The hunter-gatherer community also sells honey at the market.","exampleCN":"这个狩猎采集社群也在市场上卖蜂蜜。","why":"the term is not only historical: some communities combine wild food with wage work and trade.","whyCN":"这个词并非只属历史：有些社群把野生食物与打工贸易结合起来。"},{"no":"06","title":"A label in development writing","titleCN":"发展话语中的标签","definition":"a category used by administrators and aid agencies when describing remote communities","definitionCN":"行政与援助机构描述偏远社群时使用的类别","example":"The report's hunter-gatherer label hid the village's wage work.","exampleCN":"报告里「狩猎采集者」的标签掩盖了该村的打工收入。","why":"outside agencies need categories, and a category can flatten a mixed livelihood into a single word.","whyCN":"外部机构需要分类，而分类会把混合生计压成一个词。"},{"no":"07","title":"A role in an ecosystem","titleCN":"生态系统中的角色","definition":"the combined niche of a predator and a plant collector within one food web","definitionCN":"同一食物网中捕食者与植物采集者合起来占的生态位","example":"The hunter-gatherer niche here is shared with bears and crows.","exampleCN":"这里的狩猎采集生态位与熊和乌鸦共享。","why":"ecology borrows the human term for animals that both hunt and collect, preserving the two halves of the compound.","whyCN":"生态学借用这个人类学术语来指既捕猎又采集的动物，保留了复合词的两半。"},{"no":"08","title":"An opportunistic searcher","titleCN":"机会式搜寻者（比喻）","definition":"figuratively, someone who takes whatever is available rather than producing systematically","definitionCN":"比喻指见什么取什么、不系统生产的人","example":"As a hunter-gatherer of ideas, he read whatever lay open on the table.","exampleCN":"作为思想的狩猎采集者，他桌上摊着什么就读什么。","why":"the compound supplies a ready image of scattered, opportunistic acquisition, which fits intellectual habits too.","whyCN":"这个复合词提供了「零散、见机获取」的现成意象，也适用于思想习惯。"}],"etymology":{"intro":{"en":"Hunter-gatherer is an English compound of two native words, each built with the agent suffix -er. There is no Latin root. Dates are approximate.","cn":"hunter-gatherer 是由两个英语本族词构成的复合词，各自由表施事的 -er 构成，没有拉丁词根。年代均为约数。"},"items":[{"era":"OLD ENGLISH HUNTIAN","en":"Huntian meant 'to chase game'. Its deeper origin is not established; it has no secure cognates outside English.","cn":"huntian 意为「追逐猎物」。其更深来源未得到证明；在英语之外没有可靠的同源词。"},{"era":"OLD ENGLISH GADERIAN","en":"Gaderian meant 'to bring together, collect', and is related to the English word together.","cn":"gaderian 意为「聚拢、收集」，与英语 together 同源。"},{"era":"ENGLISH HUNTER AND GATHERER","en":"Hunt and gather each took the agent suffix -er, giving hunter and gatherer as separate occupations.","cn":"hunt 与 gather 各自加施事后缀 -er，形成 hunter 与 gatherer 两种分开的行当。"},{"era":"COMPOUND TERM","en":"The two words were joined in the twentieth century, when anthropology wanted one category that did not privilege hunting over collecting.","cn":"这两个词在 20 世纪被连在一起，当时人类学需要一个不把狩猎凌驾于采集之上的类别。"},{"era":"TERM AND ITS CRITICS","en":"Some researchers now prefer forager, arguing that the compound overstates the role of hunting; source uncertain exactly when the compound first appeared in print.","cn":"一些研究者现在更爱用 forager，认为这个复合词夸大了狩猎的比重；该复合词最早见于印刷品的年代不确定。"}]},"similar":{"note":{"en":"The first group is the two halves of the compound and their close forms; the second names other ways of getting food.","cn":"第一组是复合词的两半及其近形；第二组是其他获取食物的方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hunter","ipa":"/ˈhʌntə/","tag":"one half only","definition":"A person who hunts; it covers only the animal half of the compound and says nothing about plants.","definitionCN":"指打猎的人；只覆盖复合词中动物那一半，不涉及植物。"},{"word":"gatherer","ipa":"/ɡæˈðərə/","tag":"the other half","definition":"A person who collects wild plants or other scattered resources; it leaves hunting out.","definitionCN":"指采集野生植物或其他零散资源的人；不含狩猎。"},{"word":"hunting","ipa":"/ˈhʌntɪŋ/","tag":"the activity","definition":"The activity of chasing and killing game; a noun of action, not the person.","definitionCN":"追逐并猎杀猎物的活动；是动作名词，不指人。"},{"word":"gathering","ipa":"/ɡæˈðərɪŋ/","tag":"collecting, also social","definition":"The act of collecting things, or a social meeting; only the first sense belongs to this compound.","definitionCN":"指收集的动作，也指聚会；只有第一义属于这个复合词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"forager","ipa":"/ˈfɒrɪdʒə/","tag":"preferred modern term","definition":"A person who searches for wild food; many anthropologists prefer it because it does not rank hunting above collecting.","definitionCN":"搜寻野生食物的人；许多人类学者偏爱这个词，因为它不把狩猎排在采集之上。"},{"word":"pastoralist","ipa":"/ˈpɑːstərəlɪst/","tag":"herding, not wild food","definition":"A person who lives by tending domesticated herds; the animals are owned rather than hunted.","definitionCN":"靠照管家养畜群生活的人；牲畜是拥有的，而非猎取的。"},{"word":"farmer","ipa":"/ˈfɑːmə/","tag":"cultivating, not collecting","definition":"A person who grows crops or keeps stock on managed land; the food is produced rather than found.","definitionCN":"在经营土地上种作物或养牲畜的人；食物是生产出来的，不是找到的。"},{"word":"fisher","ipa":"/ˈfɪʃə/","tag":"water-based","definition":"A person who catches fish; a third subsistence route often grouped with hunting and gathering in classifications.","definitionCN":"捕鱼的人；在分类中常与狩猎采集并列为第三条生计路线。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real Old English verbs, two real agent endings and the phrases the compound keeps.","cn":"正常联想：两个真实的古英语动词、两个真实的施事后缀，以及这个复合词常用的搭配。"},"normal":[{"en":"hunt + gather + -er + -er = the person who does both, hyphenated into one word.","cn":"hunt + gather + -er + -er = 两样都做的人，用连字符并成一个词。"},{"en":"Gather is related to together, so the gatherer is the one who brings scattered things in.","cn":"gather 与 together 同源，因此 gatherer 就是把零散东西收拢起来的人。"},{"en":"The usual frames are society, band, lifestyle and diet.","cn":"常见框架是 society、band、lifestyle、diet。"},{"en":"The plural is simply hunter-gatherers; the compound stays unhyphenated in modern style guides but is often hyphenated for clarity.","cn":"复数直接加 -s；现代体例指南多不加连字符，但为清晰常保留连字符。"},{"en":"The word contains no Latin, so its affix story is all English.","cn":"这个词不含拉丁成分，因此它的构词故事全是英语的。"}],"abstract":[{"en":"Picture a hand holding a spear and a fibre bag at the same time.","cn":"想象一只手同时握着木矛与纤维袋。"},{"en":"Picture two footprints, one from chasing and one from stooping to pick.","cn":"想象两个脚印，一个来自追赶，一个来自弯腰采摘。"},{"en":"Picture a larder that is the whole landscape, opened a little each day.","cn":"想象一整片风景就是食物柜，每天只打开一点点。"}]},"examples":[{"en":"The band of hunter-gatherers moved camp when the waterhole dried.","cn":"水洼干涸后，这群狩猎采集者搬了营。"},{"en":"The museum compares hunter-gatherer tool kits from three continents.","cn":"博物馆比较来自三个大陆的狩猎采集工具组合。"},{"en":"Modern hunter-gatherer communities also trade with settled neighbours.","cn":"当代狩猎采集社群也与定居邻人贸易。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「喊它该着」——喊它（猎物）该着跑，一边喊一边捡，猎与采两手都干，就是狩猎采集者。","word":"hunter-gatherer"},"root":"hunter 出自古英语 huntian「追逐猎物」，加施事后缀 -er；gatherer 出自古英语 gaderian「聚拢、收集」，与 together 同源，也加 -er。两者在 20 世纪合成人类学术语，全词无拉丁词根。","sensesIntro":{"en":"Eight senses start with the individual, widen to the society, the archaeological label and the attributive use, then move to living communities, policy labels, an ecological niche and a metaphorical searcher.","cn":"八个义项从个人开始，扩到社会、考古标签与定语用法，再到当代社群、政策标签、生态位与比喻性的搜寻者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a spear in one hand and a gathering bag on the back.","cn":"核心意象：一手握矛，背上背一只采集袋。"},"chain":["THE INDIVIDUAL","THE SOCIETY","THE SITE CATEGORY","THE PRACTICE","THE ECOSYSTEM ROLE","THE METAPHOR"],"branches":[{"senses":"义项 01 · 02","en":"PERSON AND PEOPLE: one worker and a whole society are the same economy at two scales.","cn":"个人与人群：一个劳作者与整个社会，是同一经济在两个尺度上的样子。"},{"senses":"义项 03","en":"THE DIG: archaeology files the term onto sites and tools it cannot watch being used.","cn":"发掘：考古学把这个词归档到那些无法现场观察其使用的遗址与工具上。"},{"senses":"义项 04 · 05","en":"PRACTICE AND PRESENT DAY: the compound modifies diets and also names communities still living this way.","cn":"做法与当下：这个复合词既修饰饮食，也指仍这样生活的社群。"},{"senses":"义项 06","en":"THE LABEL: outside agencies use the word as a box, which can hide mixed livelihoods.","cn":"标签：外部机构把这个词当格子用，从而可能掩盖混合生计。"},{"senses":"义项 07 · 08","en":"NICHE AND METAPHOR: animals that both hunt and collect share the niche, and an opportunistic reader shares the image.","cn":"生态位与比喻：既猎又采的动物共享这一生态位，见机而读的人也共享这一意象。"}]},"affixes":{"intro":{"en":"Hunter-gatherer is made of two native English verbs, two agent endings and a hyphen, with no Latin layer at all.","cn":"hunter-gatherer 由两个英语本族动词、两个施事后缀与一个连字符构成，完全没有拉丁层。"},"latinIntro":{"en":"No Latin relative exists for either half; medieval Latin had to borrow Germanic words for fodder, and it never supplied a word for hunting of this kind.","cn":"两半都没有拉丁亲戚；中世纪拉丁语反而要借日耳曼词来表示饲料，也从未提供这类狩猎的词。"},"items":[{"word":"hunt","structure":"huntian (Old English verb)","meaning":"to chase game","meaningCN":"追逐猎物","example":"The verb survives unchanged in modern English.","exampleCN":"这个动词在现代英语中原样保留。"},{"word":"gather","structure":"gaderian (Old English verb)","meaning":"to collect, bring together","meaningCN":"收集；聚拢","example":"Gather is related to together.","exampleCN":"gather 与 together 同源。"},{"word":"-er","structure":"-er (Old English agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix makes hunter and gatherer.","exampleCN":"这个后缀构成 hunter 与 gatherer。"},{"word":"hunter","structure":"hunt + -er","meaning":"a person who hunts","meaningCN":"猎人","example":"The hunter followed the herd for two days.","exampleCN":"猎人跟了兽群两天。"},{"word":"gatherer","structure":"gather + -er","meaning":"a person who collects","meaningCN":"采集者","example":"The gatherer filled a bag with acorns.","exampleCN":"采集者装了一袋橡子。"},{"word":"hunter-gatherer","structure":"hunter + gatherer (compound)","meaning":"one who lives by both activities","meaningCN":"靠两种活动为生的人","example":"The term was coined for a whole economy.","exampleCN":"这个术语是为整套经济而造的。"},{"word":"hunter-gatherers","structure":"hunter-gatherer + -s (plural)","meaning":"people living by wild food","meaningCN":"以野生食物为生的人们","example":"Hunter-gatherers moved with the seasons.","exampleCN":"狩猎采集者随季节迁移。"},{"word":"hunter-fisher-gatherer","structure":"hunter + fisher + gatherer","meaning":"a three-part term used where fishing matters","meaningCN":"在渔业重要处使用的三段式术语","example":"Coastal groups are often called hunter-fisher-gatherers.","exampleCN":"沿海群体常被称作狩猎捕鱼采集者。"}],"latinEntries":[],"derivatives":[{"word":"hunter-gatherers","structure":"hunter-gatherer + -s (plural)","meaning":"the plural naming whole communities","meaningCN":"指整个群体的复数形式"},{"word":"hunter-gathererism","structure":"hunter-gatherer + -ism (rare)","meaning":"the way of life of such societies","meaningCN":"此类社会的生活方式"}]}},{"word":"foraging","ipa_uk":"/ˈfɒrɪdʒɪŋ/","ipa_us":"/ˈfɔːrɪdʒɪŋ/","definition_zh":"觅食；采集野生食物；四处搜寻（物资或信息）","definition_en":"the activity of searching for wild food or for scattered resources","core_image":"一只低头在灌木下翻找的手与一张同时扫过地面的眼睛，路径弯弯曲曲没有直线","scene":"天刚亮，羊群已经散到篱笆下，The flock spends the morning foraging along the hedgerow.","sceneCN":"这里 foraging 指「动物在野地里搜寻食物」（第 2 个义项：动物觅食行为）；句意为羊群在篱笆边觅食了整个上午。图中可辨识物件：篱笆、低头啃食的羊、露水草叶、弯曲的行进路线。","pos":[{"tag":"n.","zh":"觅食；采集（不可数）"},{"tag":"v.","zh":"forage 的现在分词／动名词"}],"collocations":[{"phrase":"foraging behaviour","zh":"觅食行为"},{"phrase":"foraging trip","zh":"觅食出行"},{"phrase":"optimal foraging","zh":"最优觅食"},{"phrase":"foraging strategy","zh":"觅食策略"},{"phrase":"foraging society","zh":"采集社会"},{"phrase":"information foraging","zh":"信息觅食"}],"forms":[{"label":"不可数名词","form":"foraging"},{"label":"动词原形","form":"forage"},{"label":"过去式","form":"foraged"},{"label":"三单","form":"forages"}],"derivatives":[{"word":"forage","pos":"v./n.","zh":"觅食；饲料"},{"word":"forager","pos":"n.","zh":"觅食者；采集者"},{"word":"foraged","pos":"adj.","zh":"采来的；觅得的"},{"word":"forageable","pos":"adj.","zh":"可供觅食的"}],"senses":[{"no":"01","title":"People searching for wild food","titleCN":"人搜寻野生食物","definition":"the activity of finding and collecting wild plants, fungi or small animals for food","definitionCN":"寻找并采集野生植物、菌类或小动物作食物的活动","example":"Foraging fills the gap between the last stored grain and the new harvest.","exampleCN":"觅食填补了存粮吃完到新粮收割之间的缺口。","why":"foraging is the gerund of forage, so it names the ongoing search rather than a single find.","whyCN":"foraging 是 forage 的动名词，指持续进行的搜寻，而非某一次收获。"},{"no":"02","title":"Animals searching for food","titleCN":"动物搜寻食物","definition":"the feeding behaviour of an animal as it searches for food across a patch","definitionCN":"动物在某一地块上搜寻食物时的取食行为","example":"Deer foraging at dusk damage more saplings than deer foraging at noon.","exampleCN":"黄昏觅食的鹿比正午觅食的鹿啃坏更多幼树。","why":"ecology needed a neutral word for the search itself, separate from killing or grazing, and the gerund supplied it.","whyCN":"生态学需要一个中性的词专指「搜寻」这一动作，与捕杀或放牧区分，动名词正好提供。"},{"no":"03","title":"A theory of optimal search","titleCN":"最优搜寻的理论","definition":"the branch of ecology that models how an animal should distribute its search effort","definitionCN":"生态学中模拟动物应如何分配搜寻努力的分支","example":"Optimal foraging predicts that a bird leaves a patch when the return rate drops.","exampleCN":"最优觅食理论预测，当回报率下降时鸟会离开这块地。","why":"if search is a cost, it can be modelled, and the gerund becomes the name of the model.","whyCN":"既然搜寻是一种成本，就可以建模，动名词于是成了模型的名称。"},{"no":"04","title":"A mode of subsistence","titleCN":"一种生计方式","definition":"a way of life based on wild food rather than cultivation or herding","definitionCN":"以野生食物而非耕作或畜牧为基础的生活方式","example":"Foraging societies move with the ripening of different plants.","exampleCN":"采集社会随不同植物的成熟而迁移。","why":"anthropology turned the activity into a category, contrasting foraging with farming and herding.","whyCN":"人类学把这一活动变成类别，与农耕、畜牧相对举。"},{"no":"05","title":"Searching for any needed supplies","titleCN":"搜寻任何所需物资","definition":"searching widely through available things to find what is needed","definitionCN":"在可用之物中四处搜寻所需","example":"Foraging through the drawers finally produced a candle.","exampleCN":"翻遍抽屉，终于找到一根蜡烛。","why":"the wild-food search loosens into any search through scattered stock.","whyCN":"野生食物的搜寻放宽为对任何零散存货的搜寻。"},{"no":"06","title":"Information foraging","titleCN":"信息觅食","definition":"the search for useful information treated as a foraging problem","definitionCN":"把有用信息的搜寻当作觅食问题来处理","example":"Information foraging explains why readers abandon a page after two paragraphs.","exampleCN":"信息觅食解释了读者为何读两段就弃页。","why":"the model transfers because both food and information come in patches with declining returns.","whyCN":"模型之所以能迁移，是因为食物与信息都以「地块」形式出现，回报都会递减。"},{"no":"07","title":"Bees collecting from flowers","titleCN":"蜜蜂在花间采集","definition":"the round of flower visits by a bee or colony gathering nectar and pollen","definitionCN":"蜜蜂或蜂群为采蜜与花粉而进行的一轮访花","example":"Bee foraging peaks when the orchard is in full flower.","exampleCN":"果园盛花时蜜蜂采集达到高峰。","why":"bees are the standard case where searching and collecting are one continuous motion.","whyCN":"蜜蜂是「搜寻与采集连成一个动作」的标准案例。"},{"no":"08","title":"Historical foraging by soldiers","titleCN":"历史上军队就地征粮","definition":"the old practice of soldiers collecting food and fodder from the countryside","definitionCN":"士兵从乡间收集食物与饲料的旧做法","example":"Army foraging stripped the valley before the troops arrived.","exampleCN":"军队尚未抵达，征粮已把山谷搜刮一空。","why":"this sense comes from the noun forage as fodder, not from wild-food search, but the gerund covers both.","whyCN":"这一义出自名词 forage「饲料」，而非野生食物搜寻，但动名词把两者都盖住了。"}],"etymology":{"intro":{"en":"Foraging is the English gerund of forage, which came from Old French fourrage 'fodder', of Germanic origin. Dates are approximate.","cn":"foraging 是 forage 的英语动名词，forage 出自古法语 fourrage「饲料」，源头为日耳曼语。年代均为约数。"},"items":[{"era":"FRANKISH FODR","en":"A Germanic word for fodder, reconstructed as Frankish fodr, underlies the French forms; the reconstruction is standard but unattested in writing.","cn":"一个表示饲料的日耳曼词，重构为法兰克语 fodr，是法语各形的基础；此重构属常规做法，却无书面书证。"},{"era":"OLD FRENCH FUERRE","en":"Fuerre meant 'fodder, straw', the dry feed cut for animals in winter.","cn":"fuerre 意为「饲料、草料」，即冬天为牲畜割下的干料。"},{"era":"OLD FRENCH FOURRAGE","en":"Fourrage added a collective suffix and meant the whole business of cutting and carrying fodder, including the right to do so.","cn":"fourrage 加了集合后缀，指割取搬运饲料的整套事务，包括这样做的权利。"},{"era":"ENGLISH FORAGE","en":"English borrowed forage in the fourteenth century as a noun for animal feed, then as a verb for collecting it.","cn":"英语在 14 世纪借入 forage，先作牲畜饲料的名词，后作收集饲料的动词。"},{"era":"FORAGING IN SCIENCE","en":"Ecology adopted foraging in the twentieth century for the search behaviour of animals, and anthropology extended it to wild-food economies.","cn":"生态学在 20 世纪采用 foraging 指动物的搜寻行为，人类学又把它扩展到野生食物经济。"},{"era":"LATIN-LOOKING FORM","en":"Medieval Latin fodrum is a borrowing of the Germanic word, not a Latin relative, so no Latin etymology should be claimed here; source uncertain for the earliest Latin record.","cn":"中世纪拉丁 fodrum 是借入的日耳曼词，并非拉丁同族词，因此此处不应主张拉丁词源；最早的拉丁记录年代不确定。"}]},"similar":{"note":{"en":"The first group shares the forage stem or looks like it; the second names other ways of getting food or goods.","cn":"第一组共用 forage 词干或形近；第二组是获取食物或物资的其他方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"forage","ipa":"/fəˈrɪdʒ/","tag":"the base verb and noun","definition":"To search for food, or the feed itself; the gerund names the activity, the base form names the act or the stuff.","definitionCN":"指搜寻食物，或指饲料本身；动名词指活动，原形指动作或东西。"},{"word":"forager","ipa":"/ˈfɒrɪdʒə/","tag":"the person","definition":"A person or animal that forages; the noun of agent, not the activity.","definitionCN":"进行觅食的人或动物；是施事名词，不是活动本身。"},{"word":"fodder","ipa":"/ˈfɒdə/","tag":"the feed, same Germanic root","definition":"Dry feed for livestock, from the same Germanic stock as forage, but never used for the search itself.","definitionCN":"家畜的干饲料，与 forage 同出日耳曼语，但从不指搜寻动作。"},{"word":"forge","ipa":"/fɔːdʒ/","tag":"looks close, different root","definition":"To shape metal by heating and hammering, or to fake a document; it shares spelling shape but not origin.","definitionCN":"指加热锤打金属成形，或伪造文书；拼写形状相近，来源却不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"scavenging","ipa":"/ˈskævɪdʒɪŋ/","tag":"taking what is left","definition":"Feeding on dead or discarded matter; it implies no search for living prey or fresh plants.","definitionCN":"以死亡或丢弃之物为食；不涉及寻找活猎物或新鲜植物。"},{"word":"rummaging","ipa":"/ˈrʌmɪdʒɪŋ/","tag":"searching through things","definition":"Searching unsystematically through a container or pile; it lacks the food and ecology sense.","definitionCN":"在容器或堆里不系统地翻找；缺少食物与生态含义。"},{"word":"grazing","ipa":"/ˈɡreɪzɪŋ/","tag":"eating growing grass","definition":"Eating grass or low plants where they grow; it is feeding, not searching.","definitionCN":"就地把草或低矮植物吃掉；是取食，不是搜寻。"},{"word":"hunting","ipa":"/ˈhʌntɪŋ/","tag":"chasing prey","definition":"Chasing and killing animals; the target is mobile and the method is pursuit.","definitionCN":"追逐并猎杀动物；目标会动，方法是追捕。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the French fodder word, the scientific career of the gerund and the phrases it keeps.","cn":"正常联想：法语「饲料」词、这个动名词在科学中的经历，以及它保留的搭配。"},"normal":[{"en":"fourrage 'fodder' + -ing = the business of getting feed, later any search for food.","cn":"fourrage「饲料」+ -ing = 弄饲料这件事，后来泛指找食物。"},{"en":"The same Germanic stock gives fodder, so fodder and forage are cousins, not twins.","cn":"同一日耳曼来源给出 fodder，因此 fodder 与 forage 是表亲，不是双胞胎。"},{"en":"In ecology the word pairs with patch, strategy and optimal.","cn":"在生态学里，这个词与 patch、strategy、optimal 搭配。"},{"en":"Foraging is uncountable: one does not say a foraging, but one may say a foraging trip.","cn":"这个词不可数：不说「一次觅食」，但可以说「一趟觅食之行」。"},{"en":"The gerund names the activity, while forager names the one who does it.","cn":"动名词指活动，forager 指做这件事的人。"}],"abstract":[{"en":"Picture a path that bends wherever a berry bush bends it.","cn":"想象一条路，哪儿有浆果丛就往哪儿弯。"},{"en":"Picture a hand that never leaves the pocket empty but never fills it either.","cn":"想象一只手，口袋从没空过，也从来没满过。"},{"en":"Picture a clock measured in finds rather than in hours.","cn":"想象一只以「找到几次」而非小时计时的钟。"}]},"examples":[{"en":"Foraging along the shore produced mussels, sorrel and a few crabs.","cn":"沿岸觅食收获了贻贝、酢浆草和几只蟹。"},{"en":"The study tracks foraging routes with collars and satellites.","cn":"这项研究用项圈与卫星追踪觅食路线。"},{"en":"Optimal foraging assumes that animals maximise energy per unit of search.","cn":"最优觅食假设动物使单位搜寻时间内的能量最大化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「佛瑞金」听成「佛来进」——见什么能吃的就往里进，走一路找一路，就是觅食。","word":"foraging"},"root":"forage 出自古法语 fourrage「饲料」，再上为 fuerre「草料」，源头是法兰克语 fodr 一类日耳曼词；中世纪拉丁 fodrum 是借形，不是同族。加 -ing 构成表示活动的动名词。","sensesIntro":{"en":"Eight senses follow the search: human wild food, animal feeding, optimal search theory, the subsistence mode, any search for supplies, information search, bee visits and old army requisition.","cn":"八个义项沿「搜寻」展开：人的野生食物、动物取食、最优搜寻理论、生计方式、任何物资搜寻、信息搜寻、蜜蜂访花、旧时军队征粮。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wandering path that bends wherever food appears.","cn":"核心意象：一条哪儿有食物就往哪儿弯的路径。"},"chain":["WILD FOOD","ANIMAL FEEDING","SEARCH MODEL","SUBSISTENCE MODE","SUPPLY SEARCH","INFORMATION SEARCH"],"branches":[{"senses":"义项 01 · 02","en":"PEOPLE AND ANIMALS: the same search behaviour is named for both, with no claim about who is smarter.","cn":"人与动物：同一种搜寻行为在两者身上都成立，并不涉及谁更聪明。"},{"senses":"义项 03","en":"THE MODEL: once search has a cost, it can be optimised, and the activity becomes a theory.","cn":"模型：搜寻一旦有成本就可以优化，这一活动于是变成一套理论。"},{"senses":"义项 04","en":"THE ECONOMY: repeated search becomes a way of life, classified against farming and herding.","cn":"经济：反复的搜寻成为生活方式，并与农耕、畜牧相对分类。"},{"senses":"义项 05 · 06","en":"PATCHES OF ANYTHING: drawers and web pages can be foraged because both hold scattered returns.","cn":"任何「地块」：抽屉与网页都可「觅食」，因为两者都装着零散回报。"},{"senses":"义项 07 · 08","en":"FLOWERS AND ARMIES: bees gather nectar and soldiers once gathered fodder, both under the same word.","cn":"花与军队：蜜蜂采蜜，士兵曾征草料，两件事都落在同一个词下。"}]},"affixes":{"intro":{"en":"Foraging is a French-derived noun of fodder plus the English -ing ending; its Latin-looking medieval doublet is a borrowing.","cn":"foraging 是法语来源的「饲料」名词加英语 -ing 词尾；那个拉丁味的中世纪同形词只是借形。"},"latinIntro":{"en":"The family is Germanic, not Latin: Medieval Latin fodrum borrowed the word, so it cannot be used as proof of a Latin relative.","cn":"这个词族属日耳曼语而非拉丁语：中世纪拉丁 fodrum 借入该词，不能拿来当作拉丁同族的证据。"},"items":[{"word":"forage","structure":"fourrage (Old French, 'fodder')","meaning":"feed for animals; to collect it","meaningCN":"牲畜饲料；收集饲料","example":"The verb widened from fodder to any food search.","exampleCN":"这个动词从饲料放宽到任何食物搜寻。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"The ending makes foraging a mass noun of activity.","exampleCN":"这个结尾使 foraging 成为表示活动的不可数名词。"},{"word":"fodder","structure":"fodr (Germanic) through Old English","meaning":"dry feed for livestock","meaningCN":"家畜的干饲料","example":"Fodder was cut and stacked before winter.","exampleCN":"入冬前把草料割下堆好。"},{"word":"forager","structure":"forage + -er (agent)","meaning":"one who searches for food","meaningCN":"搜寻食物者","example":"The forager knows which mushrooms are safe.","exampleCN":"采集者知道哪些菌子安全。"},{"word":"foraging","structure":"forage + -ing","meaning":"the search for food","meaningCN":"觅食活动","example":"Foraging begins before sunrise in summer.","exampleCN":"夏天觅食在日出前开始。"},{"word":"foraged","structure":"forage + -ed (past participle)","meaning":"collected from the wild","meaningCN":"从野外采得的","example":"The menu lists foraged herbs.","exampleCN":"菜单上列着野外采来的香草。"},{"word":"forageable","structure":"forage + -able (can be)","meaning":"suitable for foraging","meaningCN":"可供觅食的","example":"The burned slope became forageable within a year.","exampleCN":"烧过的坡地一年内又可觅食了。"},{"word":"fourrage","structure":"fourrage (French noun)","meaning":"fodder; the act of collecting it","meaningCN":"饲料；收集饲料的行为","example":"French keeps the older fodder sense.","exampleCN":"法语保留了较旧的饲料义。"}],"latinEntries":[],"derivatives":[{"word":"foragings","structure":"foraging + -s (rare plural)","meaning":"separate foraging trips or bouts","meaningCN":"一次次的觅食行程"},{"word":"forageability","structure":"forageable + -ity","meaning":"the quality of being searchable for food","meaningCN":"可供觅食的程度"}]}},{"word":"forage","ipa_uk":"/fəˈrɪdʒ/","ipa_us":"/ˈfɔːrɪdʒ/","definition_zh":"觅食；搜寻；采集野生食物；（名词）饲料；草料","definition_en":"to search for food or supplies; feed for animals","core_image":"一个人蹲在灌木边把能吃的叶与果一颗颗拣进口袋，另一只手还翻着落叶层","scene":"橡树林下的落叶被拱得乱七八糟，Wild pigs forage at dusk beneath the oaks.","sceneCN":"这里 forage 指「动物在野地里搜寻食物」（第 2 个义项：动物觅食）；句意为野猪在黄昏时分到橡树下觅食。图中可辨识物件：拱开的落叶、橡子、野猪鼻吻、林下灌木。","pos":[{"tag":"v.","zh":"觅食；搜寻；采集"},{"tag":"n.","zh":"饲料；草料（不可数）"}],"collocations":[{"phrase":"forage for food","zh":"觅食"},{"phrase":"forage in the woods","zh":"在林子里采集"},{"phrase":"forage crops","zh":"饲料作物"},{"phrase":"forage for supplies","zh":"搜寻物资"},{"phrase":"forage and fodder","zh":"饲草与饲料"},{"phrase":"forage a living","zh":"靠采集糊口"}],"forms":[{"label":"三单（he/she/it）","form":"forages"},{"label":"过去式","form":"foraged"},{"label":"过去分词","form":"foraged"},{"label":"现在分词","form":"foraging"},{"label":"名词（不可数）","form":"forage"}],"derivatives":[{"word":"forager","pos":"n.","zh":"觅食者"},{"word":"foraging","pos":"n.","zh":"觅食活动"},{"word":"foraged","pos":"adj.","zh":"采来的"},{"word":"forageable","pos":"adj.","zh":"可供觅食的"}],"senses":[{"no":"01","title":"People gather wild food","titleCN":"人采集野生食物","definition":"to search for and collect wild plants, fungi or small animals as food","definitionCN":"寻找并收集野生植物、菌类或小动物作食物","example":"They forage for mushrooms after the first autumn rain.","exampleCN":"秋雨初降后，他们去采蘑菇。","why":"the verb names the search, so the object is usually the food itself or the place where it is found.","whyCN":"这个动词指搜寻，因此宾语通常是食物本身或找到它的地方。"},{"no":"02","title":"Animals search for food","titleCN":"动物搜寻食物","definition":"of an animal, to search the ground or vegetation for food","definitionCN":"指动物在地面或植被间搜寻食物","example":"Bears forage along the river before the salmon run ends.","exampleCN":"鲑鱼汛结束前，熊沿着河觅食。","why":"animals do not plan a menu, they search a patch, which is exactly what the verb describes.","whyCN":"动物不会规划菜单，它们只搜寻一块地方，这正是这个动词所描述的。"},{"no":"03","title":"Rummage through things","titleCN":"在杂物中翻找","definition":"to search through a container or pile, often messily","definitionCN":"在容器或堆里翻找，常显得凌乱","example":"He foraged in the toolbox for a matching bolt.","exampleCN":"他在工具箱里翻找一颗配套螺栓。","why":"the food search extends to any search through mixed contents, with the same feeling of picking out what is useful.","whyCN":"食物搜寻扩展到对任何混杂内容的搜寻，同样带着「挑出有用之物」的感觉。"},{"no":"04","title":"Obtain by searching","titleCN":"靠搜寻取得","definition":"to get something by searching rather than by buying or asking","definitionCN":"靠搜寻而不是购买或索取得到某物","example":"She foraged a chair and a lamp for the empty room.","exampleCN":"她为那间空房搜罗来一把椅子和一盏灯。","why":"once the verb takes a direct object, the emphasis shifts from the search to the thing obtained.","whyCN":"一旦动词带直接宾语，重点就从搜寻移到所得之物。"},{"no":"05","title":"Animal feed as a noun","titleCN":"作为名词的饲料","definition":"crops or cut plants used as feed for livestock","definitionCN":"用作牲畜饲料的作物或割下的植物","example":"The barn holds enough forage for the whole winter.","exampleCN":"谷仓里的草料够吃一整个冬天。","why":"this is the oldest sense: the noun came first and still names the stuff rather than the search.","whyCN":"这是最古老的义项：名词先出现，至今仍指东西本身，而非搜寻。"},{"no":"06","title":"Soldiers collecting supplies","titleCN":"士兵就地征取给养","definition":"historical, of troops, to take food and fodder from the surrounding country","definitionCN":"历史上指军队从周边乡间取走食物与草料","example":"The cavalry foraged the villages along the road.","exampleCN":"骑兵沿路向村庄征取给养。","why":"armies on the move could not wait for supply carts, so collecting feed locally became a military verb.","whyCN":"行军中的军队等不及辎重车，就地收集草料便成了一个军事动词。"},{"no":"07","title":"Fodder in American usage","titleCN":"美国用法中的草料","definition":"in American English, feed for horses and cattle, often hay or corn","definitionCN":"美式英语中指马牛饲料，常为干草或玉米","example":"They put up forage in the loft each August.","exampleCN":"每年八月他们往阁楼里存草料。","why":"regional farming usage kept the noun alive after the wild-food verb had become scientific.","whyCN":"在野生食物动词已科学化之后，地方农业用法仍让这个名词活着。"},{"no":"08","title":"Seize whatever is available","titleCN":"见到什么就取什么（比喻）","definition":"figuratively, to take opportunities wherever they can be found","definitionCN":"比喻指在哪儿能找到机会就在哪儿取用","example":"The young writer foraged for contacts at every opening.","exampleCN":"这位年轻作家在每次开幕酒会上搜罗人脉。","why":"the wild-food image supplies a name for opportunistic acquisition of anything scarce.","whyCN":"野生食物的意象为「对任何稀缺物的机会性获取」提供了名称。"}],"etymology":{"intro":{"en":"Forage entered English from Old French fourrage 'fodder', whose source is Germanic. Latin has only a borrowed doublet. Dates are approximate.","cn":"forage 从古法语 fourrage「饲料」进入英语，源头为日耳曼语。拉丁语只有一个借形。年代均为约数。"},"items":[{"era":"FRANKISH FODR","en":"The Germanic source is reconstructed as Frankish fodr 'fodder'; it is a reconstructed form, not a written record.","cn":"其日耳曼源头重构为法兰克语 fodr「饲料」；这是重构形式，不是书面记录。"},{"era":"OLD FRENCH FUERRE","en":"Fuerre meant fodder or straw, the winter feed cut and carried for animals.","cn":"fuerre 意为饲料或草料，即冬天割下搬运给牲畜的干料。"},{"era":"OLD FRENCH FOURRAGE","en":"Fourrage named both the feed and the right to take it from a field, a legal as well as an agricultural word.","cn":"fourrage 既指饲料，也指从田里取料的权利，既是农业词也是法律词。"},{"era":"ENGLISH NOUN","en":"English forage is recorded as a noun for animal feed in the fourteenth century.","cn":"英语 forage 在 14 世纪作为牲畜饲料名词有记录。"},{"era":"ENGLISH VERB","en":"The verb followed in the fifteenth century, first for collecting fodder and then for searching for any food.","cn":"动词在 15 世纪跟进，先指收集草料，后指搜寻任何食物。"},{"era":"SCIENTIFIC SENSE","en":"Nineteenth and twentieth century ecology fixed the verb in the neutral sense of searching for food; source uncertain for the first use in this technical sense.","cn":"19 与 20 世纪生态学把这个动词固定在「搜寻食物」的中性义上；这一技术义的首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the fodder stock or looks close; the second lists other verbs of getting food.","cn":"第一组共用「饲料」来源或形近；第二组是其他获取食物的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"forage","ipa":"/fəˈrɪdʒ/","tag":"the base form","definition":"The verb and noun themselves; the gerund foraging names the activity, this form names the act or the feed.","definitionCN":"动词与名词本身；动名词 foraging 指活动，这个形式指动作或饲料。"},{"word":"forager","ipa":"/ˈfɒrɪdʒə/","tag":"the person","definition":"One who forages; an agent noun, not a form of the verb.","definitionCN":"进行觅食的人；是施事名词，不是动词形式。"},{"word":"fodder","ipa":"/ˈfɒdə/","tag":"feed only","definition":"Animal feed, from the same Germanic stock; it never means to search.","definitionCN":"牲畜饲料，同出日耳曼语；从不表示搜寻。"},{"word":"forge","ipa":"/fɔːdʒ/","tag":"shape-alike, different origin","definition":"To heat and hammer metal, or to counterfeit; the resemblance is in spelling only.","definitionCN":"指加热锤打金属，或伪造；相似只在拼写。"}]},{"heading":"NEAR MEANING","entries":[{"word":"scavenge","ipa":"/ˈskævɪndʒ/","tag":"take the discarded","definition":"To feed on dead animals or waste; the food is already dead or thrown away.","definitionCN":"以死动物或废弃物为食；食物已是死的或被丢弃的。"},{"word":"rummage","ipa":"/ˈrʌmɪdʒ/","tag":"messy search","definition":"To search through a receptacle by moving things about; no food is implied.","definitionCN":"翻动容器里的东西来找；不隐含食物。"},{"word":"graze","ipa":"/ɡreɪz/","tag":"eat where it grows","definition":"To eat grass or low plants in place; the animal does not carry food away.","definitionCN":"就地吃草或低矮植物；动物并不把食物带走。"},{"word":"hunt","ipa":"/hʌnt/","tag":"pursue prey","definition":"To chase and kill animals; the food must be caught, not collected.","definitionCN":"追逐并杀死动物；食物必须被捕获，而非收集。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the fodder noun, the search verb that grew out of it and the phrases it keeps.","cn":"正常联想：饲料名词、由它长出的搜寻动词，以及它保留的搭配。"},"normal":[{"en":"fourrage 'fodder' first, then the verb 'to collect fodder', then 'to search for any food'.","cn":"先有 fourrage「饲料」，再有动词「收集饲料」，最后泛指「搜寻任何食物」。"},{"en":"Fodder and forage come from the same Germanic stock, so they are relatives, not synonyms.","cn":"fodder 与 forage 同出日耳曼语，是亲戚，不是同义词。"},{"en":"The usual objects are food, supplies, crops and the woods.","cn":"常见宾语是「食物」「补给」「庄稼」「林地」。"},{"en":"As a noun it is uncountable in the feed sense: some forage, not a forage.","cn":"作名词表饲料时不可数：只带 some 一类量词，不能加不定冠词。"},{"en":"The verb is regular: forages, foraged, foraged, foraging.","cn":"这个动词规则变化：forages、foraged、foraged、foraging。"}],"abstract":[{"en":"Picture a pocket that fills slowly and empties as slowly as it fills.","cn":"想象一只口袋，装满得慢，空得也一样慢。"},{"en":"Picture a table set by whatever the walk happened to find.","cn":"想象一桌饭，菜色由那趟走路碰巧找到什么决定。"},{"en":"Picture a map with no roads, only places where something edible grows.","cn":"想象一幅没有路的地图，只标着长着可食之物的地方。"}]},"examples":[{"en":"The children foraged for blackberries along the railway line.","cn":"孩子们沿着铁路线采黑莓。"},{"en":"Farmers store forage for the months when the herd cannot graze.","cn":"农夫储存草料，供畜群无法放牧的月份使用。"},{"en":"The platoon was ordered to forage rather than wait for supply trucks.","cn":"这个排奉命就地征取给养，而不是等补给车。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「佛瑞吉」听成「佛来急」——一见有吃的就急急过去，走的不是路，是能吃的方向，就是觅食。","word":"forage"},"root":"古法语 fourrage「饲料」出自 fuerre「草料」，再上为法兰克语 fodr 一类日耳曼词；英语 14 世纪先作名词，15 世纪起作动词，义从「收集草料」扩为「搜寻食物」。","sensesIntro":{"en":"Eight senses run from people and animals searching, through rummaging and obtaining, to the feed noun, army requisition, American fodder and a metaphor for grabbing opportunities.","cn":"八个义项从人与动物的搜寻，经翻找与获取，到饲料名词、军队征取、美国草料义，最后是抓取机会的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stooping figure picking edible leaves into a bag.","cn":"核心意象：一个弯腰把可食叶片拣进袋里的人。"},"chain":["SEARCH FOR FOOD","ANIMAL FEEDING","RUMMAGE","OBTAIN BY SEARCH","ANIMAL FEED","OPPORTUNISM"],"branches":[{"senses":"义项 01 · 02","en":"HUMAN AND ANIMAL SEARCH: the same verb covers both because both look for scattered food.","cn":"人与动物的搜寻：同一个动词覆盖两者，因为两者都在找零散的食物。"},{"senses":"义项 03 · 04","en":"FROM SEARCH TO POSSESSION: rummaging and obtaining are the middle and the end of one motion.","cn":"从搜寻到占有：翻找与获取是同一动作的中段与终点。"},{"senses":"义项 05 · 07","en":"THE STUFF ITSELF: the noun for feed survives beside the verb for searching.","cn":"东西本身：表饲料的名词与表搜寻的动词并存。"},{"senses":"义项 06","en":"ARMY LOGISTICS: troops without carts forage the countryside, a historical branch of the feed sense.","cn":"军队后勤：没有辎重车的部队就地征粮，这是饲料义的历史分支。"},{"senses":"义项 08","en":"OPPORTUNISM: the image of picking up whatever is found is applied to contacts and chances.","cn":"机会主义：见到什么就捡的意象被用在人脉与机会上。"}]},"affixes":{"intro":{"en":"Forage is a French noun of fodder with a Germanic core; English added verb endings and a gerund.","cn":"forage 是法语「饲料」名词，核心属日耳曼语；英语为它加上了动词词尾与动名词。"},"latinIntro":{"en":"There is no Latin relative. Medieval Latin fodrum is a loan from Germanic, and saying otherwise would invent an etymology.","cn":"没有拉丁同族词。中世纪拉丁 fodrum 是日耳曼借词，若说成拉丁同族就是编造词源。"},"items":[{"word":"forage","structure":"fourrage (Old French, 'fodder')","meaning":"feed; to collect feed","meaningCN":"饲料；收集饲料","example":"The noun and the verb share one form.","exampleCN":"名词与动词同形。"},{"word":"-age","structure":"-age (French collective suffix)","meaning":"a body or business of","meaningCN":"……的集合或事务","example":"Fourrage named the whole business of fodder.","exampleCN":"fourrage 指与草料有关的整套事务。"},{"word":"forages","structure":"forage + -s (third person singular)","meaning":"he, she or it searches","meaningCN":"他、她或它搜寻","example":"The herd forages before the heat.","exampleCN":"畜群在暑热前觅食。"},{"word":"foraged","structure":"forage + -ed (past)","meaning":"searched or collected","meaningCN":"搜寻过；采集过","example":"They foraged the shore at low tide.","exampleCN":"退潮时他们在岸边采集。"},{"word":"foraging","structure":"forage + -ing (participle)","meaning":"searching for food","meaningCN":"正在觅食","example":"Bees are foraging on the clover.","exampleCN":"蜜蜂正在三叶草上采集。"},{"word":"forager","structure":"forage + -er (agent)","meaning":"one who searches for food","meaningCN":"觅食者","example":"Each forager keeps a fixed route.","exampleCN":"每个觅食者都有固定路线。"},{"word":"forageable","structure":"forage + -able (capable)","meaning":"able to be searched for food","meaningCN":"可觅食的","example":"The marsh is forageable in spring.","exampleCN":"这片沼泽春天可以觅食。"},{"word":"fodder","structure":"fodr (Germanic) + -er","meaning":"cut feed for animals","meaningCN":"为牲畜割下的饲料","example":"Fodder is drier than fresh forage.","exampleCN":"干草料比新鲜饲草更干。"}],"latinEntries":[],"derivatives":[{"word":"forageable","structure":"forage + -able","meaning":"fit to be foraged","meaningCN":"适合觅食的"},{"word":"forager","structure":"forage + -er","meaning":"a person or animal that forages","meaningCN":"觅食的人或动物"}]}},{"word":"subsistence","ipa_uk":"/sʌbˈsɪstəns/","ipa_us":"/sʌbˈsɪstəns/","definition_zh":"生存；生计；勉强维持生活的资料；自给性生产；（哲）独立存在","definition_en":"the means by which life is supported, or the state of existing independently","core_image":"一只粗陶碗里盛着刚够一顿的粥，碗底就是全部家底，桌下没有第二袋粮","scene":"山坳里几亩薄田只够一家人吃用，The family's subsistence rests on one terrace field and two goats.","sceneCN":"这里 subsistence 指「维持一家人生存的生计来源」（第 1 个义项：赖以活命的生计）；句意为这家人的生计全靠一块梯田和两只山羊。图中可辨识物件：粗陶碗、薄田、山羊、空粮袋。","pos":[{"tag":"n.","zh":"生存；生计；生计资料（不可数）"}],"collocations":[{"phrase":"means of subsistence","zh":"生计资料；谋生手段"},{"phrase":"subsistence level","zh":"仅够维生的水平"},{"phrase":"subsistence farming","zh":"自给农业"},{"phrase":"subsistence wage","zh":"糊口工资"},{"phrase":"bare subsistence","zh":"仅足糊口"},{"phrase":"subsistence allowance","zh":"生活津贴"}],"forms":[{"label":"不可数（无复数）","form":"subsistence"},{"label":"动词","form":"subsist"},{"label":"形容词","form":"subsistent"}],"derivatives":[{"word":"subsist","pos":"v.","zh":"维持生活；存在"},{"word":"subsistent","pos":"adj.","zh":"存在的；自存的"},{"word":"subsistency","pos":"n.","zh":"生存状态（罕用）"},{"word":"subsistences","pos":"n.","zh":"多种维生体系（罕用复数）"}],"senses":[{"no":"01","title":"The means of supporting life","titleCN":"维持生活的资料与手段","definition":"the food, money or resources by which a person or group stays alive","definitionCN":"使人或群体得以活命的食物、钱或资源","example":"The river is the main means of subsistence for six villages.","exampleCN":"这条河是六个村庄主要的生计来源。","why":"the Latin word means 'standing firm underneath', so subsistence is what stands under a life and holds it up.","whyCN":"这个拉丁词意为「在下面站稳」，因此 subsistence 是撑住生命、把它托起来的东西。"},{"no":"02","title":"Bare survival, with nothing spare","titleCN":"仅足活命，别无余裕","definition":"the condition of having only just enough to live on","definitionCN":"只有刚刚够活、没有余裕的状态","example":"The flood cut the village to subsistence for two years.","exampleCN":"洪水使这个村庄两年只能勉强糊口。","why":"when the supporting floor is the only floor, existence is reduced to bare maintenance.","whyCN":"当支撑的那层地板就是唯一的地板时，存在便被压缩为纯粹的维持。"},{"no":"03","title":"Production for one's own use","titleCN":"为自用而生产","definition":"an economy in which people produce food and goods mainly for themselves rather than for sale","definitionCN":"人们主要为自用而非出售而生产食物与物品的经济","example":"Subsistence occupies most of the household's working hours.","exampleCN":"自给生产占去这户人家大部分的劳动时间。","why":"if nothing is sold, the whole effort is aimed at the living of the producers, which is precisely what the word names.","whyCN":"若什么都不卖，全部努力就只指向生产者自己的生活，这正是这个词所指。"},{"no":"04","title":"Independent existence in philosophy","titleCN":"哲学上的独立存在","definition":"the state of existing in itself rather than as a property of something else","definitionCN":"自身存在，而非作为他物的属性存在","example":"The debate asks whether relation has any subsistence apart from its terms.","exampleCN":"这场争论追问：关系离开其项之后是否还有独立存在。","why":"the word translated Greek hypostasis, a standing-under, and philosophy kept that technical sense of self-standing existence.","whyCN":"这个词曾译希腊语 hypostasis「在下面站立者」，哲学保留了「自立存在」这一专门义。"},{"no":"05","title":"The minimum level of income","titleCN":"最低收入水平","definition":"the lowest income or wage on which a person can live","definitionCN":"一个人赖以活命的最低收入或工资","example":"The board set a subsistence level and indexed it to grain prices.","exampleCN":"委员会定下一条维生线，并与粮价挂钩。","why":"policy needs a measurable floor, so the abstract idea of support becomes a number called the subsistence level.","whyCN":"政策需要一条可测量的底线，于是抽象的「支撑」变成一个叫「维生线」的数字。"},{"no":"06","title":"Means of support in law","titleCN":"法律上的扶养来源","definition":"in law, the provision of the necessities of life, as in a claim for support","definitionCN":"法律上提供生活必需品，如扶养请求中的给付","example":"The petition asked for subsistence pending the division of the estate.","exampleCN":"这份申请要求在遗产分割前先行给付生活费。","why":"courts must name what a claimant lives on while a case runs, so the general sense is narrowed to a legal entitlement.","whyCN":"法院必须说明当事人在诉讼期间靠什么生活，一般义因此被收窄为法律上的给付权利。"},{"no":"07","title":"Attributive use: barely enough to live","titleCN":"作定语：仅够维生的","definition":"used before a noun to describe production or income at survival level","definitionCN":"放在名词前，描述处于生存水平的生产或收入","example":"Subsistence crops are eaten, not sold.","exampleCN":"自给作物是拿来吃的，不是拿来卖的。","why":"English routinely presses nouns into modifiers, so the abstract noun can describe a whole category of farming.","whyCN":"英语习惯把名词压作修饰语，因此这个抽象名词可以描述整整一类农业。"},{"no":"08","title":"An allowance for living costs","titleCN":"用于生活开支的津贴","definition":"a payment made to cover basic living costs, as for soldiers, students or trainees","definitionCN":"为支付基本生活开支而发放的款项，如给士兵、学生或受训者","example":"The crew drew a subsistence allowance while ashore.","exampleCN":"船员上岸期间领取生活津贴。","why":"institutions converted the idea of support into a fixed payment, and the word followed the money.","whyCN":"机构把「支撑」的观念变成一笔固定款项，这个词也就跟着钱走。"}],"etymology":{"intro":{"en":"Subsistence comes from Late Latin subsistentia, built on subsistere 'to stand firm under'. Dates are approximate.","cn":"subsistence 出自晚期拉丁 subsistentia，建于 subsistere「在下面站稳」之上。年代均为约数。"},"items":[{"era":"LATIN SISTERE","en":"Sistere meant 'to cause to stand, to stand still'. Its deeper origin is not fully settled; the link to a root meaning 'to stand' is standard but reconstructed.","cn":"sistere 意为「使站立、站住」。其更深来源未有定论；与意为「站」的词根的联系属常规说法，但为重构。"},{"era":"LATIN SUBSISTERE","en":"Sub- 'under' plus sistere gave subsistere 'to stand under, hold out, remain', used of things that keep their place.","cn":"sub-「在下」加 sistere 构成 subsistere「站在下面、撑住、留存」，用于指保持位置之物。"},{"era":"LATE LATIN SUBSISTENTIA","en":"Subsistentia abstracted the verb into the state of standing under, and was used to render Greek hypostasis in Christian and philosophical writing.","cn":"subsistentia 把这个动词抽象为「在下面站立」的状态，在基督教与哲学写作中用来翻译希腊语 hypostasis。"},{"era":"ENGLISH ENTRY","en":"English subsistence appears in the sixteenth century, first in theology and philosophy, then in ordinary talk about living.","cn":"英语 subsistence 在 16 世纪出现，先用于神学与哲学，后进入日常谈生活的语言。"},{"era":"ECONOMIC SENSE","en":"By the eighteenth century it named the material means of living, and economists built phrases such as subsistence level and subsistence farming.","cn":"到 18 世纪，它指物质生计资料，经济学家据此造出维生线、自给农业等说法。"},{"era":"TECHNICAL SURVIVAL","en":"The philosophical sense of independent existence survives in theology and metaphysics, largely beside the everyday sense.","cn":"哲学上「独立存在」的义项存留在神学与形而上学中，大体与日常义并行。"}]},"similar":{"note":{"en":"The first group shares the Latin standing verb or looks like it; the second lists words for what keeps a life going.","cn":"第一组共用拉丁「站立」动词或形近；第二组是维持生命的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"subsist","ipa":"/sʌbˈsɪst/","tag":"the verb","definition":"To stay alive, usually on very little; the verb names the surviving, the noun names the means.","definitionCN":"指靠极少的东西活下去；动词指存活，名词指手段。"},{"word":"subsistent","ipa":"/sʌbˈsɪstənt/","tag":"the adjective","definition":"Existing independently, or barely maintaining life; an adjective form, not the resources themselves.","definitionCN":"指独立存在的，或勉强维持生命的；是形容词，不是资源本身。"},{"word":"substance","ipa":"/ˈsʌbstəns/","tag":"different Latin verb","definition":"Material or essential nature, from substare 'to stand beneath'; related in image but not the same word.","definitionCN":"指物质或本质，出自 substare「在下面站」；意象相关，却不是同一个词。"},{"word":"insistence","ipa":"/ɪnˈsɪstəns/","tag":"same verb, different prefix","definition":"The act of demanding firmly, from insistere 'to stand upon'; it shares sistere but means something else.","definitionCN":"指坚决要求，出自 insistere「站在其上」；与 sistere 同源，意思却不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"livelihood","ipa":"/ˈlaɪvlihʊd/","tag":"the way one earns a living","definition":"The work or income by which a person supports life; it stresses earning rather than merely surviving.","definitionCN":"指一个人赖以为生的工作或收入；强调挣钱谋生，而非仅仅存活。"},{"word":"sustenance","ipa":"/ˈsʌstənəns/","tag":"food that keeps you going","definition":"Food and drink regarded as what keeps a person alive; it is concrete nourishment, not an abstract means.","definitionCN":"指维持生命的食物与饮料；是具体的营养，而非抽象手段。"},{"word":"survival","ipa":"/səˈvaɪvəl/","tag":"continuing to exist","definition":"The fact of continuing to live or exist, especially after danger; it names the outcome, not the support.","definitionCN":"指继续活着或存在的事实，尤指在危险之后；指结果，而非支撑。"},{"word":"maintenance","ipa":"/meɪnˈtenəns/","tag":"keeping something going","definition":"The work and money needed to keep something in working order; often applied to machines and families alike.","definitionCN":"维持某物运转所需的工作与费用；既可用于机器，也可用于家庭。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin verb of standing under, the family of sistere words and the phrases economists built.","cn":"正常联想：拉丁「在下面站」动词、由 sistere 构成的词族，以及经济学家造出的短语。"},"normal":[{"en":"sub- 'under' + sistere 'stand' = what stands under a life and holds it up.","cn":"sub-「在下」+ sistere「站」= 撑在生活下面把它托住的东西。"},{"en":"The same verb gives exist, insist, resist, assist and consistent.","cn":"同一个动词还给出 exist、insist、resist、assist、consistent。"},{"en":"Economists fixed the phrases subsistence level, subsistence farming and subsistence wage.","cn":"经济学家固定了「维生水平」「维生农业」「维生工资」这些说法。"},{"en":"Subsistence is uncountable; one speaks of a means of subsistence, not a subsistence.","cn":"subsistence 不可数；说「一种维生手段」，而不说「一个维生」。"},{"en":"The philosophical sense translates hypostasis, a standing-under; the everyday sense keeps the same floor image.","cn":"哲学义翻译 hypostasis「在下面站立者」；日常义保留同一层「地板」意象。"}],"abstract":[{"en":"Picture a single bowl that is also the whole pantry.","cn":"想象一只碗，同时也是整个食物柜。"},{"en":"Picture a floor laid directly on soil, with no room beneath it.","cn":"想象一层直接铺在土上的地板，下面再没有空间。"},{"en":"Picture a ledger where every line is food and none is profit.","cn":"想象一本账，每一行都是食物，没有一行是盈余。"}]},"examples":[{"en":"Fishing provides subsistence for the households along the lagoon.","cn":"捕鱼为潟湖沿岸的家庭提供生计。"},{"en":"The wage was set at subsistence and never rose with prices.","cn":"工资被定在糊口水平，从未随物价上涨。"},{"en":"Monks debated the subsistence of universals for centuries.","cn":"僧侣们为共相的独立存在争论了数百年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「萨布西斯滕斯」拆成「萨布（在下）+ 西斯滕（站住）」——在地板下面站住不倒，就是勉强活得下去的那点家底。","word":"subsistence"},"root":"晚期拉丁 subsistentia，出自 subsistere「站在下面、撑住、留存」，由 sub-「在下」加 sistere「站立」构成；曾用来翻译希腊 hypostasis。","sensesIntro":{"en":"Eight senses build outward from a floor under life: the means, bare survival, self-provisioning, philosophical self-standing, the minimum income, legal support, the attributive use and the living allowance.","cn":"八个义项从「生活底下的一层地板」向外建：生计资料、仅足活命、自给生产、哲学自存、最低收入、法律扶养、定语用法、生活津贴。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bowl of porridge that is the entire household store.","cn":"核心意象：一碗粥就是全部家底。"},"chain":["MEANS OF LIVING","BARE SURVIVAL","SELF-PROVISIONING","INDEPENDENT EXISTENCE","MINIMUM INCOME","LIVING ALLOWANCE"],"branches":[{"senses":"义项 01 · 02","en":"SUPPORT AND ITS FLOOR: having means and having only just enough are the same support seen with and without a margin.","cn":"支撑与其底线：有资料与只够一点，是同一种支撑在有、无余量时的两种样子。"},{"senses":"义项 03 · 07","en":"PRODUCING FOR ONESELF: when nothing is sold, the abstract means becomes a whole category of farming.","cn":"为自己生产：什么都不卖时，抽象的手段就变成整类农业。"},{"senses":"义项 04","en":"SELF-STANDING: metaphysics keeps the oldest literal image, existence that stands under itself.","cn":"自立：形而上学保留了最古老的字面意象，即自己撑住自己的存在。"},{"senses":"义项 05 · 06","en":"MEASURED AND LEGAL: a floor can be turned into a number or into an enforceable entitlement.","cn":"可测量与可执行：地板可以变成一个数字，也可以变成可强制执行的权利。"},{"senses":"义项 08","en":"THE PAYMENT: institutions turn support into money handed over for basic costs.","cn":"款项：机构把支撑变成一笔用于基本开支的钱。"}]},"affixes":{"intro":{"en":"Subsistence is a Latin prefix, a Latin verb of standing and a Latin noun ending, all still readable in English kin.","cn":"subsistence 由一个拉丁前缀、一个拉丁「站立」动词与一个拉丁名词词尾构成，这些在英语亲属词里仍可读出。"},"latinIntro":{"en":"Latin sistere also gives exist, insist, resist, assist, consist and desist, all built with different prefixes on the same standing verb.","cn":"拉丁 sistere 还给出 exist、insist、resist、assist、consist、desist，都是在同一个「站立」动词上换前缀。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under')","meaning":"under; beneath","meaningCN":"在下；在下面","example":"The prefix puts the standing underneath.","exampleCN":"这个前缀把「站立」放到下面。"},{"word":"sist-","structure":"sistere (Latin verb, 'to stand')","meaning":"to stand, cause to stand","meaningCN":"站立；使站立","example":"The stem supplies the image of something holding its place.","exampleCN":"这个词干提供「某物守住位置」的意象。"},{"word":"-ence","structure":"-entia (Latin noun ending, state)","meaning":"the state of","meaningCN":"……的状态","example":"The ending makes the verb a state, not an act.","exampleCN":"这个结尾把动词变成状态，而非动作。"},{"word":"subsist","structure":"sub- + sistere","meaning":"to keep oneself alive","meaningCN":"维持自身生存","example":"They subsisted on roots and fish.","exampleCN":"他们靠块根与鱼维持生活。"},{"word":"exist","structure":"ex- (out) + sistere","meaning":"to stand forth, be","meaningCN":"站出来；存在","example":"The pattern exists in both languages.","exampleCN":"这一模式在两种语言中都存在。"},{"word":"insist","structure":"in- (upon) + sistere","meaning":"to stand upon, demand","meaningCN":"站在其上；坚持","example":"She insisted on a written answer.","exampleCN":"她坚持要书面答复。"},{"word":"resist","structure":"re- (against) + sistere","meaning":"to stand against","meaningCN":"站住对抗；抵抗","example":"The coating resists salt.","exampleCN":"这层涂料抗盐。"},{"word":"assist","structure":"ad- (to) + sistere","meaning":"to stand by","meaningCN":"站在旁边；协助","example":"Two volunteers assisted the survey.","exampleCN":"两名志愿者协助了这次调查。"},{"word":"subsistent","structure":"subsist + -ent (adjective)","meaning":"self-standing; barely living","meaningCN":"自存的；仅足维生的","example":"A subsistent farm sells almost nothing.","exampleCN":"自给农场几乎不卖东西。"}],"latinEntries":[{"word":"subsistere","structure":"sub- + sistere (Latin verb)","meaning":"to stand firm, hold out, remain","meaningCN":"站稳；撑住；留存"},{"word":"subsistentia","structure":"subsistere + -entia (Late Latin noun)","meaning":"a standing under; subsistence","meaningCN":"在下面站立；生存"},{"word":"hypostasis","structure":"hypo- + histanai (Greek noun)","meaning":"a standing under; substance, person","meaningCN":"在下面站立；实体、位格"},{"word":"substantia","structure":"sub- + stare (Latin noun)","meaning":"that which stands beneath; substance","meaningCN":"站在下面者；实体"}],"derivatives":[{"word":"subsistences","structure":"subsistence + -s (rare plural)","meaning":"distinct systems of survival","meaningCN":"不同的维生体系"},{"word":"subsistently","structure":"subsistent + -ly","meaning":"in a self-standing way","meaningCN":"以自存的方式"}]}},{"word":"subsistence economy","ipa_uk":"/sʌbˈsɪstəns ɪˈkɒnəmi/","ipa_us":"/sʌbˈsɪstəns ɪˈkɑːnəmi/","definition_zh":"自给经济；生存经济；主要为自用而非出售而生产的经济形态","definition_en":"an economy in which most production is consumed by the producers rather than sold","core_image":"一袋粮从田里进仓、从仓里进锅，中间没有秤、没有钱、也没有买家","scene":"全村的粮只进自家灶，从不出村售卖，A subsistence economy leaves almost nothing for the market.","sceneCN":"这里 subsistence economy 指「主要为自用而非出售而生产的经济」（第 1 个义项：自给自足的经济形态）；句意为这种自给经济几乎不留下任何可上市的东西。图中可辨识物件：粮仓、灶台、空秤、未打开的集市门。","pos":[{"tag":"n.","zh":"自给经济；生存经济（可数，指一种经济形态）"}],"collocations":[{"phrase":"a subsistence economy","zh":"一种自给经济"},{"phrase":"subsistence economy and market exchange","zh":"自给经济与市场交换"},{"phrase":"transition from a subsistence economy","zh":"自给经济的转型"},{"phrase":"household subsistence economy","zh":"家庭自给经济"},{"phrase":"a purely subsistence economy","zh":"纯粹的自给经济"}],"forms":[{"label":"复数","form":"subsistence economies"},{"label":"相关名词","form":"subsistence"},{"label":"相关形容词","form":"subsistence-level"}],"derivatives":[{"word":"subsistence","pos":"n.","zh":"生计；生存"},{"word":"economy","pos":"n.","zh":"经济；经济体"},{"word":"economic","pos":"adj.","zh":"经济的"},{"word":"economist","pos":"n.","zh":"经济学家"}],"senses":[{"no":"01","title":"Production consumed by the producers","titleCN":"生产者自己消费掉的生产","definition":"an economic system in which households consume what they produce and sell little","definitionCN":"家庭消费自己所产、几乎不出售的经济体系","example":"In a subsistence economy the harvest is measured in meals, not in sales.","exampleCN":"在自给经济里，收成以饭顿计，而非以销售额计。","why":"the phrase puts the Latin idea of a supporting floor in front of the Greek idea of household management, so the economy is aimed at keeping the household alive.","whyCN":"这个短语把拉丁「支撑地板」放在希腊「家计管理」之前，因此整套经济指向让家庭活下去。"},{"no":"02","title":"A non-market mode of production","titleCN":"非市场的生产模式","definition":"a mode of production in which goods circulate by obligation and sharing rather than by price","definitionCN":"货物靠义务与分享而非价格流通的生产模式","example":"Grain moved through the village by obligation, a hallmark of the subsistence economy.","exampleCN":"粮食靠人情义务在村中流转，这是自给经济的标志。","why":"if almost nothing is sold, allocation must be organised by kinship and obligation instead of by price.","whyCN":"如果几乎什么都不卖，分配就只能靠亲属关系与义务来组织，而不是靠价格。"},{"no":"03","title":"A category in anthropology","titleCN":"人类学中的一个类别","definition":"a standard classification for economies oriented to use rather than exchange","definitionCN":"把经济取向定为使用而非交换的标准分类","example":"The course contrasts the subsistence economy with peasant and market systems.","exampleCN":"这门课把自给经济与农民经济、市场体系相对比。","why":"anthropology needs boxes, and this phrase is the box for economies that stop at the household door.","whyCN":"人类学需要格子，这个短语就是「止步于家门」的经济的那一格。"},{"no":"04","title":"A peasant household arrangement","titleCN":"农户家庭的自给安排","definition":"a household system where most food and fuel are produced on the holding itself","definitionCN":"大部分食物与燃料都在自家田地上产出的家庭体系","example":"The peasant household ran a partial subsistence economy and sold only the surplus.","exampleCN":"这户农家实行部分自给经济，只卖余粮。","why":"peasant holdings mix sale and self-provision, so the phrase often describes a tendency rather than a pure type.","whyCN":"农户经营混合了出售与自给，因此这个短语常描述一种倾向，而非纯粹类型。"},{"no":"05","title":"The opposite of a cash economy","titleCN":"与现金经济相对","definition":"an economy defined chiefly by the absence of money in most transactions","definitionCN":"主要以多数交易不用钱来界定的经济","example":"Wages barely exist in a subsistence economy; labour is repaid in grain.","exampleCN":"在自给经济里几乎没有工资；劳动以粮食偿付。","why":"a system is easiest to describe against its opposite, and here the opposite is money-mediated exchange.","whyCN":"制度最易借对立面描述，而这里的对立面是以货币为媒介的交换。"},{"no":"06","title":"A label in development policy","titleCN":"发展政策中的标签","definition":"a term used by agencies to classify regions considered outside market production","definitionCN":"机构用来归类那些被认为处于市场生产之外的地区的术语","example":"The project's subsistence economy label obscured the village's remittances.","exampleCN":"项目所贴的自给经济标签掩盖了该村的汇款收入。","why":"policy categories simplify, and a phrase built for one economy can hide the cash that already flows through it.","whyCN":"政策分类会简化现实，为一个经济形态造的短语，可能掩盖已经流经它的现金。"},{"no":"07","title":"A pre-industrial local system","titleCN":"前工业时代的本地体系","definition":"a local economy before wide markets, transport and wage labour","definitionCN":"在广域市场、运输与雇佣劳动出现之前的本地经济","example":"Historians describe a subsistence economy that paid taxes in chickens.","exampleCN":"史家描述一种以鸡缴税的自给经济。","why":"historical writing uses the phrase for the long period when most production never left the district.","whyCN":"历史写作把这个短语用于漫长时期——那时多数产品从未离开本区。"},{"no":"08","title":"A self-sufficient system, by metaphor","titleCN":"比喻意义上的自足体系","definition":"figuratively, any system that supplies its own needs without outside exchange","definitionCN":"比喻指任何不靠外部交换而自供所需的体系","example":"The lab prided itself on a subsistence economy of spare parts.","exampleCN":"这个实验室以零件上的自给经济为傲。","why":"the image of closed circulation transfers easily to workshops, software and even hobbies.","whyCN":"闭环流通的意象很容易迁移到工坊、软件甚至爱好上。"}],"etymology":{"intro":{"en":"The phrase joins subsistence, from Latin subsistere, to economy, from Greek oikonomia 'household management'. The compound is modern. Dates are approximate.","cn":"这个短语把出自拉丁 subsistere 的 subsistence 与出自希腊 oikonomia「家计管理」的 economy 组合起来。组合本身是近代产物。年代均为约数。"},"items":[{"era":"GREEK OIKOS","en":"Oikos meant 'house, household', including the people, animals and stores that made up a household.","cn":"oikos 意为「房子、家户」，包括构成一户的人、畜与储粮。"},{"era":"GREEK NEMEIN","en":"Nemein 'to deal out, manage' supplied the second half of oikonomia; its deeper root is reconstructed rather than attested.","cn":"nemein「分配、管理」提供 oikonomia 的后半；其更深词根属重构，而非书证。"},{"era":"GREEK OIKONOMIA","en":"Oikonomia meant the management of a household and later the management of a community's resources.","cn":"oikonomia 指管理一个家户，后来指管理一个共同体的资源。"},{"era":"LATIN OECONOMIA","en":"Latin borrowed the Greek word as oeconomia; the Latin form is a loan, not a native relative.","cn":"拉丁语把希腊词借作 oeconomia；这个拉丁形是借词，不是本族同源词。"},{"era":"ENGLISH ECONOMY","en":"English economy entered in the fifteenth century as household management, then widened to the wealth and trade of a whole society.","cn":"英语 economy 在 15 世纪以「家计管理」进入，后来放宽到整个社会的财富与贸易。"},{"era":"COMPOUND PHRASE","en":"Subsistence economy was fixed by nineteenth and twentieth century economists and anthropologists to name production aimed at use; source uncertain for its first printed use.","cn":"subsistence economy 由 19 与 20 世纪的经济学家与人类学家固定下来，指以使用为目标的生产；首次见于印刷品的年代不确定。"}]},"similar":{"note":{"en":"The first group shares the two halves of the phrase or looks close; the second names neighbouring economic arrangements.","cn":"第一组共用短语的两半或形近；第二组是邻近的经济安排。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"subsistence","ipa":"/sʌbˈsɪstəns/","tag":"the first half alone","definition":"The means of staying alive; the full phrase adds economy, so production and circulation are included.","definitionCN":"指维生资料；完整短语加上 economy，才包含生产与流通。"},{"word":"subsistent","ipa":"/sʌbˈsɪstənt/","tag":"the adjective","definition":"Describing something barely providing for itself; an adjective, where the phrase is a named system.","definitionCN":"形容仅能自供的状态；是形容词，而短语是一个有名字的体系。"},{"word":"economy","ipa":"/ɪˈkɒnəmi/","tag":"the second half alone","definition":"The system of production, trade and money in a place; alone it does not say whether output is sold.","definitionCN":"指某地的生产、贸易与货币体系；单独使用并不说明产出是否出售。"},{"word":"economize","ipa":"/ɪˈkɒnəmaɪz/","tag":"verb of saving","definition":"To spend less or use sparingly; it is about thrift, not about a whole mode of production.","definitionCN":"指少花钱、节省使用；说的是节约，不是整套生产模式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"self-sufficiency","ipa":"/ˌselfsəˈfɪʃənsi/","tag":"the property","definition":"The capacity to meet one's needs without outside help; a property of a unit, rather than a named economy.","definitionCN":"指无需外援即可满足自身需要的能力；是某单位的一种属性，而非一种命名的经济。"},{"word":"autarky","ipa":"/ɔːˈtɑːki/","tag":"closed national economy","definition":"A policy or condition of national economic self-reliance; it is political and usually large-scale.","definitionCN":"指国家经济自给的政策或状态；带政治性，且通常是宏观尺度。"},{"word":"barter economy","ipa":"/ˈbɑːtə ɪˈkɒnəmi/","tag":"exchange without money","definition":"An economy in which goods are traded directly; it may still be market-oriented, unlike a subsistence economy.","definitionCN":"指以物易物的经济；它仍可能面向市场，与自给经济不同。"},{"word":"household economy","ipa":"/ˈhaʊshəʊld ɪˈkɒnəmi/","tag":"the domestic unit","definition":"The production and consumption of one household; it can be fully market-connected and still be called this.","definitionCN":"指一个家户的生产与消费；它可以完全连着市场，仍叫这个名字。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Greek household words behind economy and the contrasts economists draw.","cn":"正常联想：economy 背后两个希腊「家户」词，以及经济学家作出的对举。"},"normal":[{"en":"subsistence 'keeping alive' + economy 'household management' = management aimed only at keeping the household alive.","cn":"subsistence「维持生存」+ economy「家计管理」= 只为让家户活下去的管理。"},{"en":"Economy goes back to oikos 'house' and nemein 'manage', so the phrase is literally home economics.","cn":"economy 上溯 oikos「房子」与 nemein「管理」，因此这个短语字面上就是「家计」。"},{"en":"The standard contrasts are market economy, cash economy and peasant economy.","cn":"标准对举是「市场经济」「现金经济」「农民经济」。"},{"en":"The plural is subsistence economies, since each region can have its own.","cn":"复数是把末尾的 y 改成 ies，因为每个地区都可以有自己的那一套。"},{"en":"The phrase nearly always carries an article: a subsistence economy, the subsistence economy of the valley.","cn":"这个短语几乎总带冠词：一种自给经济、这座山谷的自给经济。"}],"abstract":[{"en":"Picture a sack of grain that never meets a scale or a coin.","cn":"想象一袋粮，从未碰过秤，也没碰过钱币。"},{"en":"Picture a market square with shutters closed because nothing was ever brought to sell.","cn":"想象一个市集广场，百叶窗关着，因为从来没人带东西来卖。"},{"en":"Picture a household ledger written entirely in meals.","cn":"想象一本家庭账，全部用「饭顿」来记。"}]},"examples":[{"en":"The valley ran a subsistence economy until the road brought traders.","cn":"在道路带来商人之前，这座山谷实行自给经济。"},{"en":"Researchers distinguish a subsistence economy from a peasant economy by how much is sold.","cn":"研究者靠出售比例来区分自给经济与农民经济。"},{"en":"The island's subsistence economy depended on taro and reef fish.","cn":"这座岛的自给经济依赖芋头与礁鱼。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「自给经济」四个字最好记：种来自家吃、织来自家穿，秤和钱都闲着。subsistence 就是「站住活下去」，economy 就是「管家」。","word":"subsistence economy"},"root":"subsistence 出自晚期拉丁 subsistere「在下面站稳」；economy 出自希腊 oikonomia，由 oikos「家户」与 nemein「管理」构成，经拉丁 oeconomia 进入英语。两者组合为近代学术用语。","sensesIntro":{"en":"Eight senses range from household self-provision through non-market circulation, anthropological classification, peasant practice, the cash-economy contrast, policy labelling, pre-industrial history and metaphorical self-sufficiency.","cn":"八个义项从家庭自给，经非市场流通、人类学分类、农户实践、与现金经济的对举、政策标签、前工业历史，到比喻性的自足。"},"semanticMap":{"core":{"en":"CORE IMAGE: grain that passes from field to store to pot without a scale or a coin.","cn":"核心意象：粮食从田到仓再到锅，全程不碰秤、不碰钱。"},"chain":["OWN CONSUMPTION","NON-MARKET FLOW","ANTHROPOLOGICAL TYPE","PEASANT PRACTICE","PRE-INDUSTRIAL LOCALISM","SELF-SUFFICIENT SYSTEM"],"branches":[{"senses":"义项 01 · 02","en":"USE AND OBLIGATION: consuming one's own output and circulating it by duty are two sides of the same closed loop.","cn":"使用与义务：消费自家产出与按义务流转，是同一闭环的两面。"},{"senses":"义项 03 · 04","en":"THEORY AND FARM: the classification and the actual peasant holding describe the same arrangement at different resolutions.","cn":"理论与农田：分类与真实的农户经营，是同一安排在不同分辨率下的描述。"},{"senses":"义项 05","en":"NO CASH: the system is often defined by what it lacks, namely money in most transactions.","cn":"没有现金：这套体系常以「缺什么」来定义，即多数交易里没有钱。"},{"senses":"义项 06 · 07","en":"LABEL AND HISTORY: policy boxes and historical periods both use the phrase for economies that stop at the district line.","cn":"标签与历史：政策格子与历史分期都用这个短语指止步于本区的经济。"},{"senses":"义项 08","en":"THE METAPHOR: any workshop that recycles its own parts borrows the closed-loop image.","cn":"比喻：任何循环使用自家零件的工坊，都借用了这个闭环意象。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin noun of standing under with a Greek noun of household management, so its two halves have different origins.","cn":"这个短语把拉丁「在下面站立」名词与希腊「家计管理」名词组合起来，两半来源不同。"},"latinIntro":{"en":"Subsistence half is Latin; economy half is Greek borrowed into Latin as oeconomia. The two should not be given one shared root.","cn":"subsistence 那一半是拉丁的；economy 那一半是希腊语，经拉丁 oeconomia 借入。两者不应被说成共用一个词根。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under')","meaning":"under; beneath","meaningCN":"在下","example":"It holds the supporting floor beneath life.","exampleCN":"它把支撑的地板放在生活之下。"},{"word":"sist-","structure":"sistere (Latin verb, 'to stand')","meaning":"to stand firm","meaningCN":"站稳","example":"The same stem appears in insist and resist.","exampleCN":"同一个词干见于 insist 与 resist。"},{"word":"oik-","structure":"oikos (Greek noun, 'household')","meaning":"house; household","meaningCN":"房子；家户","example":"The stem also gives ecology and ecumenical.","exampleCN":"这个词干还给出 ecology 与 ecumenical。"},{"word":"nom-","structure":"nemein (Greek verb, 'to manage, deal out')","meaning":"to manage; to distribute","meaningCN":"管理；分配","example":"This is the managing half of economy.","exampleCN":"这是 economy 中「管理」的那一半。"},{"word":"economy","structure":"oikos + nemein through Latin oeconomia","meaning":"household management; a system of production","meaningCN":"家计管理；生产体系","example":"The word widened from one house to a whole country.","exampleCN":"这个词从一个家扩到整个国家。"},{"word":"subsistence","structure":"sub- + sistere + -ence","meaning":"the means of staying alive","meaningCN":"维生资料","example":"Subsistence here means food and fuel, not money.","exampleCN":"这里的 subsistence 指食物与燃料，而不是钱。"},{"word":"subsistence economy","structure":"subsistence + economy","meaning":"production aimed at one's own use","meaningCN":"以自用为目标的生产","example":"The phrase names a whole system.","exampleCN":"这个短语命名一整套体系。"},{"word":"economies","structure":"economy + -ies (plural)","meaning":"several economic systems","meaningCN":"多个经济体系","example":"The book compares four subsistence economies.","exampleCN":"这本书比较四种自给经济。"},{"word":"economic","structure":"economy + -ic (adjective)","meaning":"relating to production and wealth","meaningCN":"与经济有关的","example":"Economic change followed the new road.","exampleCN":"经济变化随新路而来。"}],"latinEntries":[{"word":"subsistentia","structure":"subsistere + -entia (Late Latin noun)","meaning":"a standing under; subsistence","meaningCN":"在下面站立；生存"},{"word":"oeconomia","structure":"Greek oikonomia borrowed into Latin","meaning":"household management","meaningCN":"家计管理"},{"word":"oeconomicus","structure":"oeconomia + -icus (Medieval Latin adjective)","meaning":"of household management","meaningCN":"家计管理的"}],"derivatives":[{"word":"subsistence-level","structure":"subsistence + level (compound modifier)","meaning":"at bare survival standard","meaningCN":"处于仅足维生水平的"},{"word":"agro-economic","structure":"agro- (field) + economic","meaning":"relating to farm production and money","meaningCN":"农业经济的"}]}},{"word":"domestication","ipa_uk":"/dəˌmestɪˈkeɪʃən/","ipa_us":"/dəˌmestɪˈkeɪʃən/","definition_zh":"驯化；驯养；栽培化；使野生物种适应人类利用的过程","definition_en":"the process by which wild animals or plants are brought under human control and use","core_image":"一只野禽在几代人的挑选下翅膀变短、产蛋变多，栏门从篱笆变成木门，最后变成一把锁","scene":"村口的羊圈里，Generations of selection have made domestication visible in the shorter horns of the flock.","sceneCN":"这里 domestication 指「把野生物种驯化为家养的过程」（第 1 个义项：动物驯化）；句意为数代选育使驯化的痕迹显现在羊群变短的角上。图中可辨识物件：羊圈木栏、短角羊、选留标记、饲料槽。","pos":[{"tag":"n.","zh":"驯化；驯养；栽培化（不可数）；一次驯化事件（可数）"}],"collocations":[{"phrase":"animal domestication","zh":"动物驯化"},{"phrase":"plant domestication","zh":"作物栽培化"},{"phrase":"the domestication of wheat","zh":"小麦的驯化"},{"phrase":"early domestication","zh":"早期驯化"},{"phrase":"domestication syndrome","zh":"驯化综合征"},{"phrase":"centres of domestication","zh":"驯化中心"}],"forms":[{"label":"不可数（无复数）","form":"domestication"},{"label":"动词","form":"domesticate"},{"label":"形容词","form":"domesticated"}],"derivatives":[{"word":"domesticate","pos":"v.","zh":"驯化；驯养"},{"word":"domesticated","pos":"adj.","zh":"已驯化的；家养的"},{"word":"domestic","pos":"adj./n.","zh":"家庭的；家养的；家务"},{"word":"domesticity","pos":"n.","zh":"家庭生活；家居性"}],"senses":[{"no":"01","title":"Bringing wild animals under human control","titleCN":"把野生动物置于人的控制之下","definition":"the process by which a wild animal population is bred and managed by people","definitionCN":"野生兽群被人类繁育与管理的过程","example":"Dog domestication began before farming, according to the burial evidence.","exampleCN":"据墓葬证据，狗的驯化早于农耕。","why":"domestic comes from Latin domus 'house', so domestication is literally the process of bringing a wild thing into the household.","whyCN":"domestic 出自拉丁 domus「家」，因此驯化字面上就是把野物带进家户的过程。"},{"no":"02","title":"Turning a wild plant into a crop","titleCN":"把野生植物变成作物","definition":"the process by which a wild plant is selected and changed until it depends on cultivation","definitionCN":"野生植物被选育改变，直到依赖栽培的过程","example":"Maize domestication reshaped the cob from a few hard seeds to a full ear.","exampleCN":"玉米的驯化把几粒硬籽的穗轴改造成饱满的果穗。","why":"the household image extends to plants: a field is a household arrangement for a species that can no longer scatter its own seed.","whyCN":"「家户」的意象扩展到植物：田是为一个再也不能自己散播种子的物种安排的家。"},{"no":"03","title":"The domesticated condition","titleCN":"被驯养的状态","definition":"the state of a species or individual that has become dependent on human care","definitionCN":"某物种或个体已变得依赖人类照料的状态","example":"Domestication left the breed unable to survive without shelter.","exampleCN":"驯化使这个品种离开人工庇护就无法生存。","why":"the process name also names its result, because a species that has been through it looks different from its wild relatives.","whyCN":"过程名也指结果，因为经历过这一过程的物种与野生亲戚看起来不同。"},{"no":"04","title":"Making something wild feel familiar","titleCN":"使野性之物变得可亲近","definition":"figuratively, the process of taming or civilising something that was once unfamiliar","definitionCN":"比喻指把曾经陌生之物变得驯顺或文明化的过程","example":"The domestication of the forest into a park took a century.","exampleCN":"把森林驯化成公园用了一个世纪。","why":"once the word means bringing inside, it can describe any wildness reduced to something a household can handle.","whyCN":"一旦这个词表示「带进家里」，它就能描述任何被削减到家户可处理程度的野性。"},{"no":"05","title":"A shared set of changes in tame species","titleCN":"家养物种共有的一组变化","definition":"the recurring package of traits, such as smaller horns and patchy coat, seen in many domesticated animals","definitionCN":"许多家养动物身上反复出现的一组性状，如角变小、毛色出现斑块","example":"Floppy ears and shorter snouts are part of the domestication syndrome.","exampleCN":"垂耳与较短的吻部是驯化综合征的一部分。","why":"breeding for calmness repeatedly pulled along other traits, so science gave the bundle a name built on domestication.","whyCN":"为温顺而选育，反复连带出其他性状，科学于是给这束变化起了一个建于 domestication 上的名字。"},{"no":"06","title":"Reshaping a landscape","titleCN":"把景观改造为人工环境","definition":"the long process by which people convert a wild landscape into one they manage","definitionCN":"人们把野地改造成由自己管理的景观的长期过程","example":"Landscape domestication produced terraces, hedges and wells.","exampleCN":"景观驯化造出了梯田、树篱与水井。","why":"if animals and plants can be brought inside, so can a whole valley, and the same word covers the slow reshaping.","whyCN":"既然动植物能被带进家户，整座山谷也可以，同一个词覆盖这种缓慢改造。"},{"no":"07","title":"Making an idea or technology familiar","titleCN":"使想法或技术变得日常可用","definition":"the process by which a novel idea or tool becomes ordinary and easy to use","definitionCN":"新想法或新工具变得寻常、易用的过程","example":"The domestication of the telephone took two generations.","exampleCN":"电话走进日常生活用了两代人。","why":"a new tool is wild in the sense that no one knows how to live with it; domestication is learning to live with it.","whyCN":"新工具之所以「野」，是因为没人知道怎么与它共处；驯化就是学会与它共处。"},{"no":"08","title":"Bringing a treaty into domestic law","titleCN":"把条约转为国内法","definition":"in law, the incorporation of an international agreement into a state's own legal system","definitionCN":"法律上把国际协定纳入本国法律体系","example":"The domestication of the convention required a new statute.","exampleCN":"该公约的国内法化需要一部新法规。","why":"legal writers reuse the household image: an international text must be brought inside the house of national law.","whyCN":"法律写作者沿用「家户」意象：国际文本必须被带进国家法律这座房子。"}],"etymology":{"intro":{"en":"Domestication is built on Latin domesticus 'of the household', from domus 'house', with the English verb ending -ate and the noun ending -ion. Dates are approximate.","cn":"domestication 建于拉丁 domesticus「属于家户的」之上，再上为 domus「房子」，加英语动词词尾 -ate 与名词词尾 -ion。年代均为约数。"},"items":[{"era":"LATIN DOMUS","en":"Domus meant 'house, household'. Its pre-Latin base is reconstructed; the usual link to a root meaning 'to build' is a hypothesis, not a demonstrated derivation.","cn":"domus 意为「房子、家户」。它在拉丁语之前的词基属重构；通常把它联系到意为「建造」的词根，那只是假说，并非已证实的派生。"},{"era":"LATIN DOMESTICUS","en":"Domesticus meant 'belonging to the household', applied to slaves, animals and things kept inside a house.","cn":"domesticus 意为「属于家户的」，用于指奴隶、动物与养在屋内之物。"},{"era":"LATIN DOMARE","en":"Domare 'to tame' is a separate verb with its own reconstructed root; it overlaps in meaning but should not be presented as the source of domesticus.","cn":"domare「使驯服」是另一个动词，有自己的重构词根；它与 domesticus 意义重叠，却不应被说成 domesticus 的来源。"},{"era":"LATIN DOMESTICARE","en":"Domesticare meant 'to make domestic, to tame', and English took it as domesticate.","cn":"domesticare 意为「使成为家用的、使驯服」，英语借作 domesticate。"},{"era":"ENGLISH DOMESTICATION","en":"English domestication appeared in the seventeenth century, first for taming animals and later for plants and landscapes.","cn":"英语 domestication 在 17 世纪出现，先指驯服动物，后扩及植物与景观。"},{"era":"SCIENTIFIC AND LEGAL SPREAD","en":"In the twentieth century the noun became standard in archaeology and genetics, and law borrowed it for incorporating treaties; source uncertain for the first legal use.","cn":"20 世纪，这个名词在考古学与遗传学中成为标准用语，法律也借用它指纳入条约；首次法律用法不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin household word; the second names other processes of bringing organisms or land under human use.","cn":"第一组共用拉丁「家户」词；第二组是把生物或土地纳入人类利用的其他过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"domestic","ipa":"/dəˈmestɪk/","tag":"the adjective","definition":"Belonging to the home or to animals kept in it; it describes the state, not the historical process.","definitionCN":"指属于家庭或养在家中的；描述状态，而非历史过程。"},{"word":"domesticate","ipa":"/dəˈmestɪkeɪt/","tag":"the verb","definition":"To bring a wild species under human use; the verb names the act, the noun names the whole process.","definitionCN":"指把野生物种纳入人类利用；动词指动作，名词指整套过程。"},{"word":"domesticated","ipa":"/dəˈmestɪkeɪtɪd/","tag":"the participle","definition":"Already tamed or adapted; it looks back at a completed action rather than naming the action.","definitionCN":"指已被驯化或适应；回看已完成的动作，而非命名动作。"},{"word":"domesticity","ipa":"/dəmesˈtɪsəti/","tag":"home life","definition":"The quality or state of home life; it has nothing to do with taming species.","definitionCN":"指家庭生活的性质或状态；与驯化物种无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"taming","ipa":"/ˈteɪmɪŋ/","tag":"the individual act","definition":"Making one animal calm and obedient to people; it can happen without any change in the species.","definitionCN":"使单只动物变得温顺听话；可以完全不涉及物种层面的改变。"},{"word":"cultivation","ipa":"/ˌkʌltɪˈveɪʃən/","tag":"the plant parallel","definition":"Preparing and working land to grow crops; it names the labour, not necessarily the genetic change.","definitionCN":"指整地耕作以种作物；指劳动，不一定指遗传改变。"},{"word":"acclimatization","ipa":"/əˌklaɪmətaɪˈzeɪʃən/","tag":"adjusting to a place","definition":"Adjustment of an organism to a new climate or habitat; no human household is implied.","definitionCN":"生物对新气候或生境的适应；不隐含人类家户。"},{"word":"settlement","ipa":"/ˈsetəlmənt/","tag":"the human parallel","definition":"The founding of a permanent community in a place; it is about people staying, not species being tamed.","definitionCN":"指在某地建立永久社区；说的是人定居，不是物种被驯化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin house word, the family it built and the phrases archaeology keeps.","cn":"正常联想：拉丁「房子」词、它构成的词族，以及考古学固定的搭配。"},"normal":[{"en":"domus 'house' + -ticus 'belonging to' + -ation 'process' = the process of bringing a wild thing into the house.","cn":"domus「房子」+ -ticus「属于」+ -ation「过程」= 把野物带进家户的过程。"},{"en":"The family runs domestic, domesticate, domesticated, domestication and domesticity.","cn":"词族包括 domestic、domesticate、domesticated、domestication、domesticity。"},{"en":"Domare 'to tame' is a different Latin verb that happens to overlap in meaning.","cn":"domare「使驯服」是另一个拉丁动词，只是意义恰好重叠。"},{"en":"The standard collocations are animal domestication, plant domestication and domestication syndrome.","cn":"标准搭配是「动物驯化」「植物驯化」「驯化综合征」。"},{"en":"The word is uncountable: a process, not a count of events.","cn":"这个词不可数：指过程，而不计次数。"}],"abstract":[{"en":"Picture a threshold that a species crosses once and cannot cross back.","cn":"想象一道门槛，一个物种跨过去一次，就再也跨不回来。"},{"en":"Picture a hand choosing seed from the calmest plant, year after year.","cn":"想象一只手年复一年从最安静的植株上留种。"},{"en":"Picture a wild valley drawn slowly into a floor plan.","cn":"想象一座野谷被缓慢画进一张平面图。"}]},"examples":[{"en":"The domestication of the horse changed transport across the steppe.","cn":"马的驯化改变了草原上的运输方式。"},{"en":"Genetic studies date wheat domestication to the Fertile Crescent.","cn":"遗传研究把小麦的驯化定在肥沃新月地带。"},{"en":"The report examines the domestication of international labour standards.","cn":"这份报告考察国际劳工标准的国内法化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「多麦斯提凯申」听成「多麦斯（多把麦子）提进家」——把野麦一担担提进屋、年年留种，就是驯化。","word":"domestication"},"root":"拉丁 domus「房子、家户」构成 domesticus「属于家户的」，再构成 domesticare「使驯服、使家用」，英语取其动词作 domesticate，加 -ion 成 domestication。domare「使驯服」是另一个动词，并非 domesticus 的来源。","sensesIntro":{"en":"Eight senses move from animal and plant domestication through the domesticated state, the figurative taming of anything wild, the trait bundle, landscape reshaping, familiar technology and legal incorporation.","cn":"八个义项从动植物驯化，经被驯养状态、对任何野性的比喻性驯服、性状束、景观改造、技术日常化，到法律的国内法化。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wild bird whose wings shorten generation by generation behind a gate.","cn":"核心意象：一只野禽在门后一代代地短了翅膀。"},"chain":["TAME ANIMALS","CULTIVATE PLANTS","TAME CONDITION","FAMILIARISE ANY WILDNESS","LANDSCAPE CONTROL","LEGAL INCORPORATION"],"branches":[{"senses":"义项 01 · 02","en":"ANIMALS AND PLANTS: selection behind a fence and selection in a field are one method aimed at two kingdoms.","cn":"动物与植物：栏后的选育与田里的选育，是同一种方法指向两个界。"},{"senses":"义项 03 · 05","en":"STATE AND SYNDROME: the result of breeding is a dependent animal with a recognisable bundle of traits.","cn":"状态与综合征：选育的结果是一只依赖人的动物，带着一组可辨认的性状。"},{"senses":"义项 04","en":"ANY WILDNESS: what is unfamiliar can be brought inside just as an animal is.","cn":"任何野性：陌生之物也可以像动物一样被带进家户。"},{"senses":"义项 06","en":"LAND: a whole valley can be domesticated into terraces, hedges and wells.","cn":"土地：整座山谷可以被驯化成梯田、树篱与水井。"},{"senses":"义项 07 · 08","en":"TOOLS AND TREATIES: a telephone and an international convention are both brought inside a house of use or law.","cn":"工具与条约：电话与国际公约都被带进「使用」或「法律」这座房子。"}]},"affixes":{"intro":{"en":"Domestication is a Latin household adjective turned into a verb and then into a noun of process.","cn":"domestication 是一个拉丁「家户」形容词，先变动词，再变表示过程的名词。"},"latinIntro":{"en":"Latin domus also gives domicile and domestic, while domare 'to tame' is a separate verb whose similarity is semantic rather than etymological.","cn":"拉丁 domus 还给出 domicile 与 domestic；domare「使驯服」是另一个动词，其相似是语义上的，而非词源上的。"},"items":[{"word":"dom-","structure":"domus (Latin noun, 'house')","meaning":"house; household","meaningCN":"房子；家户","example":"The stem supplies the image of bringing something indoors.","exampleCN":"这个词干提供「把某物带进屋内」的意象。"},{"word":"-estic","structure":"-ticus (Latin adjective ending)","meaning":"belonging to","meaningCN":"属于……的","example":"The ending makes domesticus 'of the household'.","exampleCN":"这个结尾构成 domesticus「属于家户的」。"},{"word":"-ate","structure":"-are (Latin verb ending, through French -er)","meaning":"to make or cause","meaningCN":"使成为；造成","example":"The ending turns domestic into domesticate.","exampleCN":"这个结尾把 domestic 变成 domesticate。"},{"word":"-ation","structure":"-atio (Latin noun of action)","meaning":"the process of","meaningCN":"……的过程","example":"The ending turns the verb into a process noun.","exampleCN":"这个结尾把动词变成过程名词。"},{"word":"domestic","structure":"domesticus through French","meaning":"of the home; kept at home","meaningCN":"家庭的；家养的","example":"Domestic animals depend on people.","exampleCN":"家养动物依赖人。"},{"word":"domesticate","structure":"domestic + -ate","meaning":"to tame and keep","meaningCN":"驯化并饲养","example":"People domesticated goats early.","exampleCN":"人们很早就驯化了山羊。"},{"word":"domesticated","structure":"domesticate + -ed","meaning":"already brought under human care","meaningCN":"已被纳入人类照料的","example":"The domesticated form has smaller seeds.","exampleCN":"驯化型的种子更小。"},{"word":"domestication","structure":"domesticate + -ion","meaning":"the process of taming","meaningCN":"驯化的过程","example":"Domestication took many generations.","exampleCN":"驯化历经许多代。"},{"word":"domesticity","structure":"domestic + -ity","meaning":"home life as a state","meaningCN":"家庭生活状态","example":"The novel praises domesticity.","exampleCN":"这部小说赞美家庭生活。"}],"latinEntries":[{"word":"domus","structure":"Latin noun, fourth declension","meaning":"house, household","meaningCN":"房子；家户"},{"word":"domesticus","structure":"domus + -ticus","meaning":"of the household","meaningCN":"属于家户的"},{"word":"domesticare","structure":"domesticus + -are (Latin verb)","meaning":"to make domestic, tame","meaningCN":"使家用；使驯服"},{"word":"domare","structure":"Latin verb, separate root","meaning":"to tame, subdue","meaningCN":"使驯服；制服"}],"derivatives":[{"word":"domestications","structure":"domestication + -s (rare plural)","meaning":"separate episodes of taming","meaningCN":"一次次的驯化事件"},{"word":"redomestication","structure":"re- (again) + domestication","meaning":"a second taming of a feral population","meaningCN":"对野化群体的再次驯化"}]}},{"word":"domesticate","ipa_uk":"/dəˈmestɪkeɪt/","ipa_us":"/dəˈmestɪkeɪt/","definition_zh":"驯化；驯养；栽培；使适应家庭生活；使（条约）转为国内法","definition_en":"to bring a wild animal or plant under human control and use","core_image":"一双手把一只挣扎的幼兽按在膝上，另一只手把门闩轻轻扣上","scene":"农人把野生的禾草一株株挑出来留种，Farmers domesticate the wild grass by saving seed from the calmest plants.","sceneCN":"这里 domesticate 指「把野生植物选育为栽培作物」（第 2 个义项：栽培化）；句意为农人从最安静的植株上留种，从而驯化这种野草。图中可辨识物件：留种穗、麻袋、挑选的手、田垄。","pos":[{"tag":"v.","zh":"驯化；驯养；栽培；使适应家庭生活"},{"tag":"n.","zh":"（罕用）已驯化的动物"}],"collocations":[{"phrase":"domesticate an animal","zh":"驯化一种动物"},{"phrase":"domesticate a plant","zh":"栽培化一种植物"},{"phrase":"domesticate a species","zh":"驯化一个物种"},{"phrase":"domesticate a treaty","zh":"把条约转为国内法"},{"phrase":"be domesticated into","zh":"被驯化为"}],"forms":[{"label":"三单（he/she/it）","form":"domesticates"},{"label":"过去式","form":"domesticated"},{"label":"过去分词","form":"domesticated"},{"label":"现在分词","form":"domesticating"},{"label":"名词（过程）","form":"domestication"}],"derivatives":[{"word":"domestication","pos":"n.","zh":"驯化"},{"word":"domesticated","pos":"adj.","zh":"已驯化的"},{"word":"domestic","pos":"adj.","zh":"家庭的；家养的"},{"word":"domesticity","pos":"n.","zh":"家庭生活"}],"senses":[{"no":"01","title":"Tame an animal over generations","titleCN":"历经数代驯养动物","definition":"to breed and manage a wild animal population so that it lives under human care","definitionCN":"繁育并管理野生兽群，使其生活在人类照料之下","example":"People domesticated dogs long before they kept herds.","exampleCN":"人们养畜群之前很久就驯化了狗。","why":"the verb is the act behind domestication, and its object is a population rather than a single pet.","whyCN":"这个动词是驯化背后的动作，其对象是一个群体，而不是一只宠物。"},{"no":"02","title":"Turn a wild plant into a crop","titleCN":"把野生植物变成作物","definition":"to select and cultivate a wild plant until it depends on human sowing","definitionCN":"对野生植物进行选育与栽培，直到它依赖人播种","example":"Early farmers domesticated barley without knowing genetics.","exampleCN":"早期农民不懂遗传学，却驯化了二棱大麦。","why":"the plant sense repeats the animal sense at the level of seed rather than behaviour.","whyCN":"植物义在种子层面重复了动物义，而不是在行为层面。"},{"no":"03","title":"Adapt a species genetically","titleCN":"在遗传上使物种适应","definition":"to bring about inherited changes that suit a species to human environments","definitionCN":"造成可遗传的改变，使某物种适应人类环境","example":"Selective breeding domesticated the temperament as well as the body.","exampleCN":"选育既驯化了身体，也驯化了性情。","why":"when the change is heritable, taming one generation domesticates the line.","whyCN":"当改变可遗传时，驯服一代就驯化了整条线。"},{"no":"04","title":"Accustom a person to home life","titleCN":"使人习惯家庭生活","definition":"to make a person used to the routines and confines of a household","definitionCN":"使人习惯于家户的日常与范围","example":"Years of indoor work had domesticated him more than he admitted.","exampleCN":"多年室内工作使他安于家居，比他承认的更甚。","why":"the household image turns on a person, and the verb now means settling someone into domestic routine.","whyCN":"家户意象转向人，动词于是指让人安于家庭日常。"},{"no":"05","title":"Make something familiar and manageable","titleCN":"使某物变得熟悉可控","definition":"to make an unfamiliar idea, tool or practice easy to live with","definitionCN":"使陌生的想法、工具或做法易于共处","example":"The handbook domesticated a difficult theory for new staff.","exampleCN":"这本手册把一套艰深理论变得新员工也能上手。","why":"anything wild or intimidating can be brought indoors metaphorically.","whyCN":"任何野生或令人畏惧之物，都可以在比喻意义上被带进屋内。"},{"no":"06","title":"Incorporate a treaty into domestic law","titleCN":"把条约纳入国内法","definition":"in law, to give an international agreement effect within a national legal order","definitionCN":"法律上使国际协定在国内法律秩序中生效","example":"Parliament domesticated the convention by statute.","exampleCN":"议会以法规把该公约转为国内法。","why":"the international text must be brought into the house of national law before courts can apply it.","whyCN":"国际文本必须先被带进国家法律这座房子，法院才能适用。"},{"no":"07","title":"A domesticated animal, as a rare noun","titleCN":"作为罕用名词的驯化动物","definition":"rarely, a domesticated animal or plant considered as an entity","definitionCN":"罕用，指作为实体的已驯化动植物","example":"The farm keeps four domesticates and a dozen wild species.","exampleCN":"这个农场养四种驯化种和十几种野生种。","why":"English often lets a verb form double as a noun, and specialists use it for the organism itself.","whyCN":"英语常让动词形式兼作名词，专业人士用它指生物本身。"},{"no":"08","title":"Settle and work a landscape","titleCN":"定居并经营一片土地","definition":"to bring land into settled, managed use","definitionCN":"把土地纳入定居、有管理的使用","example":"The valley was domesticated by terrace builders a thousand years ago.","exampleCN":"这座山谷在一千年前被修梯田的人驯化了。","why":"if a species can be brought into the household, so can the ground it grows on.","whyCN":"既然物种能被带进家户，它生长的土地也可以。"}],"etymology":{"intro":{"en":"Domesticate comes from Latin domesticare 'to make domestic', built on domesticus 'of the household'. Dates are approximate.","cn":"domesticate 出自拉丁 domesticare「使家用、使驯服」，建于 domesticus「属于家户的」之上。年代均为约数。"},"items":[{"era":"LATIN DOMUS","en":"Domus 'house' is the base of the family. Its deeper origin is reconstructed, and the common link to a building root remains a hypothesis.","cn":"domus「房子」是整个词族的基础。其更深来源属重构，通常联系的「建造」词根仍是假说。"},{"era":"LATIN DOMESTICUS","en":"Domesticus described what belongs to a household, including animals kept indoors.","cn":"domesticus 描述属于家户之物，包括养在屋内的动物。"},{"era":"LATIN DOMESTICARE","en":"Domesticare meant 'to make domestic, to tame'; it is the direct source of the English verb.","cn":"domesticare 意为「使家用、使驯服」，是英语动词的直接来源。"},{"era":"ENGLISH VERB","en":"English domesticate is recorded in the seventeenth century, at first for animals and later for plants.","cn":"英语 domesticate 在 17 世纪有记录，先用于动物，后用于植物。"},{"era":"EXTENDED USES","en":"The verb was extended to people, tools and treaties; the legal use is recent and its first date is uncertain.","cn":"这个动词后来扩展到人、工具与条约；法律用法较晚，首见年代不确定。"}]},"similar":{"note":{"en":"The first group is the same Latin household family; the second lists other verbs of bringing something under control.","cn":"第一组是同一个拉丁「家户」词族；第二组是把某物置于控制之下的其他动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"domestic","ipa":"/dəˈmestɪk/","tag":"adjective","definition":"Of the home or of animals kept there; an adjective, where domesticate is the action.","definitionCN":"指家庭的或家养的；是形容词，domesticate 是动作。"},{"word":"domesticated","ipa":"/dəˈmestɪkeɪtɪd/","tag":"past participle","definition":"Already tamed or adapted; it reports a result, while domesticate names the doing.","definitionCN":"指已被驯化或适应；报告结果，而 domesticate 指做的动作。"},{"word":"domestication","ipa":"/dəˌmestɪˈkeɪʃən/","tag":"process noun","definition":"The whole historical process; the verb can be one step inside that process.","definitionCN":"指整个历史过程；动词可以是这个过程里的一步。"},{"word":"domesticity","ipa":"/dəmesˈtɪsəti/","tag":"home life","definition":"The state or quality of home life; it has no taming sense at all.","definitionCN":"指家庭生活的状态或性质；完全没有驯化含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tame","ipa":"/teɪm/","tag":"one animal","definition":"To make one animal calm around people; it need not change the species or its offspring.","definitionCN":"使单只动物在人前安静；不必改变物种或后代。"},{"word":"cultivate","ipa":"/ˈkʌltɪveɪt/","tag":"work the land","definition":"To prepare and tend land or plants; the labour can occur without any inherited change.","definitionCN":"整地并照料土地或植物；这种劳动可以没有可遗传的改变。"},{"word":"breed","ipa":"/briːd/","tag":"controlled mating","definition":"To mate selected animals or plants; it is the mechanism often used to domesticate.","definitionCN":"让选定的动植物交配；常是驯化所用的机制。"},{"word":"naturalise","ipa":"/ˈnætʃərəlaɪz/","tag":"settle in a new range","definition":"To establish a species in a new region; the aim is survival there, not human use.","definitionCN":"使某物种在新地区立足；目标是当地存活，而非人类利用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin house verb, the regular English endings and the objects the verb takes.","cn":"正常联想：拉丁「房子」动词、规则的英语词尾，以及这个动词常带的宾语。"},"normal":[{"en":"domesticus 'of the house' + -are 'to make' = to make something house-broken.","cn":"domesticus「属于房子」+ -are「使」= 使某物适应屋内生活。"},{"en":"The verb is regular: domesticates, domesticated, domesticated, domesticating.","cn":"这个动词规则变化：domesticates、domesticated、domesticated、domesticating。"},{"en":"Typical objects are animals, plants, species and treaties.","cn":"典型宾语是动物、植物、物种与条约。"},{"en":"The result adjective is domesticated, and the process noun is domestication.","cn":"结果形容词是 domesticated，过程名词是 domestication。"},{"en":"Domare 'to tame' looks related in meaning but is a separate Latin verb.","cn":"domare「使驯服」在意义上看似相关，却是另一个拉丁动词。"}],"abstract":[{"en":"Picture a hand pressing gently on a young animal until it stops struggling.","cn":"想象一只手轻轻按在幼兽身上，直到它不再挣扎。"},{"en":"Picture a door latch that can be opened from inside but not from outside.","cn":"想象一把门闩，从里面能开，从外面打不开。"},{"en":"Picture a wild field being taught to hold still in rows.","cn":"想象一片野地被教着站成一排排。"}]},"examples":[{"en":"Farmers domesticated rice in several river valleys independently.","cn":"农民在几处河谷各自独立地驯化了水稻。"},{"en":"You cannot domesticate a species in one lifetime.","cn":"一个物种不可能在一代人的时间里被驯化。"},{"en":"The state domesticated the agreement through a new act.","cn":"该国以一部新法把该协定转为国内法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「多麦斯提凯特」听成「多把麦子提进家」——野物提进家门，喂熟、留种，就是驯化。","word":"domesticate"},"root":"拉丁 domus「房子、家户」→ domesticus「属于家户的」→ domesticare「使家用、使驯服」，英语直接借其动词形作 domesticate。domare「使驯服」为另一动词，不与此同源。","sensesIntro":{"en":"Eight senses run from taming animals and plants through genetic adaptation, human domestication, familiarising ideas, legal incorporation, the rare noun and settled land.","cn":"八个义项从驯养动植物，经遗传适应、人的家居化、想法日常化、法律纳入、罕用名词，到土地的定居经营。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand holding a young animal while the gate is latched.","cn":"核心意象：一只手按住幼兽，另一只手扣上门闩。"},"chain":["TAME AN ANIMAL","CULTIVATE A PLANT","CHANGE THE SPECIES","SETTLE A PERSON","ABSORB A TEXT","SETTLE THE LAND"],"branches":[{"senses":"义项 01 · 02","en":"BEAST AND CROP: behaviour and seed are two handles on the same act of bringing inside.","cn":"兽与作物：行为与种子，是把同一「带进家户」动作的两个抓手。"},{"senses":"义项 03 · 07","en":"THE LINE AND THE THING: inherited change makes a lineage domestic, and the resulting organism can be counted.","cn":"谱系与个体：可遗传的改变使一条谱系家养化，其结果生物也就可以计数。"},{"senses":"义项 04","en":"THE PERSON: a human can be settled into a household as surely as an animal.","cn":"人：人也可以像动物一样被安顿进家户。"},{"senses":"义项 05","en":"THE IDEA: a difficult theory is brought indoors until ordinary people can live with it.","cn":"想法：艰深理论被带进屋内，直到普通人能与它共处。"},{"senses":"义项 06 · 08","en":"LAW AND GROUND: a treaty enters national law, and a valley enters settled use.","cn":"法律与土地：条约进入国家法，山谷进入定居使用。"}]},"affixes":{"intro":{"en":"Domesticate is a Latin household adjective plus a Latin verb ending, with English tense endings added on top.","cn":"domesticate 是拉丁「家户」形容词加拉丁动词词尾，其上又加英语时态词尾。"},"latinIntro":{"en":"Latin domus gives domicile, domestic and domesticate; the taming verb domare is a different root and should not be folded in.","cn":"拉丁 domus 给出 domicile、domestic、domesticate；表驯服的 domare 属另一词根，不应并入。"},"items":[{"word":"dom-","structure":"domus (Latin noun, 'house')","meaning":"house; household","meaningCN":"房子；家户","example":"The stem carries the idea of indoors.","exampleCN":"这个词干带着「屋内」的意思。"},{"word":"-ate","structure":"-are (Latin verb ending)","meaning":"to make, to cause","meaningCN":"使；造成","example":"The ending makes a verb of the adjective.","exampleCN":"这个结尾把形容词变成动词。"},{"word":"domesticate","structure":"domesticus + -are","meaning":"to bring under household use","meaningCN":"使纳入家用","example":"They domesticated the local grain.","exampleCN":"他们驯化了当地的谷物。"},{"word":"domesticates","structure":"domesticate + -s (third person)","meaning":"he, she or it tames","meaningCN":"他、她或它驯化","example":"The project domesticates three species.","exampleCN":"该项目驯化三个物种。"},{"word":"domesticated","structure":"domesticate + -ed","meaning":"tamed; made homely","meaningCN":"已驯化的；已家居化的","example":"The domesticated form is smaller.","exampleCN":"驯化型更小。"},{"word":"domesticating","structure":"domesticate + -ing","meaning":"in the process of taming","meaningCN":"正在驯化的","example":"Domesticating a tree takes decades.","exampleCN":"驯化一种树要几十年。"},{"word":"domestication","structure":"domesticate + -ion","meaning":"the process itself","meaningCN":"驯化过程","example":"Domestication changed the diet of the region.","exampleCN":"驯化改变了该地区的饮食。"},{"word":"domestic","structure":"domesticus through French","meaning":"of the home","meaningCN":"家庭的","example":"Domestic life settled around the hearth.","exampleCN":"家庭生活围绕炉灶展开。"},{"word":"domicile","structure":"domicilium (Latin 'dwelling')","meaning":"a place of residence","meaningCN":"住所","example":"The tax domicile is the family house.","exampleCN":"税务住所是那栋家宅。"}],"latinEntries":[{"word":"domus","structure":"Latin noun, fourth declension","meaning":"house, household","meaningCN":"房子；家户"},{"word":"domesticus","structure":"domus + -ticus","meaning":"of the household","meaningCN":"属于家户的"},{"word":"domesticare","structure":"domesticus + -are (Latin verb)","meaning":"to make domestic, tame","meaningCN":"使家用；使驯服"},{"word":"domicilium","structure":"domus + -cilium (Latin noun)","meaning":"a dwelling","meaningCN":"住所"}],"derivatives":[{"word":"redomesticate","structure":"re- (again) + domesticate","meaning":"to tame a feral population again","meaningCN":"再次驯化野化群体"},{"word":"domesticable","structure":"domesticate + -able","meaning":"capable of being tamed","meaningCN":"可被驯化的"}]}},{"word":"domesticated","ipa_uk":"/dəˈmestɪkeɪtɪd/","ipa_us":"/dəˈmestɪkeɪtɪd/","definition_zh":"已驯化的；家养的；栽培的；安于家庭生活的","definition_en":"tamed and kept by people, or adapted to household life","core_image":"一只狗不挖洞、不守食，只在炉边等一只手落下，皮毛上的斑块是几代人挑出来的","scene":"院里的狗不再冲着陌生人叫，The domesticated dog sleeps by the stove instead of digging a den.","sceneCN":"这里 domesticated 指「已被人类驯养、依赖人的」（第 1 个义项：动物已家养化）；句意为这只家养的狗睡在炉边，而不再去挖洞穴。图中可辨识物件：炉边草垫、蜷睡的狗、没有掘土的爪、屋门。","pos":[{"tag":"adj.","zh":"已驯化的；家养的；栽培的；安于家居的"}],"collocations":[{"phrase":"domesticated animals","zh":"家养动物"},{"phrase":"domesticated plants","zh":"栽培植物"},{"phrase":"a domesticated breed","zh":"家养品种"},{"phrase":"domesticated forms of wheat","zh":"小麦的栽培型"},{"phrase":"become domesticated","zh":"变得安于家居"}],"forms":[{"label":"比较级","form":"more domesticated"},{"label":"最高级","form":"most domesticated"},{"label":"动词原形","form":"domesticate"},{"label":"名词（过程）","form":"domestication"}],"derivatives":[{"word":"domesticate","pos":"v.","zh":"驯化"},{"word":"domestication","pos":"n.","zh":"驯化"},{"word":"domestic","pos":"adj.","zh":"家庭的；家养的"},{"word":"semidomesticated","pos":"adj.","zh":"半驯化的"}],"senses":[{"no":"01","title":"An animal tamed and kept","titleCN":"被驯养并饲养的动物","definition":"describing an animal that has been tamed and lives under human care","definitionCN":"形容已被驯服、生活在人类照料下的动物","example":"The domesticated herd returns to the same pen every evening.","exampleCN":"这群家养牲畜每晚回到同一个圈里。","why":"the participle reports a finished change, so the animal is described by what has already happened to its line.","whyCN":"分词报告一个已完成的变化，因此这只动物是由其谱系已经历的事来描述的。"},{"no":"02","title":"A plant brought into cultivation","titleCN":"被纳入栽培的植物","definition":"describing a plant that depends on sowing and tending by people","definitionCN":"形容依赖人类播种与照料的植物","example":"The domesticated wheat has a brittle-free rachis that keeps the ear intact.","exampleCN":"栽培小麦的穗轴不易折断，使整穗保持完整。","why":"the same participle covers plants, because cultivation is the botanical form of keeping something in the house.","whyCN":"同一个分词也覆盖植物，因为栽培是「养在屋里」在植物学上的形式。"},{"no":"03","title":"Genetically adapted to people","titleCN":"在遗传上适应了人类","definition":"describing inherited traits that fit a species to human environments","definitionCN":"形容使物种适应人类环境的可遗传性状","example":"The domesticated strain digests starch more easily than its wild cousin.","exampleCN":"栽培品系比野生近亲更容易消化淀粉。","why":"once selection is repeated across generations, the adaptation sits in the genes and can be described as a state.","whyCN":"当选择跨代重复，适应便落在基因里，可以被描述为一种状态。"},{"no":"04","title":"A person settled into home life","titleCN":"安于家庭生活的人","definition":"describing a person who has grown used to domestic routines and indoor comfort","definitionCN":"形容已习惯于家庭日常与室内舒适的人","example":"He became domesticated after two winters of desk work.","exampleCN":"两冬的案头工作之后，他变得安于家居。","why":"the animal image turns on people with a mild irony: home has tamed them too.","whyCN":"动物的意象带着淡淡反讽转到人身上：家也把他们驯服了。"},{"no":"05","title":"Made tame or harmless","titleCN":"被磨平、变得无害","definition":"figuratively, describing something once dangerous or wild that has been made safe","definitionCN":"比喻形容曾经危险或野性之物已被变得安全","example":"The domesticated storm scene lost its violence in the film version.","exampleCN":"在电影版本里，那场被驯化的暴风雨失去了暴烈。","why":"if a beast can be domesticated, so can an image, a style or an argument.","whyCN":"兽可以被驯化，意象、风格或论点也可以。"},{"no":"06","title":"Land brought under settled use","titleCN":"被纳入定居经营的土地","definition":"describing a landscape converted to fields, terraces or managed pasture","definitionCN":"形容已被改为田地、梯田或管理牧场的景观","example":"The domesticated slope holds soil that the wild slope lost.","exampleCN":"被驯化的坡面留住了野坡已经流失的土。","why":"a landscape can be described by the same participle because it has been brought into the human household.","whyCN":"景观也能用同一个分词描述，因为它已被带进人类的家户。"},{"no":"07","title":"A treaty incorporated into domestic law","titleCN":"已转为国内法的条约","definition":"in law, describing an international agreement given effect in national law","definitionCN":"法律上形容已在国家法中生效的国际协定","example":"The domesticated convention can now be cited in national courts.","exampleCN":"这份已国内法化的公约如今可在本国法院援引。","why":"the legal participle repeats the household image: the text has been moved inside.","whyCN":"法律分词重复了家户意象：文本已被搬进屋内。"},{"no":"08","title":"House-trained in informal use","titleCN":"口语中「规规矩矩的」","definition":"informal, describing a person or animal that behaves well indoors","definitionCN":"口语形容在人前或室内举止得体的","example":"The puppy is domesticated enough to sleep indoors.","exampleCN":"这只小狗已经规矩到可以睡在屋里了。","why":"the oldest household sense survives as a joke about indoor manners.","whyCN":"最古老的家户义以关于室内举止的玩笑方式留存下来。"}],"etymology":{"intro":{"en":"Domesticated is the past participle of domesticate, from Latin domesticare, built on domus 'house'. Dates are approximate.","cn":"domesticated 是 domesticate 的过去分词，动词出自拉丁 domesticare，建于 domus「房子」之上。年代均为约数。"},"items":[{"era":"LATIN DOMUS","en":"Domus meant 'house, household'; its pre-Latin base is reconstructed, and the link to a building root is a hypothesis.","cn":"domus 意为「房子、家户」；其拉丁语之前的词基属重构，与「建造」词根的联系只是假说。"},{"era":"LATIN DOMESTICUS","en":"Domesticus 'of the household' described people, animals and objects belonging to a house.","cn":"domesticus「属于家户的」可描述属于一户的人、动物与物件。"},{"era":"LATIN DOMESTICARE","en":"Domesticare 'to make domestic, tame' supplied the English verb and therefore this participle.","cn":"domesticare「使家用、使驯服」提供英语动词，因而也提供这个分词。"},{"era":"ENGLISH PARTICIPLE","en":"The English participle domesticated is recorded from the seventeenth century, first of animals.","cn":"英语分词 domesticated 自 17 世纪有记录，最初用于动物。"},{"era":"EXTENDED ADJECTIVE","en":"Later it described plants, people, landscapes and treaties; the informal house-trained sense is nineteenth-century and its first date is uncertain.","cn":"后来它描述植物、人、景观与条约；口语「规矩」义属 19 世纪，首见年代不确定。"}]},"similar":{"note":{"en":"The first group is the same household family in adjective form; the second lists adjectives for organisms or people under human control.","cn":"第一组是同一个「家户」词族的形容词形态；第二组是形容受人类控制的生物或人的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"domestic","ipa":"/dəˈmestɪk/","tag":"broader adjective","definition":"Of the home in general; a domestic cat is kept indoors, but domestic also covers chores, flights and politics.","definitionCN":"泛指家庭的；家猫是养在屋内的，但 domestic 也用于家务、航班与政治。"},{"word":"domesticate","ipa":"/dəˈmestɪkeɪt/","tag":"the verb","definition":"The act of taming; the participle describes the result of that act.","definitionCN":"指驯化的动作；分词描述该动作的结果。"},{"word":"domestication","ipa":"/dəˌmestɪˈkeɪʃən/","tag":"the process","definition":"The long historical process; the participle is the state at the end of it.","definitionCN":"指漫长的历史过程；分词是过程终点的状态。"},{"word":"domesticity","ipa":"/dəmesˈtɪsəti/","tag":"home life","definition":"The quality of home life; it does not describe tamed animals.","definitionCN":"指家庭生活的性质；不形容被驯化的动物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tame","ipa":"/teɪm/","tag":"calm around people","definition":"Describing an animal that is not afraid of people; it can be true of one individual and need not be inherited.","definitionCN":"形容不怕人的动物；可以只对个体成立，不必可遗传。"},{"word":"cultivated","ipa":"/ˈkʌltɪveɪtɪd/","tag":"plant parallel","definition":"Describing land or plants that are tended; it stresses labour rather than inherited change.","definitionCN":"形容受照料的地或植物；强调劳动，而非可遗传的改变。"},{"word":"household","ipa":"/ˈhaʊshəʊld/","tag":"the unit, not the state","definition":"Belonging to a home as a social unit; it names the unit, not the tamed condition.","definitionCN":"指作为社会单位的家庭；指单位，而非被驯化的状态。"},{"word":"naturalized","ipa":"/ˈnætʃərəlaɪzd/","tag":"established in a new range","definition":"Describing a species established in a new region; it may be wild there and still be called naturalized.","definitionCN":"形容在新地区立足的物种；在那里可能仍是野生的，却也称 naturalized。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the participle ending, the household core and the nouns it most often modifies.","cn":"正常联想：分词词尾、家户核心，以及它最常修饰的名词。"},"normal":[{"en":"domesticate + -ed = the state after taming, as in a domesticated breed.","cn":"domesticate + -ed = 驯化之后的状态，如家养品种。"},{"en":"The word often sits before animals, plants, breeds and forms.","cn":"这个词常放在 animals、plants、breeds、forms 之前。"},{"en":"The base domus 'house' explains why the word also means house-trained.","cn":"词基 domus「房子」解释了它为什么也有「屋内规矩」的意思。"},{"en":"Compare the chain: domesticate, domesticated, domestication.","cn":"比较这条链：domesticate、domesticated、domestication。"},{"en":"The adjective is gradable: more domesticated, most domesticated.","cn":"这个形容词可分级，可以说「更驯化」「最驯化」。"}],"abstract":[{"en":"Picture a paw that has forgotten how to dig.","cn":"想象一只爪子，已经忘了怎么刨土。"},{"en":"Picture a coat with patches that were chosen by people, not by weather.","cn":"想象一身斑块毛色，是人挑出来的，而不是天气挑的。"},{"en":"Picture a field whose soil stays put because a wall was built for it.","cn":"想象一片田，土不再流失，因为有人为它砌了墙。"}]},"examples":[{"en":"Domesticated animals usually have smaller teeth than their wild relatives.","cn":"家养动物的牙通常比野生近亲更小。"},{"en":"The domesticated varieties ripen together, which suits machine harvest.","cn":"栽培品种同时成熟，适合机械收割。"},{"en":"After a year indoors he had become thoroughly domesticated.","cn":"在室内待了一年后，他已完全安于家居生活。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「多麦斯提凯提德」后半的「提德」听成「提进屋的」——已经被提进屋、喂熟了的，就是已驯化的。","word":"domesticated"},"root":"动词 domesticate 出自拉丁 domesticare「使家用、使驯服」，其基础是 domus「房子、家户」所生的 domesticus。过去分词 -ed 表示「已处于该状态」。","sensesIntro":{"en":"Eight senses describe results: tamed animals, cultivated plants, genetic adaptation, settled people, harmless versions of wild things, managed land, incorporated treaties and indoor manners.","cn":"八个义项都在描述结果：家养动物、栽培植物、遗传适应、安于家居的人、被磨平的野性、被经营的土地、已纳入的条约、室内举止。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dog asleep by the stove with paws that no longer dig.","cn":"核心意象：一只狗睡在炉边，爪子已不再刨土。"},"chain":["TAMED ANIMAL","CULTIVATED PLANT","INHERITED ADAPTATION","SETTLED PERSON","HARMLESS VERSION","MANAGED LAND"],"branches":[{"senses":"义项 01 · 03","en":"ANIMAL AND GENES: the tame individual and the adapted line are the same result at two depths.","cn":"动物与基因：温顺的个体与适应的谱系，是同一结果的两个深度。"},{"senses":"义项 02","en":"PLANT: cultivation produces a plant that cannot sow itself.","cn":"植物：栽培产生一种无法自行播种的植物。"},{"senses":"义项 04 · 08","en":"PERSON AND MANNERS: a settled adult and a house-trained puppy share the household image.","cn":"人与举止：安于家居的成年人与守规矩的幼犬共享家户意象。"},{"senses":"义项 05","en":"SOFTENED WILDNESS: images and styles can be made harmless too.","cn":"被磨平的野性：意象与风格也可以被变得无害。"},{"senses":"义项 06 · 07","en":"GROUND AND LAW: a slope and a treaty are both brought inside a managed order.","cn":"土地与法律：坡地与条约都被带进一种受管理的秩序。"}]},"affixes":{"intro":{"en":"Domesticated is a Latin household verb with an English past-participle ending used as an adjective.","cn":"domesticated 是拉丁「家户」动词加英语过去分词词尾，并作形容词使用。"},"latinIntro":{"en":"The Latin base domus also yields domicile and domestic; the tame verb domare is a separate root and only looks related.","cn":"拉丁词基 domus 还衍生 domicile 与 domestic；表驯服的 domare 属另一词根，只是看起来相关。"},"items":[{"word":"dom-","structure":"domus (Latin noun, 'house')","meaning":"house; household","meaningCN":"房子；家户","example":"The stem explains the indoor sense.","exampleCN":"这个词干解释了「屋内」义。"},{"word":"domestic-","structure":"domesticus (Latin adjective)","meaning":"of the household","meaningCN":"属于家户的","example":"The adjective supplies the base of the verb.","exampleCN":"这个形容词提供动词的基础。"},{"word":"-ed","structure":"-ed (English past participle)","meaning":"having undergone","meaningCN":"已经历……的","example":"The ending reports a completed change.","exampleCN":"这个结尾报告已完成的变化。"},{"word":"domesticate","structure":"domesticus + -are","meaning":"to tame","meaningCN":"驯化","example":"They domesticate local millet.","exampleCN":"他们驯化当地小米。"},{"word":"domesticated","structure":"domesticate + -ed","meaning":"already tamed","meaningCN":"已驯化的","example":"Domesticated bees are kept in hives.","exampleCN":"家养蜜蜂养在蜂箱里。"},{"word":"domestication","structure":"domesticate + -ion","meaning":"the process of taming","meaningCN":"驯化过程","example":"Domestication preceded cities.","exampleCN":"驯化早于城市出现。"},{"word":"semidomesticated","structure":"semi- (half) + domesticated","meaning":"partly tamed","meaningCN":"半驯化的","example":"Semidomesticated reindeer still migrate.","exampleCN":"半驯化的驯鹿仍会迁徙。"},{"word":"domestic","structure":"domesticus through French","meaning":"of the home","meaningCN":"家庭的","example":"Domestic chores filled the morning.","exampleCN":"家务占满了上午。"},{"word":"domesticity","structure":"domestic + -ity","meaning":"home life","meaningCN":"家庭生活","example":"The painting celebrates domesticity.","exampleCN":"这幅画赞美家庭生活。"}],"latinEntries":[{"word":"domus","structure":"Latin noun, fourth declension","meaning":"house, household","meaningCN":"房子；家户"},{"word":"domesticus","structure":"domus + -ticus","meaning":"of the household","meaningCN":"属于家户的"},{"word":"domesticare","structure":"domesticus + -are (Latin verb)","meaning":"to make domestic, tame","meaningCN":"使家用；使驯服"}],"derivatives":[{"word":"undomesticated","structure":"un- (not) + domesticated","meaning":"still wild","meaningCN":"仍为野生的"},{"word":"domesticatedness","structure":"domesticated + -ness","meaning":"the state of being tame","meaningCN":"被驯化的状态"}]}},{"word":"pastoral","ipa_uk":"/pɑːˈstɔːrəl/","ipa_us":"/ˈpæstərəl/","definition_zh":"畜牧的；牧羊的；田园的；牧歌式的；牧师的；田园诗","definition_en":"relating to shepherds or country life, or to the care of a religious congregation","core_image":"一道石墙围着草坡，羊群散在墙内，墙外的城市只剩一条模糊的边","scene":"清晨的坡地上羊群散开，A pastoral valley keeps its shepherds and its dry stone walls.","sceneCN":"这里 pastoral 指「与牧羊、畜牧相关的」（第 1 个义项：畜牧的）；句意为这座牧歌式的山谷仍保留着牧人与干砌石墙。图中可辨识物件：干砌石墙、羊群、牧杖、远处城市的轮廓。","pos":[{"tag":"adj.","zh":"畜牧的；田园的；牧歌式的；牧灵的"},{"tag":"n.","zh":"田园诗；牧歌"}],"collocations":[{"phrase":"pastoral farming","zh":"畜牧农业"},{"phrase":"pastoral landscape","zh":"田园景观"},{"phrase":"pastoral poetry","zh":"田园诗"},{"phrase":"pastoral care","zh":"牧灵关怀"},{"phrase":"pastoral letter","zh":"主教牧函"},{"phrase":"pastoral lease","zh":"牧区租地"}],"forms":[{"label":"复数（名词：牧歌）","form":"pastorals"},{"label":"比较级","form":"more pastoral"},{"label":"最高级","form":"most pastoral"},{"label":"名词（畜牧者）","form":"pastoralist"}],"derivatives":[{"word":"pastor","pos":"n.","zh":"牧师；牧人"},{"word":"pasture","pos":"n./v.","zh":"牧场；放牧"},{"word":"pastoralism","pos":"n.","zh":"畜牧主义；畜牧生活"},{"word":"pastoralist","pos":"n.","zh":"畜牧者"}],"senses":[{"no":"01","title":"Relating to sheep and cattle farming","titleCN":"与牧羊、畜牧相关的","definition":"concerned with the grazing of livestock rather than with crops","definitionCN":"与放牧牲畜有关，而非与种植作物有关","example":"Pastoral land here is too dry for wheat and too steep for ploughs.","exampleCN":"这里的牧地太干种不了麦，太陡使不了犁。","why":"pastor is Latin for shepherd, so the first sense is the working sense: everything to do with grazing animals.","whyCN":"pastor 是拉丁语「牧人」，因此第一个义项是干活的义：一切与放牧牲畜有关的事。"},{"no":"02","title":"An idealised countryside","titleCN":"理想化的田园","definition":"describing a peaceful rural scene imagined as simple and harmonious","definitionCN":"形容被想象为朴素和谐的宁静乡野景象","example":"The brochure sells a pastoral image of village life.","exampleCN":"宣传册贩卖一种田园式的乡村生活形象。","why":"town writers looked at herding country and saw peace, so the working word acquired a glow it did not have for the herders.","whyCN":"城里的写作者看着牧区，看到了安宁，于是这个干活用的词多了一层牧人自己感受不到的光晕。"},{"no":"03","title":"A literary and artistic mode","titleCN":"文学与艺术中的牧歌体裁","definition":"belonging to poems, plays, music or paintings that treat shepherd life as a theme","definitionCN":"属于以牧人生活为主题的诗歌、戏剧、音乐或绘画","example":"The pastoral tradition puts shepherds into a golden weather that never rains.","exampleCN":"牧歌传统把牧人放进一个从不下雨的金色天气里。","why":"the idealised countryside became a genre with set conventions, and the adjective names the genre.","whyCN":"理想化的乡野变成有固定套路的体裁，形容词便用来命名这一体裁。"},{"no":"04","title":"Care of a congregation","titleCN":"对会众的牧灵关怀","definition":"in religion, relating to the guidance and care a minister gives to people","definitionCN":"宗教中指牧师对人所给予的引导与照顾","example":"Pastoral care includes visiting the sick and the lonely.","exampleCN":"牧灵关怀包括探访病人与孤独者。","why":"the Latin shepherd was applied to clergy, so the same adjective covers looking after a flock of people.","whyCN":"拉丁语「牧人」被用在神职人员身上，因此同一个形容词也指照料一群「羊」。"},{"no":"05","title":"A bishop's letter to the faithful","titleCN":"主教致信众的牧函","definition":"a formal letter from a bishop or church leader to the people of a diocese","definitionCN":"主教或教会领袖写给教区信众的正式书信","example":"The pastoral letter asked parishes to shelter refugees.","exampleCN":"这封牧函要求各堂区收容难民。","why":"a letter that shepherds the readers borrows the adjective of shepherding.","whyCN":"一封「牧养」读者的信，借用了牧养的形容词。"},{"no":"06","title":"A grazing lease in Australian usage","titleCN":"澳大利亚用法中的牧区租地","definition":"in Australia, land leased from the state for grazing livestock","definitionCN":"澳大利亚指从国家租来放牧牲畜的土地","example":"The family held a pastoral lease of forty thousand hectares.","exampleCN":"这家人持有一份四万公顷的牧区租地。","why":"Australian land law named vast dry grazing blocks pastoral, and the adjective became a legal category.","whyCN":"澳大利亚土地法把大片干旱牧地称作 pastoral，形容词于是成了法律类别。"},{"no":"07","title":"Herding that moves with the seasons","titleCN":"随季节移动的畜牧","definition":"describing a herding system that moves animals between seasonal pastures","definitionCN":"形容在季节草场之间移动牲畜的畜牧制度","example":"Pastoral nomadism survives where fields cannot be irrigated.","exampleCN":"在无法灌溉的地方，畜牧游牧仍然存续。","why":"the adjective combines with nomadism to name the oldest form of livestock keeping.","whyCN":"这个形容词与 nomadism 组合，用来命名最古老的养畜形式。"},{"no":"08","title":"A poem about shepherd life","titleCN":"描写牧人生活的诗","definition":"a poem or musical piece in the shepherd convention","definitionCN":"采用牧人套路的诗或乐曲","example":"He wrote three pastorals before he ever saw a sheep.","exampleCN":"他还没见过一只羊，就写了三首牧歌。","why":"the adjective became a noun for the work itself, a common shift in the language of genres.","whyCN":"这个形容词变成指作品本身的名词，这在体裁语汇里很常见。"}],"etymology":{"intro":{"en":"Pastoral comes from Latin pastoralis, from pastor 'shepherd', built on pascere 'to feed, graze'. Dates are approximate.","cn":"pastoral 出自拉丁 pastoralis，再上为 pastor「牧人」，建于 pascere「喂养、放牧」之上。年代均为约数。"},"items":[{"era":"LATIN PASCERE","en":"Pascere meant 'to feed, graze'. Its deeper origin is not fully established; the usual link to a root meaning 'to feed' is reconstructed.","cn":"pascere 意为「喂养、放牧」。其更深来源未有定论；通常与意为「喂养」的词根相联系，那属重构。"},{"era":"LATIN PASTOR","en":"Pastor meant 'herdsman, shepherd', literally 'one who feeds'.","cn":"pastor 意为「牧人、牧羊人」，字面是「喂养者」。"},{"era":"LATIN PASTORALIS","en":"Pastoralis meant 'of a shepherd or of shepherding', used of songs, gifts and duties connected with herds.","cn":"pastoralis 意为「牧人的、牧养的」，用于与牲畜相关的歌、礼物与职责。"},{"era":"CHRISTIAN USE","en":"The image of the shepherd was applied to clergy, so pastoral acquired the sense of caring for a congregation.","cn":"牧人的意象被用在神职人员身上，pastoral 因此获得「照料会众」的意思。"},{"era":"ENGLISH LITERARY USE","en":"English poets of the sixteenth century took pastoral for the shepherd genre, and the idealised countryside followed.","cn":"16 世纪英语诗人用 pastoral 指牧歌体裁，理想化的乡野义随之而来。"},{"era":"COLONIAL LAND USE","en":"Settler land law in Australia named large grazing leases pastoral; the legal sense is dated to the nineteenth century.","cn":"澳大利亚移民土地法把大片放牧租地称作 pastoral；这一法律义可定在 19 世纪。"}]},"similar":{"note":{"en":"The first group shares the Latin shepherd and grazing words; the second names the rural and literary qualities pastoral suggests.","cn":"第一组共用拉丁「牧人」「放牧」词；第二组是 pastoral 所暗示的田园与文学品质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pastor","ipa":"/ˈpɑːstə/","tag":"the person","definition":"A minister or, literally, a shepherd; the noun for the person where pastoral is the adjective.","definitionCN":"指牧师，字面为牧人；是指人的名词，pastoral 是对应的形容词。"},{"word":"pasture","ipa":"/ˈpɑːstʃə/","tag":"the ground","definition":"Grassland used for grazing, or to graze it; it names the place or the act, not the style.","definitionCN":"指用于放牧的草地，或放牧这块地；指地点或动作，而非风格。"},{"word":"pastoralism","ipa":"/ˈpɑːstərəlɪzəm/","tag":"the system","definition":"The branch of farming based on grazing herds; a noun for the economy, not an adjective for a scene.","definitionCN":"指以放牧畜群为基础的农业分支；是经济的名词，不是景象的形容词。"},{"word":"pastoralist","ipa":"/ˈpɑːstərəlɪst/","tag":"the herder","definition":"A person who keeps grazing livestock; the human noun, not the literary genre.","definitionCN":"指养放牧牲畜的人；是指人的名词，不是文学体裁。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bucolic","ipa":"/bjuːˈkɒlɪk/","tag":"literary countryside","definition":"Charmingly rural in a literary way, from Greek for a herdsman; it is almost always a stylistic word.","definitionCN":"指带文学味的迷人乡野，出自希腊语「牧人」；几乎总是风格用词。"},{"word":"idyllic","ipa":"/aɪˈdɪlɪk/","tag":"perfectly peaceful","definition":"Describing a scene of perfect peace and simplicity; it can apply to any place, not only herding country.","definitionCN":"形容完美宁静朴素的景象；可用于任何地方，不限牧区。"},{"word":"rural","ipa":"/ˈrʊərəl/","tag":"the plain fact","definition":"Of the countryside; a neutral word with no idealisation and no herds.","definitionCN":"指乡下的；中性词，不含理想化，也不含畜群。"},{"word":"agrarian","ipa":"/əˈɡreəriən/","tag":"land and farming","definition":"Relating to land ownership or farming, usually crops; it is about tenure and production, not scenery.","definitionCN":"指与土地所有权或农耕（通常指作物）相关的；讲的是权属与生产，不是风景。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin grazing verb, the family it built and the double life of the word in church and literature.","cn":"正常联想：拉丁「放牧」动词、它构成的词族，以及这个词在教会与文学中的双重生活。"},"normal":[{"en":"pascere 'to graze' + -tor 'one who' = pastor, a feeder of animals; pastoral is its adjective.","cn":"pascere「放牧」+ -tor「做……的人」= pastor，喂养牲畜的人；pastoral 是其形容词。"},{"en":"The family runs pastor, pasture, pastoral, pastoralism and pastoralist.","cn":"词族包括 pastor、pasture、pastoral、pastoralism、pastoralist。"},{"en":"The church sense keeps the sheep metaphor: pastoral care, pastoral letter, pastoral visit.","cn":"教会义保留羊的比喻：牧灵关怀、牧函、牧灵探访。"},{"en":"The literary sense keeps the golden weather: pastoral poetry, pastoral scene, pastoral elegy.","cn":"文学义保留金色天气：田园诗、田园场景、田园挽歌。"},{"en":"In Australia a pastoral lease is a legal category of grazing land.","cn":"在澳大利亚，「牧区租约」是放牧土地的一个法律类别。"}],"abstract":[{"en":"Picture a stone wall that exists only to keep sheep in and the city out.","cn":"想象一道石墙，唯一的作用是把羊拦住、把城市挡在外面。"},{"en":"Picture a shepherd's crook that is also a bishop's staff.","cn":"想象一根牧羊杖，同时也是主教的手杖。"},{"en":"Picture a poem written about a field the poet has never walked.","cn":"想象一首诗写的是诗人从未走过的田野。"}]},"examples":[{"en":"The region shifted from pastoral use to irrigated horticulture.","cn":"该地区从畜牧用地转为灌溉园艺。"},{"en":"Pastoral novels rarely mention the smell of a wet fleece.","cn":"田园小说很少提到湿羊毛的气味。"},{"en":"The bishop's pastoral letter was read from every pulpit.","cn":"主教的牧函在每个讲道坛上被宣读。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「帕斯托罗」听成「怕石多罗」——坡上石头多，羊却偏要在石缝里找草，这就是牧羊的田园。pastor 是牧人，pastoral 是牧人的。","word":"pastoral"},"root":"拉丁 pastor「牧人」出自 pascere「喂养、放牧」，加 -alis 成 pastoralis「牧人的」；经法语进入英语。基督教把牧人意象用于神职，文学把它用于牧歌体裁，澳大利亚土地法把它用于牧区租地。","sensesIntro":{"en":"Eight senses divide between the working herd and the imagined countryside, then add church care, a bishop's letter, a grazing lease, seasonal herding and the poem itself.","cn":"八个义项分布在「干活的畜群」与「想象中的乡野」两侧，再加教会牧养、主教书信、牧区租地、季节畜牧与诗作本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dry stone wall holding sheep inside and the city outside.","cn":"核心意象：一道干砌石墙，把羊拦在里面，把城市挡在外面。"},"chain":["GRAZING LAND","IDEAL COUNTRYSIDE","SHEPHERD GENRE","CONGREGATION CARE","BISHOP'S LETTER","GRAZING LEASE"],"branches":[{"senses":"义项 01 · 07","en":"WORKING HERD: settled pasture and seasonal movement are the two practical forms of the same grazing economy.","cn":"干活的畜群：定居牧场与季节移动，是同一畜牧经济的两种实际形态。"},{"senses":"义项 02 · 03 · 08","en":"THE IMAGINED COUNTRY: the idealised scene, the genre and the poem are one literary construction at three stages.","cn":"想象的乡野：理想景象、体裁与诗作，是同一文学建构的三个阶段。"},{"senses":"义项 04","en":"THE FLOCK OF PEOPLE: clergy inherit the shepherd image and care for a congregation instead of sheep.","cn":"人的羊群：神职继承了牧人意象，照料的是会众而非羊。"},{"senses":"义项 05","en":"THE LETTER: a bishop writes to shepherd his readers.","cn":"书信：主教写信以牧养他的读者。"},{"senses":"义项 06","en":"THE LEASE: colonial land law turns the adjective into a legal category of vast dry grazing blocks.","cn":"租地：殖民地土地法把这个形容词变成大片干旱牧地的法律类别。"}]},"affixes":{"intro":{"en":"Pastoral is a Latin noun of the shepherd plus a Latin adjective ending; the same stem also built pasture and pastor.","cn":"pastoral 是拉丁「牧人」名词加拉丁形容词词尾；同一词干还构成 pasture 与 pastor。"},"latinIntro":{"en":"Latin pascere 'to graze' also gives pasture, repast and pabulum, all connected with feeding.","cn":"拉丁 pascere「放牧」还给出 pasture、repast、pabulum，都与喂养有关。"},"items":[{"word":"pasc-","structure":"pascere (Latin verb, 'to feed, graze')","meaning":"to feed; to graze","meaningCN":"喂养；放牧","example":"The stem supplies the feeding image behind the whole family.","exampleCN":"这个词干提供整个词族背后的「喂养」意象。"},{"word":"pastor","structure":"pascere + -tor (one who feeds)","meaning":"a herdsman; a minister","meaningCN":"牧人；牧师","example":"The word moved from sheep to souls.","exampleCN":"这个词从羊群移到了灵魂。"},{"word":"-al","structure":"-alis (Latin adjective ending)","meaning":"relating to","meaningCN":"与……相关的","example":"The ending makes pastoralis 'of the shepherd'.","exampleCN":"这个结尾构成 pastoralis「牧人的」。"},{"word":"pastoral","structure":"pastor + -al","meaning":"of shepherds or country life","meaningCN":"牧人的；田园的","example":"Pastoral scenes filled the gallery.","exampleCN":"画廊里挂满了田园场景。"},{"word":"pasture","structure":"pascere, past participle pastus","meaning":"grazing land; to graze","meaningCN":"牧场；放牧","example":"The herd moved to summer pasture.","exampleCN":"畜群转到夏季牧场。"},{"word":"pastoralism","structure":"pastoral + -ism","meaning":"a herding economy or its advocacy","meaningCN":"畜牧经济或其主张","example":"Pastoralism shaped the region's law.","exampleCN":"畜牧经济塑造了该地区的法律。"},{"word":"pastoralist","structure":"pastoral + -ist","meaning":"one who keeps grazing livestock","meaningCN":"畜牧者","example":"Pastoralists moved before the rains.","exampleCN":"畜牧者在雨季前迁移。"},{"word":"pastorally","structure":"pastoral + -ly","meaning":"in a rural or shepherd manner","meaningCN":"以田园方式地","example":"The valley is pastorally quiet.","exampleCN":"这座山谷有田园式的安静。"},{"word":"repast","structure":"re- + pascere (Latin repascere)","meaning":"a meal","meaningCN":"一餐","example":"The word literally meant feeding again.","exampleCN":"这个词字面意为「再喂一次」。"}],"latinEntries":[{"word":"pascere","structure":"Latin verb, third conjugation","meaning":"to feed, pasture, graze","meaningCN":"喂养；放牧"},{"word":"pastor","structure":"pascere + -tor","meaning":"herdsman, shepherd","meaningCN":"牧人；牧羊人"},{"word":"pastoralis","structure":"pastor + -alis","meaning":"of a shepherd","meaningCN":"牧人的"},{"word":"pastio","structure":"pascere + -tio (Latin noun)","meaning":"a pasturing, grazing","meaningCN":"放牧"}],"derivatives":[{"word":"pastorals","structure":"pastoral + -s (plural)","meaning":"several shepherd poems","meaningCN":"多首牧歌"},{"word":"pastoralness","structure":"pastoral + -ness","meaning":"the quality of being rural and calm","meaningCN":"田园宁静的性质"}]}}]);
